-- GENERATED by `wfj generate` from data/quest/quest-0003.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [3000] = { "⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Tiza Battleforge a ⟦Ironforge=Forgiardente⟧.", "Salve, {name}. So che sei impegnat<o/a> ad aiutare la gente di Azeroth, ma quando hai tempo dovresti tornare a ⟦Ironforge=Forgiardente⟧ e parlare con uno dei paladini più rispettati della tua patria: Tiza Battleforge. È da lei che vanno i giovani paladini nanici quando è il momento di imparare di più sulla Luce e su cosa ci si aspetta da tutti noi.\n\nLa trovi al piano di sopra, nella Hall of Mysteries, che si trova nel Mystic Ward.", nil, "Ti saluto e ti do il benvenuto, {name}.", 0x85861feb, 0x04be03fc, 0x3dc4f4ac, nil, 0x35f6641b, "...m." },
  [3001] = { "In cerca di Strahad", "Trova Strahad Farsan a ⟦Ratchet=Porto Paranco⟧.", "In passato ti ho insegnato delle abilità, ma è giunto il momento che sia un altro a istruirti. Si trova a ⟦Ratchet=Porto Paranco⟧ e il suo nome è Strahad. È umano, ma non lasciarti ingannare: non è debole, né è tuo nemico... almeno per ora. È potente e va rispettato. Può insegnarti evocazioni superiori, evocazioni per cui ti sento pront<o/a>. Va' da lui, ora.\n\nLo troverai a ⟦Ratchet=Porto Paranco⟧... sopra la città portuale, accanto alla torre.", nil, "Una giornata piena a ⟦Ratchet=Porto Paranco⟧, vero? Quanto mi piace osservare la fatica di una città portuale. Tanto mistero, tanta avventura... tanta ignoranza.\n\nÈ odio quello che vedo nei tuoi occhi, {name}? Bene, lo metteremo a frutto.", 0x884bfbbe, 0x8ee66c11, 0xb6f535c4, nil, 0x44d961f5, "...m." },
  [3002] = { "Il ⟦Gordunni Orb=Globo Gordunni⟧", "Porta il ⟦Gordunni Orb=Globo Gordunni⟧ a Uthel'nay, nella Darkbriar Lodge di Orgrimmar.", "Conosco bene il mio nemico, ma sono un guerriero, {name}. Non saprei nemmeno da dove cominciare a dirti di cosa sia capace questo globo.\n\nConosco un mago a Orgrimmar che saprà dirci di più sul globo. Portalo a lui.", "Che cosa mi hai portato, {race}?", "Affascinante, {name}...\n\nQuesto globo è molto potente, ma anche molto pericoloso.", 0xe3823ff5, 0xeb70cf0b, 0x72c4d28d, 0xfb96e30e, 0xd7de6a56, "....." },
  [3022] = { "Maneggiare con cura", "Porta la Carefully-packed Crate a Erelas Ambersky, a ⟦Rut'theran Village=Rut'theran⟧.", "{name}, vedo che desideri dedicarti alla mia nobile causa. Sì, certo, puoi fare qualcosa per me!\n\nPorta questa cassa di uova a Erelas Ambersky. È un druido che si prende cura di queste uova, le aiuta a schiudersi e poi addestra i giovani ippogrifi. Lo troverai a Teldrassil, in un piccolo villaggio a sud chiamato Rut'theran.", "Un'altra spedizione da parte di Curgle, immagino?", "Grazie del tuo aiuto, {name}. Senza di noi la popolazione degli ippogrifi semplicemente non prospererebbe. Ah, ma sono certo che lo capisci fin troppo bene, visto che sei stat<o/a> a Feralas e hai visto la devastazione che vi hanno portato i Gordunni.\n\nBe', come vedi qui sono molto impegnato, quindi faresti meglio a rimetterti in cammino.\n\nGrazie ancora, {name}.", 0x69b638db, 0x3764b408, 0xe03666ec, 0x5b1259d0, 0x7896e98a, "....." },
  [3042] = { "⟦Troll Temper=Sudore di Troll⟧", "Porta 20 fiale di ⟦Troll Temper=Sudore di Troll⟧ a Trenton Lighthammer a ⟦Gadgetzan=Meccania⟧.", "I troll Sabbiafurente di ⟦Zul'Farrak=Zul'farrak⟧ ricavano dalle arenarie un agente per la tempra, e io posso usarlo per temprare gli oggetti che forgio, eccome se posso! Gli intenditori lo pagano a peso d'oro, quindi se mi porti una buona scorta di Sudore di Troll ti ricompenserò bene.\n\n⟦Zul'Farrak=Zul'farrak⟧ è a nord-ovest di ⟦Gadgetzan=Meccania⟧. Buona fortuna.", "Mi hai portato il Sudore di Troll, {name}?", "Ah, questo è davvero un ottimo Sudore di Troll! E quanto ce n'è! Lavorerò per giorni prima di usarlo tutto!\n\nGrazie, {name}. Ti prego, prendi questo come compenso.", 0xc905c5a9, 0xa028d7d0, 0x8e83f55c, 0x0bfb6765, 0x63047f86, "....." },
  [3062] = { "Cuore oscuro", "Talo Thornhoof all'⟦Camp Mojache=Accampamento Mojache⟧ vuole il Cuore Oscuro di Edana Hatetalon.", "Edana Hatetalon è la regina delle arpie Northspring che vivono nelle rovine a ovest. È il male puro; ho sentito dire che il suo cuore è di cristallo. Non prova alcuna emozione, se non l'odio che nutre verso tutti gli altri. Devi affrontare Edana e riportarmi il suo cuore oscuro.\n\nHo sentito parlare di un corno che le arpie portano con sé: suonarlo presso le pietre Hatetalon, nella parte settentrionale delle rovine, richiamerà la regina.\n\nImmagina la sua sorpresa quando a chiamarla non sarà la sua gente, ma la sua morte.", "L'odio che Edana diffonde su queste terre va fermato.", "Ora so che Edana è morta davvero. Questo cuore lo terrò in ricordo di ciò che hai fatto qui per me, {name}. Grazie.", 0x9af68453, 0x1b081601, 0xab66d8bb, 0x57530bb3, 0xf3df6cce, "....." },
  [3063] = { "Vendetta sulle Northspring", "Talo Thornhoof vuole che tu uccida 4 Northspring Harpy, 4 Northspring Roguefeather, 4 Northspring Windcaller e 4 Northspring Slayer.", "Ai miei tempi ero un cacciatore esperto. Non c'era creatura che temessi. Finché...\n\nEro nella foresta, ad affilare la lama dopo una dura battaglia, quando caddi in un'imboscata. Le arpie mi circondarono, e riuscii a malapena a trascinarmi in salvo.\n\nAncora oggi sento l'eco delle loro grida...\n\nDa allora non sono più stato lo stesso. Ma l'odio mi ribolle dentro: dopo tutti questi anni, devo pareggiare i conti.\n\nLe arpie Northspring si trovano a ovest di qui. {name}, vendicami.", "Le ali delle arpie Northspring sono nere come la notte; non distogliere lo sguardo da loro, o spariranno nell'oscurità.", "Grazie, {name}. Hai dato pace alla mente di un vecchio tauren.", 0x38e02ae5, 0x31867a8e, 0xf1f40184, 0xc2525972, 0x64f65ca4, "....." },
  [3065] = { "⟦Simple Tablet=Tavoletta Semplice⟧", "Leggi la ⟦Simple Tablet=Tavoletta Semplice⟧ e parla con Frang nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una cartapecora per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttore dei guerrieri Frang. Vuole parlarti quando sarai pront<o/a>. Lo troverai fuori dall'Antro del Tirocinio, al riparo all'ombra.", "<Un/Una> nuov<o/a> {race} per rinforzare i ranghi. Per me va bene.\n\nProbabilmente farai fatica a sollevare una buona arma come un'ascia, ma una lancia vale quanto qualsiasi altra cosa.\n\nBenvenut<o/a> nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Troverai questo posto adatto a te, mentre continui ad addestrarti nelle vie del {class}. Se hai domande, chiedi pure a chiunque qui intorno, e quando ti senti pront<o/a>, torna da me per l'addestramento. Padroneggio quest'arte quanto qualunque altro {class} qui nella Valle e posso trasmetterti il mio sapere... a pagamento.", 0x1de75c3d, 0x70d6f7de, 0xb9d4e50a, 0x3a60c097, 0x79d5a027, "....." },
  [3082] = { "⟦Etched Tablet=Tavoletta Intagliata⟧", "Parla con Jen'shan nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una tavoletta per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttrice dei cacciatori Jen'shan. Vuole parlarti quando sarai pront<o/a>.", "Jen'shan vede <un/una> potente <cacciatore/cacciatrice> davanti a sé, e gli spiriti approvano.\n\nLa via del cacciatore è uno dei più antichi modi di vivere della nostra gente. L'⟦Horde=Orda⟧ venne da noi quando loro faticavano solo a sopravvivere su Azeroth, e ci chiesero di insegnare, di mostrare i segreti di tante cose. Erano già forti: forti nelle vie degli sciamani; forti nelle vie dei guerrieri. Ma la via del cacciatore non era la loro via... allora.", "Ora noi insegniamo a loro quelle cose, e loro insegnano a noi altre. Diventiamo un'unica razza... quasi. Siamo alleati da tanto tempo ormai. Quindi tu ricorda di aiutarli. E Jen'shan si ricorda di aiutare te.\n\nJen'shan ti insegna le vie del cacciatore, e te le insegna bene. Non dimenticare mai che i cacciatori sono molto rispettati dalla tribù. Tu avrai un ruolo grande nel futuro... non dimenticarlo mai.\n\nQuando senti il bisogno, vieni da Jen'shan. Lei ti insegna tutto quello che può quando ti sente pront<o/a>.", 0x5f30637e, 0xd78d7114, 0x1cb5c31f, 0xd3da7216, 0xbd0588a5, "....." },
  [3083] = { "⟦Encrypted Tablet=Tavoletta Codificata⟧", "Leggi la ⟦Encrypted Tablet=Tavoletta Codificata⟧ e parla con Rwag nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una tavoletta per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttore dei ladri Rwag. Vuole parlarti quando sarai pront<o/a>.", "Benvenut<o/a> nella ⟦Valley of Trials=Valle delle Sfide⟧, {name}. Non saresti qui se non avessi ricevuto la mia tavoletta, quindi vengo al punto.\n\nSono Rwag e mi occupo di addestrare ladri, furfanti e borseggiatori qui nella Valle. Sono io quello a cui si rivolgerà la Hand se non sarai pront<o/a> per ciò che ti aspetta. Ma non preoccuparti, la Hand non controllerà ogni tua mossa, anche se sarebbe saggio collaborare con loro, se avranno bisogno dei tuoi talenti.", "Fino ad allora, sarai sotto la mia tutela. Ti insegnerò i trucchi del mestiere, come dice qualcuno. Quando ti senti pront<o/a>, vieni da me e vedrò di addestrarti ancora. Nel frattempo, esercita le tue capacità e tienile affilate come un rasoio. Non si sa mai quando potrebbe servirti anche l'abilità più insignificante.", 0xf26f0369, 0x4028c542, 0x4649a294, 0x63ebe82c, 0x41da7694, "....." },
  [3084] = { "⟦Rune-Inscribed Tablet=Tavoletta con Rune⟧", "Parla con Shikrik nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una tavoletta per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttrice degli sciamani Shikrik. Vuole parlarti quando sarai pront<o/a>.", "Ah, benvenut<o/a>, {name}. Sono lieta che tu sia arrivat<o/a>. Le mie giornate sono diventate lunghe e perfino frenetiche, con tanti allievi da istruire, ma l'arrivo di uno della tua gente mi dà un grande senso di soddisfazione: ricordo i giorni in cui fui istruita da uno dei vostri sciamani.", "Come probabilmente sai, sono gli elementi a darci il nostro potere. Fuoco, terra, acqua e aria: questi sono i nostri strumenti.\n\nLa nostra forza viene dagli spiriti dei nostri antenati. Siamo le guide del nostro popolo. Come Thrall lo è per l'⟦Horde=Orda⟧, così noi lo saremo per i villaggi e le città che visitiamo. Si rivolgeranno a noi per avere saggezza e protezione. Per essere più preparat<o/a>, devi addestrarti spesso. Quando senti di aver acquisito più potere, vieni da me e ti insegnerò ciò che posso.", 0x57135a67, 0xaa674223, 0x7a1980af, 0xc763b8e8, 0x0bb859af, "....." },
  [3085] = { "⟦Hallowed Tablet=Tavoletta Benedetta⟧", "Leggi la ⟦Hallowed Tablet=Tavoletta Benedetta⟧ e parla con Ken'jai fuori dall'Antro del Tirocinio, nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una tavoletta per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttore dei sacerdoti Ken'jai. Vuole parlarti quando sarai pront<o/a>.", "Allora ce l'hai fatta... bene, bene! Gli spiriti mi han detto che saresti venut<o/a> presto a trovare Ken'jai. Lascia che io sia uno dei primi a darti il benvenuto nella ⟦Valley of Trials=Valle delle Sfide⟧. Questo posto non sarà casa tua per molto, ma finché lo è, perché non approfittarne al meglio?", "Mentre metti alla prova te stess<o/a>, scoprirai di avere un controllo sempre migliore sugli spiriti: li chiamerai per cose sempre più grandi... ed è qui che entra in gioco il vecchio Ken'jai. Vieni a parlare col vecchio Ken'jai quando ti senti pront<o/a>. Se gli spiriti sono d'accordo, allora vediamo di insegnarti abilità più potenti... ma solo se gli spiriti sono d'accordo.\n\nOra va', parla col resto della gente della Valle. Torna a parlarmi più tardi.", 0xcbf1c524, 0xc36df6ef, 0x3e34c39a, 0x2b9a89b9, 0x5fe35355, "....." },
  [3086] = { "⟦Glyphic Tablet=Tavoletta con Glifi⟧", "Leggi la ⟦Glyphic Tablet=Tavoletta con Glifi⟧ e parla con Mai'ah vicino all'ingresso dell'Antro del Tirocinio, nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una tavoletta per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttrice dei maghi Mai'ah. Vuole parlarti quando sarai pront<o/a>.", "Già cerchi di compiacere Mai'ah, {name}. Questo è bene. Tu dai rispetto a Mai'ah, e Mai'ah forse ti ridà rispetto. Ma basta così, tu sei qui per imparare la magia, non per sentire Mai'ah che chiacchiera.\n\nC'è solo una cosa sulla magia che Mai'ah non può insegnarti, {name}, ed è come fermare la corruzione.", "Tu sei tra gli esseri più potenti del pianeta, {name}... su questo non si discute. E tutti lo sanno... lo sanno bene, pure!\n\nMa devi stare attent<o/a>! Perché non è l'orco, o l'elfo, o il nano che devi temere... sono le cose che non puoi vedere. La magia è potente. Ti fa fare cose che forse non vuoi fare. Ti fa pensare di essere più potente di quanto sei davvero. Sii paziente. Usa la testa.\n\nQuando pensi di essere pront<o/a> per l'addestramento, torna da Mai'ah. Lei ti insegna quello che sei pront<o/a> a imparare, nessun problema.", 0x2f8b4832, 0xdeaadea8, 0x57f2c952, 0x3b28c8b6, 0xc911bdb3, "....." },
  [3087] = { "⟦Etched Parchment=Cartapecora Intagliata⟧", "Leggi la ⟦Etched Parchment=Cartapecora Intagliata⟧ e parla con Jen'shan nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una cartapecora per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttrice dei cacciatori Jen'shan. Vuole parlarti quando sarai pront<o/a>.", "Ah, allora sei arrivat<o/a>, finalmente. Bene. Jen'shan ti aspettava.\n\nMolti pensano che sia una via facile, ma Jen'shan ti dice che non è vero. Dominare le bestie di Durotar e oltre richiede tanta abilità quanto dominare le arti arcane o parlare con i nostri antenati.\n\nTirare con l'arco o col fucile forse non è pericoloso per te quanto lanciare un incantesimo, ma di sicuro è pericoloso per il tuo nemico.", "Quando finiamo di parlare, dovresti parlare col resto degli abitanti della Valle. Loro ti chiedono di fare cose per loro... cose che metteranno alla prova la tua abilità e ti insegneranno alcuni dei pericoli di questa terra.\n\nMan mano che cresci in esperienza e saggezza, avrai bisogno che Jen'shan ti mostri tecniche e abilità migliori. Torna spesso da Jen'shan. Ti dirò cosa posso insegnarti.", 0x923579a2, 0x48d60d22, 0xfba32734, 0x0569874c, 0x7c765b06, "....." },
  [3088] = { "⟦Encrypted Parchment=Cartapecora Codificata⟧", "Leggi la ⟦Encrypted Parchment=Cartapecora Codificata⟧ e parla con Rwag nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una cartapecora per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttore dei ladri Rwag. Vuole parlarti quando sarai pront<o/a>.", "Ssst, non così forte. Non mi fido di Nartok, laggiù. Chi deve nascondersi in una grotta più in fondo di me non va preso alla leggera.\n\nImmagino che tu non abbia avuto problemi a orientarti?", "Ora che sai dove mi sono rintanato, devo dirti una cosa: la Shattered Hand mi ha chiesto di tenerti d'occhio. Vogliono che ti addestri e che ti tenga informat<o/a> su qualunque cosa possa servire a loro. Anche se non ti interessa ancora aiutarli, e saresti sciocc<o/a> a non volerlo, farò il possibile per addestrarti... per un piccolo compenso. Torna da me quando pensi di essere pront<o/a>, e vedremo cosa sei pront<o/a> a imparare.", 0xccd2a2af, 0x62ff2435, 0xf5942fa0, 0x2656277a, 0xdb3c2ab9, "....." },
  [3089] = { "⟦Rune-Inscribed Parchment=Cartapecora con Rune⟧", "Leggi la ⟦Rune-Inscribed Parchment=Cartapecora con Rune⟧ e parla con Shikrik nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una cartapecora per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttrice degli sciamani Shikrik. Vuole parlarti quando sarai pront<o/a>.", "Allora sei arrivat<o/a>. Cominciavo a chiedermi quando ti saresti fatt<o/a> vedere. Ho mandato la cartapecora un po' di tempo fa e non ero sicura che fosse arrivata.\n\nMa basta chiacchiere... sei qui perché sei stat<o/a> scelt<o/a>, scelt<o/a> per guidare la vita spirituale del nostro popolo.", "Sarai il tramite attraverso cui comunicano i nostri antenati. Avrai il potere degli elementi ai tuoi ordini. Annientare i tuoi nemici sarà un gioco da ragazzi; guarire i tuoi alleati, facile come respirare. Tieni a mente queste cose mentre affronti nuove sfide, e torna da me tutte le volte che vuoi. Resterò qui per insegnarti nuovi incantesimi e indirizzarti sulla strada giusta quando sarai pront<o/a>.", 0xb7d19e20, 0x38687a84, 0x4edad387, 0xa3f65b21, 0xb34f759d, "....." },
  [3090] = { "⟦Tainted Parchment=Cartapecora Corrotta⟧", "Leggi la ⟦Tainted Parchment=Cartapecora Corrotta⟧ e parla con Nartok dentro l'Antro del Tirocinio, nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una cartapecora per te, {name}.\n\nDi solito, se posso, evito di avere a che fare con gli stregoni, ma credo che dovresti leggerla quando hai tempo. Se non sbaglio, viene dal tuo nuovo istruttore, Nartok. Vuole parlarti quando sarai pront<o/a>.", "Finalmente sei arrivat<o/a>... e con discrezione, per giunta. Bene.\n\nIl nostro mondo è pieno di sciocchi, {name}. Perfino il potente Thrall ha difetti più grandi di quanto i più riescano a vedere. Volta le spalle al potere necessario per rendere questa terra completamente nostra! Non siamo più il popolo che fu manipolato e usato dalle creature del Nether. Siamo un popolo a sé. Siamo fieri... e siamo forti.", "E ora anche tu sei entrat<o/a> nelle nostre file. Non fraintendermi, {name}. Solo perché hai accesso a un potere che molti invidieranno, non significa che sarai accettat<o/a> facilmente. Thrall permette a quelli come noi di entrare a Orgrimmar perché siamo ancora suoi consanguinei: non può voltarci le spalle, o diventeremmo patetici quanto gli umani che lo resero schiavo. Il punto è questo: sta' attent<o/a>. Puoi essere potente, ma se sei sciocc<o/a>, sei già mort<o/a>.\n\nSe ti serve addestramento negli incantesimi, torna da me.", 0xaf2d0c7f, 0x3d7f7224, 0x01fe275d, 0xcc951811, 0x2b34a4b3, "....." },
  [3091] = { "⟦Simple Note=Nota Semplice⟧", "Leggi la ⟦Simple Note=Nota Semplice⟧ e parla con Harutt Thunderhorn al ⟦Camp Narache=Campo Narache⟧.", "Poco fa una messaggera ti stava cercando, {name}. Credo l'abbia mandata l'istruttore dei guerrieri Harutt. Se questa nota è di Harutt, non aspetterei troppo a leggerla.", "Ah, finalmente sei arrivat<o/a>, {class}. Non ho mentito nella mia nota, {name}. Anche noi siamo una stirpe speciale, non diversa dai druidi o dagli sciamani della nostra tribù. Sei altrettanto importante. Siamo noi quelli chiamati a difendere i nostri confini, a cacciare i centauri e ad andare in guerra.", "Ognuno di noi ha un ruolo nella nostra tribù. E ognuno di noi deve affrontare gli stessi riti. Non lasciare mai che il tuo orgoglio ti dica il contrario.\n\nResto qui per addestrare i nuovi guerrieri che cercano la gloria della battaglia e che seguono le vie dei nostri antenati più antichi. Quando ti senti pront<o/a>, torna da me e farò il possibile per addestrarti ancora. Va' con la benedizione della tribù, {name}.", 0x14ead102, 0x3a12e673, 0xe0460976, 0xa6b0edf0, 0xb1121bc2, "....." },
  [3092] = { "⟦Etched Note=Nota Intagliata⟧", "Leggi la ⟦Etched Note=Nota Intagliata⟧ e parla con Lanka Farshot alla ⟦Red Cloud Mesa=Mesa Nuvola Rossa⟧.", "Poco fa una messaggera ti stava cercando, {name}. Credo l'abbia mandata l'istruttrice dei cacciatori Lanka. Se questa nota è di Lanka, non aspetterei troppo a leggerla.", "Benvenut<o/a> al ⟦Camp Narache=Campo Narache⟧, {name}. Sento dire buone cose su di te. La tua stirpe è forte e molti anziani ti ritengono già abile. Ma questo lo metteremo alla prova.\n\nLe pianure di Mulgore saranno la tua casa per un po': dovresti fare del tuo meglio per conoscerle molto bene. Un giorno viaggerai verso terre sconosciute per padroneggiare abilità superiori. Devi essere pront<o/a>.", "Ed è mio compito assicurarmi che tu sia pront<o/a>, insegnandoti le basi della nostra professione: come addomesticare il tuo animale, come sparare col fucile e molte altre abilità che diventeranno necessarie.\n\nI cacciatori sono una parte importante della nostra tradizione e della nostra storia, {name}. Faresti bene a ricordare quanto sei importante per la tribù. Sarai rispettat<o/a> e venerat<o/a> se servirai bene il nostro popolo.", 0x9c2dae5c, 0xed672d15, 0x78d5882a, 0x6c84c2d0, 0xbd639c75, "....." },
  [3093] = { "⟦Rune-Inscribed Note=Nota con Rune⟧", "Leggi la ⟦Rune-Inscribed Note=Nota con Rune⟧ e parla con Meela Dawnstrider al ⟦Camp Narache=Campo Narache⟧.", "Poco fa una messaggera ti stava cercando, {name}. Credo l'abbia mandata l'istruttrice degli sciamani Meela. Se questa nota è di Meela, non aspetterei troppo a leggerla.", "Con la stessa rapidità con cui l'acqua cade dal cielo, eccoti davanti a me. La tua prontezza mi fa piacere. Significa che capisci l'importanza del nostro incontro e della tua presenza qui. Non sono un capo, ma comprendo gli elementi e so parlare con gli spiriti del nostro popolo. Ti insegnerò a fare lo stesso.", "Ci incontreremo molte volte nei giorni a venire. Spero che ogni volta lascerai la mia compagnia un po' più potente... un po' più preparat<o/a>. Come la Fiamma Eterna, il tuo spirito arderà luminoso e caldo.\n\nVa' ora, {name}. Va' e metti alla prova te stess<o/a>. Sarò qui per te quando ne avrai bisogno.", 0x3d99c971, 0x05a28553, 0xa97f9159, 0x8b98605c, 0xb586e860, "....." },
  [3094] = { "⟦Verdant Note=Nota Verdastra⟧", "Leggi la ⟦Verdant Note=Nota Verdastra⟧ e parla con Gart Mistrunner al ⟦Camp Narache=Campo Narache⟧.", "Poco fa una messaggera ti stava cercando, {name}. Credo l'abbia mandata l'istruttore dei druidi Gart. Se questa nota è di Gart, non aspetterei troppo a leggerla.", "Sei arrivat<o/a>. Questo è bene. Gli spiriti dei nostri antenati sono diventati inquieti in tutto Mulgore e oltre, ma non so dire perché. Sarà sempre tuo dovere imparare ad ascoltare gli spiriti della natura e agire come loro avatar. Tienilo a mente.", "Anche se ci unisce un legame comune, non aspettarti una grande accoglienza dagli Elfi della Notte. Il loro orgoglio limita ancora la loro vista, ma non è affar nostro. Gli insegnamenti della Madre Terra sono tutto ciò di cui devi preoccuparti, e ti insegnerò ciò che so man mano che crescerai in saggezza.\n\nTorna spesso da me, {name}. Scoprirai che la Madre Terra concede capacità incredibili a chi le è più devoto.", 0x183c3d84, 0x92cc1324, 0x227a33b2, 0xe544de60, 0xae67cb54, "....." },
  [3095] = { "⟦Simple Scroll=Pergamena Semplice⟧", "Leggi la ⟦Simple Scroll=Pergamena Semplice⟧ e parla con Dannal Stern ad ⟦Deathknell=Albamorta⟧.", "Ah, mentre eri impegnat<o/a> con il Flagello senza mente, è arrivata questa pergamena per te. Credo sia una faccenda importante, visto che sembra portare il sigillo dell'istruttore dei guerrieri Dannal. Al tuo posto la leggerei prima di ripartire.", "Ah, sei arrivat<o/a>. Bene. Ho sentito che pochi altri sono riusciti a sfuggire alla \"morte\" e si stavano dirigendo in città. Forse questa tenacia ripagherà anche in futuro.\n\nPuoi ringraziare Sylvanas per la tua libertà... libertà della mente e del corpo. Anche se resti tormentat<o/a> dalla pestilenza e dai suoi effetti, ora sei liber<o/a> di andare e venire come meglio credi.", "Sarò qui per addestrarti mentre acquisti esperienza... vieni a trovarmi tutte le volte che vuoi. Chiedo un compenso minimo, ma scoprirai che tutto ciò che posso insegnarti ne vale la pena.\n\nOra va' e metti alla prova la tua abilità. Molte altre cose ti saranno rivelate man mano che acquisti esperienza, alcune delle quali non posso discutere con te qui. Sappi solo che in futuro Sylvanas avrà bisogno di guerrieri con la tua forza. Sarai la spina dorsale della nostra salvezza. Non dimenticarlo.", 0x47a42397, 0xab7828aa, 0xac9ea6e5, 0x3d4cd994, 0x26098b59, "....." },
  [3096] = { "⟦Encrypted Scroll=Pergamena Codificata⟧", "Leggi la ⟦Encrypted Scroll=Pergamena Codificata⟧ e parla con David Trias ad ⟦Deathknell=Albamorta⟧.", "Ah, mentre eri impegnat<o/a> con il Flagello senza mente, è arrivata questa pergamena per te. Credo sia una faccenda importante, visto che sembra portare il sigillo dell'istruttore dei ladri David Trias. Al tuo posto la leggerei prima di ripartire.", "Quindi ce l'hai fatta? Bene, col tempo avremo bisogno di altri ladri. Probabilmente gli Shadowstalkers ti troveranno quando lo riterranno opportuno, quindi non fare passi falsi e non fare niente di cui potresti pentirti. Hanno bisogno di agenti di talento... non di borseggiatori e sciocchi.", "Passo quasi tutto il tempo qui nella locanda a tenere d'occhio le facce nuove e le promesse in ascesa. Tieniti fuori dai guai e farò il possibile per insegnarti qualcosa. Torna da me quando vuoi e vedremo se sei pront<o/a> per una o due nuove abilità.", 0x1c2bcac8, 0xcefbc41c, 0x080b8339, 0x390c2af2, 0xe51c548c, "....." },
  [3097] = { "⟦Hallowed Scroll=Pergamena Benedetta⟧", "Leggi la ⟦Hallowed Scroll=Pergamena Benedetta⟧ e parla con il Chierico Oscuro Duesten nella chiesa di ⟦Deathknell=Albamorta⟧.", "Ah, mentre eri impegnat<o/a> con il Flagello senza mente, è arrivata questa pergamena per te. Credo sia una faccenda importante, visto che sembra portare il sigillo dell'istruttore dei sacerdoti Duesten. Al tuo posto la leggerei prima di ripartire.", "Ah, tra fuoco, pestilenza, rivolte e cose molto peggiori, un altro dei \"fedeli\" bussa alla mia porta. Be', lascia che ti dia il benvenuto, {class}. E concedimi un momento per spiegarti un paio di cose, prima che tu decida che è ora di cercare qualunque cosa ti spinga avanti: la ⟦Holy Light=Luce Sacra⟧ non ti riguarda più, gli spiriti dei tuoi antenati sono favole, e le creature del Vuoto non ti vogliono.\n\nFin qui mi segui?", "C'è solo una cosa che devi sapere: siamo sopravvissuti grazie alla sola volontà. È la fede in noi stessi che ci distingue dagli altri, e con i nostri poteri porteremo grandi cambiamenti in tutta Azeroth. I deboli verranno ad appoggiarsi a te. I lebbrosi ti chiameranno Signore. E gli ignoranti ti cercheranno per avere una guida. È mio dovere assicurarmi che tu abbia gli strumenti necessari, così che quando verrà il momento sarai pront<o/a>. Man mano che acquisti esperienza, cercami. Ti insegnerò poteri più grandi, se sarai pront<o/a>.", 0xf5ae8c7e, 0x1fc11880, 0xd59f8872, 0xe3387ae8, 0x8c4ad707, "....." },
  [3098] = { "⟦Glyphic Scroll=Pergamena con Glifi⟧", "Leggi la ⟦Glyphic Scroll=Pergamena con Glifi⟧ e parla con Isabella nella chiesa di ⟦Deathknell=Albamorta⟧.", "Ah, mentre eri impegnat<o/a> con il Flagello senza mente, è arrivata questa pergamena per te. Credo sia una faccenda importante, visto che sembra portare il sigillo dell'istruttrice dei maghi Isabella. Al tuo posto la leggerei prima di ripartire.", "Sapevo che saresti venut<o/a> da me, {name}. Non perché ti manchi la volontà di seguire la tua strada, ma perché siamo spiriti affini. Entrambi abbiamo provato il dolore. Entrambi abbiamo sofferto. E ora vogliamo il potere di riprenderci ciò che sappiamo essere nostro: questa terra, le nostre vite, i nostri destini. Ma hai ancora molto da imparare.", "Devi tornare spesso da me, se vuoi diventare abbastanza potente da distruggere chi vorrebbe opporsi a noi. Le regole della magia valgono ancora per te, {name}. Scoprirai che la corruzione ti segue ancora come lupi affamati nella notte. Scoprirai che la sua carezza non è diversa da una dipendenza, una vecchia amante che vuole ancora starti accanto. Ma queste cose si possono tenere a bada. Ti controlleranno solo se glielo permetterai.\n\nOra va', e torna da me quando sarai più potente.", 0x59480f8c, 0xe2240a4b, 0x538de0b1, 0x33c31b73, 0x7b8e5ffc, "....." },
  [3099] = { "⟦Tainted Scroll=Pergamena Corrotta⟧", "Leggi la ⟦Tainted Scroll=Pergamena Corrotta⟧ e parla con Maximillion ad ⟦Deathknell=Albamorta⟧.", "Ah, mentre eri impegnat<o/a> con il Flagello senza mente, è arrivata questa pergamena per te. Credo sia una faccenda importante, visto che sembra portare il sigillo dell'istruttore degli stregoni Maximillion. Al tuo posto la leggerei prima di ripartire.", "Ti do il benvenuto, <fratello/sorella>. Sapevo che saresti venut<o/a>. Era solo questione di tempo.\n\nCiò che ho detto ti ha interessato, vero? Ho toccato una corda... qualcosa dentro di te sapeva che dicevo il vero. Bene.\n\nSappi però questo: non sono un traditore di Sylvanas. Semmai, lei apprezzerebbe le mie parole, visto che sono state proprio le sue convinzioni a portare i Reietti dove sono ora.", "Ho detto che uno schiavo resta uno schiavo, qualunque sia il padrone. Te lo ricordi? Sappiamo entrambi che è quel tipo di controllo, quel tipo di potere, a guidarci adesso. Cerchiamo creature che ci servano. Sappiamo di essere più potenti e di meritare più rispetto di quanto ce ne diano gli altri... e ora vogliamo prendercelo.\n\nSarò tuo alleato in questa lotta, la lotta per la nostra libertà. Libertà di scegliere le nostre alleanze. Quando ti sentirai pront<o/a>, torna da me e ti insegnerò tutto ciò che so.", 0xbb45df2a, 0x6c0ba64b, 0x7834b1d3, 0xe41ae79b, 0xde5f138f, ".....", nil, nil, nil, 0x447c5d0b, nil },
  [3100] = { "⟦Simple Letter=Lettera Semplice⟧", "Leggi la ⟦Simple Letter=Lettera Semplice⟧ e parla con Llane Beshere all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Mi hanno chiesto di mostrarti questa appena fossi tornat<o/a> dagli accampamenti dei coboldi, {name}. Sembra una lettera sigillata con l'emblema di Llane, il nostro istruttore dei guerrieri. Io la leggerei senza esitare, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.", "Ah, hai ricevuto la mia lettera, {name}... bene.\n\nDi recente c'è stato un afflusso di guerrieri a Elwynn, il che è un bene per ⟦Stormwind=Roccavento⟧, ma un male per i coboldi e i Defias della zona.", "Sistemati per bene, impara a conoscere il territorio e torna da me quando ti serve addestramento. Sono qui giorno e notte.\n\nI ⟦Knights of the Silver Hand=Cavalieri della Mano d'Argento⟧ hanno fatto un buon lavoro nel rendere questo posto abbastanza sicuro, ma quando conoscerai gli altri cittadini, credo che scoprirai che tutti hanno problemi per cui un aiuto farebbe comodo: l'aiuto che un {class} può dare loro. Buona fortuna.", 0x8a6765ad, 0xcd1a2f24, 0xfe579234, 0x76e67b55, 0x1ce50385, "....." },
  [3101] = { "⟦Consecrated Letter=Lettera Consacrata⟧", "Leggi la ⟦Consecrated Letter=Lettera Consacrata⟧ e parla con fratello Sammuel all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Mi hanno chiesto di mostrarti questa appena fossi tornat<o/a> dagli accampamenti dei coboldi, {name}. Sembra una lettera sigillata con l'emblema di fratello Sammuel, il nostro istruttore dei paladini. Io la leggerei senza esitare, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.", "Finalmente! Ci incontriamo faccia a faccia, da fratello a <fratello/sorella>. Ti do il benvenuto nella ⟦Northshire=Contea del Nord⟧. Questa sarà la tua casa per poco tempo, mentre impari come vanno le cose, ma sappi che ⟦Stormwind=Roccavento⟧ non è lontana e prima o poi il tuo cammino ti porterà lì. Fino ad allora, però, sii paziente... Cavaliere della ⟦Silver Hand=Mano d'Argento⟧.", "Nel frattempo, dovresti sapere un paio di altre cose. Per molti, in questa terra, sei un simbolo: comportati di conseguenza. La ⟦Holy Light=Luce Sacra⟧ risplende dentro di te, e sarà evidente sia ai tuoi alleati sia ai tuoi nemici.\n\nInoltre, man mano che crescerai in saggezza e potere, dovrai addestrarti per imparare nuove abilità. È qui che entro in gioco io. Quando sentirai di aver acquisito un po' di esperienza qui nella ⟦Northshire=Contea del Nord⟧, torna da me e ti insegnerò ciò che ritengo tu sia pront<o/a> a imparare. Buona fortuna... {class}!", 0x339c82f5, 0x6d6ee593, 0x26cd99ad, 0xeb1b3e11, 0x8b941ae4, ".....", nil, nil, nil, 0x808f8fbe, nil },
  [3102] = { "⟦Encrypted Letter=Lettera Codificata⟧", "Leggi la ⟦Encrypted Letter=Lettera Codificata⟧ e parla con Jorik Kerridan nella stalla dietro l'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Mi hanno chiesto di mostrarti questa appena fossi tornat<o/a> dagli accampamenti dei coboldi, {name}. Sembra una lettera sigillata con l'emblema di Jorik, uno dei nostri istruttori. Io la leggerei senza esitare, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.", "Sei arrivat<o/a> qui tutt<o/a> inter<o/a>, e non sembra che ti abbiano vist<o/a> in molti. Per me va bene. Non mi piace attirare troppa attenzione, qui dietro... bello tranquillo. Sono sicuro che capisci.\n\nHai già avuto problemi? Mi fa piacere sentire di no. Le cose cambieranno presto.", "Troverai un bel po' di gruppi che bramano le nostre abilità, {name}. Avventurieri, ⟦SI:7=IR:7⟧... diamine, perfino la ⟦Defias Brotherhood=Fratellanza dei Defias⟧ non disdegnerebbe una spia o due dentro ⟦Stormwind=Roccavento⟧. Ma ricordati questo: sei <un/una> <uomo/donna> che decide da sé. Non lasciare che nessuno ti costringa a fare qualcosa che non vuoi fare! E poi, le carte buone le abbiamo noi... almeno, prima che la partita finisca. Capisci cosa intendo?\n\nComunque, volevo solo presentarmi e farti sapere che sono qui se ti serve addestramento. Passa quando vuoi.", 0x5eef0cde, 0x3d129a05, 0xb39f75e7, 0x6b9b0e24, 0xd57ec303, ".....", nil, nil, nil, nil, 0x46913652 },
  [3103] = { "⟦Hallowed Letter=Lettera Benedetta⟧", "Leggi la ⟦Hallowed Letter=Lettera Benedetta⟧ e parla con la sacerdotessa Anetta all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Mi hanno chiesto di mostrarti questa appena fossi tornat<o/a> dagli accampamenti dei coboldi, {name}. Sembra una lettera sigillata con l'emblema della sacerdotessa Anetta, la nostra istruttrice dei sacerdoti. Io la leggerei senza esitare, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.", "Ah, finalmente sei arrivat<o/a>. Sapevo che avresti trovato la strada fino a me. La ⟦Holy Light=Luce Sacra⟧ risplende su di te e sul cammino che hai scelto. Sono tempi duri: la Legione Infuocata è ancora presente su Azeroth, l'intero Kalimdor cerca nuovi modi per difendersi dalle proprie tribolazioni, e spetta a te aiutare quante più persone possibile.", "Man mano che acquisirai esperienza, torna da me e farò il possibile per trasmetterti il mio sapere. Fino ad allora, va' con la compassione nel cuore e lascia che la saggezza sia la tua guida. Ricorda, il mondo diventa un posto migliore solo se sei tu a renderlo tale.", 0x3871ce99, 0x3719f745, 0x63ba8573, 0x3c6b09ac, 0x69805596, "....." },
  [3104] = { "⟦Glyphic Letter=Lettera con Glifi⟧", "Leggi la ⟦Glyphic Letter=Lettera con Glifi⟧ e parla con Khelden Bremen dentro l'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Mi hanno chiesto di mostrarti questa appena fossi tornat<o/a> dagli accampamenti dei coboldi, {name}. Sembra una lettera sigillata con l'emblema di Khelden, il nostro istruttore dei maghi. Io la leggerei senza esitare, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.", "Salve, {name}. Sono Khelden. Posso fare qualcosa per te?", "Ah ah, sapevo che il mio biglietto non ti avrebbe distolt<o/a> dal tuo cammino. Allora sei pront<o/a>, vero? Pront<o/a> ad accettare il tuo destino? Pront<o/a> a sfidare gli dèi e qualunque altra forza ti si pari davanti nella ricerca della conoscenza e del potere?\n\nNon mentirò, {name}: sarai temut<o/a> quanto rispettat<o/a>. Ma sappi anche questo: sarò qui per te quando avrai bisogno di addestramento. Cercami man mano che diventerai più potente.", 0x9c0b51a2, 0xb2702f67, 0xde444377, 0x1257130c, 0xea282e3b, "....." },
  [3105] = { "⟦Tainted Letter=Lettera Corrotta⟧", "Leggi la ⟦Tainted Letter=Lettera Corrotta⟧ e parla con Drusilla La Salle accanto all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Mi hanno chiesto di mostrarti questa appena fossi tornat<o/a> dagli accampamenti dei coboldi, {name}. Sembra una lettera sigillata con l'emblema di Drusilla, una delle nostre istruttrici. Io la leggerei senza esitare, prima di occuparti di qualsiasi altra faccenda qui all'Abbazia.", "Ah, eccoti arrivat<o/a>, e appena in tempo, {name}. Poco fa alcune guardie erano qui e mi lanciavano occhiate curiose... patetici profani.", "Man mano che il tuo potere crescerà, sarai tentat<o/a>: devi sempre ricordarti di controllarti. Non mentirò: la corruzione può colpire chiunque pratichi l'arcano, soprattutto chi ha a che fare con le creature della ⟦Twisting Nether=Distorsione Fatua⟧. Sii paziente, e sii prudente... ma non lasciare che questo soffochi la tua ambizione.\n\nMan mano che diventerai più potente, torna da me e ti insegnerò di più sulle nostre vie.", 0xfe092140, 0xa2b9450e, 0xc0471a03, 0x04538110, 0x1fcadfe2, "....." },
  [3106] = { "⟦Simple Rune=Runa Semplice⟧", "Leggi la ⟦Simple Rune=Runa Semplice⟧ e parla con Thran Khorman nella ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questa runa da passarti. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei guerrieri Thran. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Accidenti che freddo oggi, eh? È come se la neve non se ne andasse mai, {name}.\n\nL'avrai già notato, ma ora nella nostra città vivono degli gnomi. Questo perché si sono fatti saltare fuori da casa loro. Non andarlo a dire in giro, ma non posso dargli torto: credo che anch'io sarei ricorso agli esplosivi, se ⟦Ironforge=Forgiardente⟧ fosse infestata dai Ferroscuro o roba simile.", "Altre cose che probabilmente vedrai, giusto perché tu lo sappia: nani che in combattimento usano la magia invece del fucile. Alcuni di noi che si mettono a venerare la ⟦Holy Light=Luce Sacra⟧ come certi umani e, ultimi ma non meno importanti, i trogg. Ne saprai di più più avanti, ma quello che devi sapere adesso è che io sono qui per aiutarti.\n\nSono qui per insegnarti a essere un vero {class}. Ogni volta che pensi di aver bisogno di altro addestramento, torna da me e vedrò cosa posso fare.", 0x15759692, 0xa8e2a12b, 0x0b2a8f18, 0x45cd211f, 0xc0004879, "....." },
  [3107] = { "⟦Consecrated Rune=Runa Consacrata⟧", "Leggi la ⟦Consecrated Rune=Runa Consacrata⟧ e parla con Bromos Grummner nella ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questa runa da passarti. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei paladini Bromos. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Allora ce l'hai fatta! E appena in tempo. C'è molto da fare nella ⟦Coldridge Valley=Valle Crestafredda⟧ e oltre. Avrò bisogno del tuo aiuto quanto tu avrai bisogno del mio!\n\nOra sei un Cavaliere della ⟦Silver Hand=Mano d'Argento⟧: preparati a recitare la parte.", "Gli umani ci hanno insegnato molto sulla ⟦Holy Light=Luce Sacra⟧ e su quanto il loro ordine sia importante per loro... e per la protezione di tutta Azeroth. Abbiamo grande rispetto per quanto sia radicato nella tradizione, e per come una sola figura, un solo sacrificio, possa fare la differenza tra dolore e salvezza.\n\nNoi due lavoreremo insieme per un po'. Ogni volta che pensi di essere pront<o/a>, torna da me e vedremo di farti fare un po' di addestramento. Non possiamo mandarti nel mondo impreparat<o/a>, no?", 0x605af2d1, 0x95f50fa0, 0x01726882, 0x5259d37c, 0x8df035d1, "....." },
  [3108] = { "⟦Etched Rune=Runa Intagliata⟧", "Leggi la ⟦Etched Rune=Runa Intagliata⟧ e parla con Thorgas Grimson nella ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questa runa da passarti. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei cacciatori Thorgas. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Ce l'hai fatta! Mi fa piacere! Scommetto che non hai dovuto seguire le mie tracce per trovare il posto. Ah ah!\n\nLa nostra professione è profondamente legata alla tradizione, {name}. Imparare le vie della terra. Imparare a seguire le tracce di un orso tra le montagne. Perfino sopravvivere soltanto col proprio ingegno richiede molto coraggio e astuzia. Pensi di esserne capace?", "Una cosa che devi sempre ricordare è che devi rispettare il mondo in cui vivi. Le bestie che scelgono di combattere al tuo fianco; la lucentezza della tua arma; il peso delle tue munizioni; il morso di un vento gelido; tutte queste cose devi conoscerle a fondo.\n\nFarò il possibile per aiutarti, ma la maggior parte del lavoro spetta a te. Ogni volta che pensi di essere pront<o/a>, torna a parlarmi. Ti addestrerò quando posso.", 0x9cb873ec, 0xaa004bc7, 0x3f424343, 0x919eafc7, 0x04729792, "....." },
  [3109] = { "⟦Encrypted Rune=Runa Codificata⟧", "Leggi la ⟦Encrypted Rune=Runa Codificata⟧ e parla con Solm Hargrin nella ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questa runa da passarti. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei ladri Solm. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Ce l'hai fatta! Ottimo!\n\nUltimamente c'è un gran fermento, quindi sono contento di contare un altro membro del clan di ⟦Ironforge=Forgiardente⟧ tra le nostre file. Troppi di noi guardano all'arcano e al divino, per i miei gusti. Niente contro di loro e le loro credenze, ma non c'è niente come una lama fredda in mano e un'ombra che ti tenga lontano dalla luce, capisci cosa intendo?", "Comunque, quando comincerai a curiosare per ⟦Coldridge=Crestafredda⟧, prima o poi probabilmente avrai bisogno di addestramento. Torna da me ogni volta che ne senti il bisogno e ti insegnerò quello che so: un trucco qui, una manovra là. Sai, la roba che ti tiene in vita e ti fa guadagnare qualche moneta in più.\n\nTieni d'occhio anche i nostri amici gnomi... gli è andata proprio male, con Gnomeregan... distrutta. Avranno bisogno del nostro aiuto per sentirsi i benvenuti.", 0xde5dc5cf, 0x5ff77ee1, 0xfc6f1297, 0xdfb79b4e, 0x81c5d183, "....." },
  [3110] = { "⟦Hallowed Rune=Runa Benedetta⟧", "Leggi la ⟦Hallowed Rune=Runa Benedetta⟧ e parla con Branstock Khalder a ⟦Anvilmar=Forgiamara⟧.", "Mentre mi davi una mano, mi hanno dato questa runa da passarti. Prenditi un po' di tempo per leggerla quando puoi. Secondo me viene dall'istruttore dei sacerdoti Branstock. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Ah! Ce l'hai fatta, {name}! Magnifico!\n\nStavo per dire che stavo per perdere la fede che saresti arrivat<o/a>... capito, perdere la fede? È una battuta, <ragazzo/ragazza>... uff, lascia stare. Tanto non sei venut<o/a> qui per le mie battutacce.", "Sono io quello che può addestrarti mentre cominci a orientarti nella ⟦Coldridge Valley=Valle Crestafredda⟧. Quando ti senti pront<o/a>, torna da me e vedremo magari di insegnarti un incantesimo o due per difendere la valle da quei maledetti trogg.\n\nHai la Luce dalla tua parte, insieme a tutta ⟦Ironforge=Forgiardente⟧, {name}... nessuna pressione perché tu diventi qualcosa di speciale.", 0x87b91362, 0x2feef57d, 0xa512f166, 0x054b980d, 0x2b1b31d2, "....." },
  [3111] = { "Runa con Glifi", "Parla con Marryk Nurribit dentro ⟦Anvilmar=Forgiamara⟧.", "Tanto tempo fa gli alti elfi insegnarono i segreti della magia a noi e ai nostri alleati umani. Ci facevano la predica sulle regole e su come la magia possa farti impazzire! Ma non crederci. Noi non siamo come gli elfi; non abbiamo le loro stesse debolezze. Resta sulla retta via e scoprirai che la magia è tanto uno strumento potente quanto un'arma.\n\nQuando sei pront<o/a>, vieni a cercarmi dentro ⟦Anvilmar=Forgiamara⟧. Ti aspetto!", nil, nil, 0x82fc2769, 0xab749d05, 0x46703590, nil, nil, "...mm" },
  [3112] = { "⟦Simple Memorandum=Promemoria Semplice⟧", "Leggi il ⟦Simple Memorandum=Promemoria Semplice⟧ e parla con Thran Khorman nella ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questo promemoria da passarti. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene dall'istruttore dei guerrieri Thran. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Ah, be', un altro promemoria da <un/una> {race} in missione... che cosa pittoresca.\n\nNo, no, non ti sto prendendo in giro, piccol<o/a>. Bisogna rispettare la tua tenacia, questo è sicuro. Sarei altrettanto seccato se ⟦Ironforge=Forgiardente⟧ fosse stata presa dai Nani ⟦Dark Iron=Ferroscuro⟧, quindi non pensare che non capisca la tua situazione...", "Be', visto che questa è la tua direttiva principale, o come diavolo la chiamate di questi tempi, ho dato la mia parola che avrei fatto il possibile per assicurarmi che tu e i tuoi foste pronti a riprendervi la vostra casa... ed è proprio quello che farò.\n\nOgni volta che ti senti pront<o/a>, torna dal buon vecchio Thran e sarò felice di condividere con te quello che so. Addestrarti ha un costo, ma non sarà troppo caro. Buona fortuna.", 0xc08132de, 0xfd32d41c, 0xc7252d3e, 0x2813cf41, 0x954e3497, "....." },
  [3113] = { "⟦Encrypted Memorandum=Promemoria Codificato⟧", "Leggi il ⟦Encrypted Memorandum=Promemoria Codificato⟧ e parla con Solm Hargrin nella ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questo promemoria da passarti. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene dall'istruttore dei ladri Solm. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Mi fa piacere vedere che hai ricevuto il mio biglietto e sei venut<o/a>. Scusa se ho finto che fosse un promemoria dei tuoi superiori... senza offesa. Sapevo solo che noi due, insieme ad altri come noi, dobbiamo restare uniti.\n\nNon in molti pensano che sia la cosa migliore del mondo avere la tua gente e la mia rintanate nella stessa città, ma credo che possiamo andare d'accordo benissimo. Tu che ne dici?", "Qui me ne sto per conto mio, così non ci danno la colpa per le cose che spariscono, ma se ti serve qualcosa, un po' di addestramento o roba del genere, torna pure quando vuoi.\n\nTu e io ci capiamo. Sappiamo che, alla fine dei conti, ci si può fidare solo della famiglia... ed è proprio quello che abbiamo qui, no? Anche se Gnomeregan è stata... invasa, e qualunque altra cosa ci capiti, ci copriamo le spalle a vicenda. Giusto?", 0xb85fa8ab, 0xadca2176, 0xddd66e3c, 0x6c381354, 0x094ba3b2, "....." },
  [3114] = { "⟦Glyphic Memorandum=Promemoria con Glifi⟧", "Leggi il ⟦Glyphic Memorandum=Promemoria con Glifi⟧ e parla con Marryk Nurribit dentro ⟦Anvilmar=Forgiamara⟧, sopra la ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi davi una mano, mi hanno dato questo promemoria da passarti. Prenditi un po' di tempo per leggerlo quando puoi. Secondo me viene dall'istruttore dei maghi Marryk. Dacci un'occhiata e poi va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.", "Sì, che c'è, {race}? Parla più forte, se non ti dispiace. Dopo qualche birra non ci sento tanto bene.", "Ah, sì! Arti Arcane... certo.\n\nEcco cosa devi sapere, {name}: non cacciarti in troppi guai. Metti da parte qualche moneta per offrirmi una birra... o per gli incantesimi che potresti volere. E sta' alla larga da Gnomeregan, accidenti. A parte questo, buona giornata! Sarò qui se hai bisogno di me o vuoi addestrarti... o quel che è.", 0x201c49fc, 0x442b0781, 0x8ec02c25, 0x2a6a6bb4, 0xf605ca24, "....." },
  [3115] = { nil, "Leggi il Tainted Memorandum e parla con Alamar Grimm dentro ⟦Anvilmar=Forgiamara⟧, sopra la ⟦Coldridge Valley=Valle Crestafredda⟧.", "Mentre mi aiutavi, mi hanno dato questo memorandum da passarti. Prenditi un po' di tempo per leggerlo, quando puoi. Secondo me viene da Alamar, l'istruttore degli stregoni. Dacci un'occhiata e va' a cercarlo dentro ⟦Anvilmar=Forgiamara⟧, quando hai un momento.\n\nE stai attent<o/a>, {name}: quelli come te non godono di molta fiducia da 'ste parti.", "Splendido! Evidentemente hai ricevuto il mio memorandum.\n\nIgnora gli sciocchi che hai intorno, {name}. La ⟦Holy Light=Luce Sacra⟧?! La spada e lo scudo?! Non sono strade per menti aperte come le nostre. Guarda cosa ha fatto la magia \"normale\" alla nostra casa. Aggiungici quei dannati inventori, e la nostra razza è quasi scomparsa. E ora dobbiamo dipendere dai nani, che preferiscono passare il tempo ad allearsi con gli umani piuttosto che aiutarci a ricostruire la nostra casa. Siamo come cittadini di serie B. Hai visto come ci guardano?", "Ma niente di tutto questo conta. Ciò che conta è che hai visto la tua ⟦Holy Light=Luce Sacra⟧! Sai da dove viene davvero il potere. Capisci che avere alleati tutti nostri è molto più... prudente. Alleati speciali. Alleati che, qualunque sia il compito, obbediranno fino all'ultimo respiro.\n\nEd è qui che entro in gioco io, {name}. Posso insegnarti i primi rudimenti di questi poteri speciali. Vieni a trovarmi spesso e farò il possibile per insegnarti altri incantesimi.", 0x8ca3cdd0, 0xc0e37525, 0x9cf6a18f, 0xefc765ed, 0x0c6a5847, "e...." },
  [3116] = { "⟦Simple Sigil=Sigillo Semplice⟧", "Leggi il ⟦Simple Sigil=Sigillo Semplice⟧ e parla con Alyissia a ⟦Shadowglen=Vallombra⟧.", "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice dei guerrieri, Alyissia. Pare che Alyissia voglia parlarti, quando hai un momento. Leggilo e poi portaglielo.", "Ce l'hai fatta. Ne sono molto lieta.\n\nSono successe molte cose negli ultimi anni, {name}: la creazione di Teldrassil, la corruzione di molte creature della foresta, qui e altrove, la scoperta di terre che credevamo perdute come Feralas... tante cose, in così poco tempo. Ma queste sono solo alcune delle ragioni per cui siamo qui; la più importante è proteggere la nostra gente da altro male.", "Presto vedrai altri di razze diverse tra i rami della nostra casa: non lasciare che questo faccia nascere in te alcun pregiudizio. Sono i benvenuti. Ci aiuteranno quando potranno. Non tutti saranno altruisti, ma meritano un po' di fiducia.\n\nMa ora niente di tutto questo conta. Ora dobbiamo concentrarci su di te e su come puoi aiutare la nostra gente. Sono qui proprio per questo. Ti addestrerò nelle arti di <un/una> {class} man mano che diventerai più forte. Torna da me quando vuoi e farò il possibile per aiutarti.", 0x0b1c4d33, 0xd0e81f4b, 0xba14907e, 0x57568a0d, 0x95b00c23, "....." },
  [3117] = { "⟦Etched Sigil=Sigillo Intagliato⟧", "Leggi il ⟦Etched Sigil=Sigillo Intagliato⟧ e parla con Ayanna Everstride in cima ad Aldrassil, a ⟦Shadowglen=Vallombra⟧.", "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice dei cacciatori, Ayanna. Pare che Ayanna voglia parlarti, quando hai un momento. Leggilo e poi portaglielo.", "Sei arrivat<o/a>, e appena in tempo, {name}. Benvenut<o/a> a ⟦Shadowglen=Vallombra⟧.\n\nConfido che il mio sigillo ti abbia trovat<o/a> in buona salute e di buon umore?\n\nCome ti ho già detto, sono qui per addestrarti come <cacciatore/cacciatrice>: per domare le bestie che ti aiuteranno in battaglia, per usare l'arco con precisione infallibile, per rispettare le terre che chiamiamo casa e anche quelle al di là.", "Man mano che scopri ciò che ⟦Shadowglen=Vallombra⟧ ha da insegnarti, vieni a trovarmi: potrò aiutarti a capire meglio il tuo ruolo di <cacciatore/cacciatrice> e ciò di cui sei capace.\n\nSono tempi pericolosi, {name}: non dare per scontata l'abilità dei tuoi animali. In questo mondo ci sono cose più pericolose di quanto tu possa immaginare. Va' con Elune e torna di nuovo da me.", 0x4253939a, 0xd81ae928, 0xec30768a, 0x5c32ead3, 0x1a49e722, "....." },
  [3118] = { "⟦Encrypted Sigil=Sigillo Codificato⟧", "Leggi il ⟦Encrypted Sigil=Sigillo Codificato⟧ e parla con Frahun Shadewhisper a ⟦Shadowglen=Vallombra⟧.", "Questo sigillo mi è stato consegnato da un messaggero del nostro istruttore dei ladri, Frahun. Pare che Frahun voglia parlarti, quando hai un momento. Leggilo e poi portaglielo.", "Ciao, {name}. Sono contento che tu mi abbia trovato. Pensavo che ti fossi pers<o/a> lungo la strada.\n\nNon è successo niente di nuovo a ⟦Shadowglen=Vallombra⟧ da quando ti ho mandato il mio sigillo, ma lascio a te il compito di raccogliere informazioni. Parla pure con le altre persone intorno ad Aldrassil, se vuoi.", "Fino ad allora, sappi che la nostra gente è necessaria più che mai in questi tempi incerti. La pace con le altre razze può crollare in qualsiasi momento, e si parla molto di membri dell'⟦Horde=Orda⟧ che cercano di seminare ancora più sfiducia. Ricordalo.\n\nMan mano che acquisirai potere e ti sentirai più pront<o/a>, torna qui da me e vedrò di farti addestrare. È importante che tu sappia maneggiare l'arma che preferisci, tra le altre cose.", 0xd9ec7b68, 0x0f31aa64, 0x6d5e7cd1, 0x042e42d6, 0x1de17785, "....." },
  [3119] = { "⟦Hallowed Sigil=Sigillo Benedetto⟧", "Leggi il ⟦Hallowed Sigil=Sigillo Benedetto⟧ e parla con Shanda ad Aldrassil.", "Questo sigillo mi è stato consegnato da un messaggero della nostra istruttrice dei sacerdoti, Shanda. Pare che Shanda voglia parlarti, quando hai un momento. Leggilo e poi portaglielo.", "Mi fa piacere vedere che sei arrivat<o/a> così in fretta, {name}. Benvenut<o/a>.\n\nCome probabilmente avrai sentito, tutto Teldrassil è in fermento per l'andirivieni dei viaggiatori. Persino ad alcuni membri dell'⟦Alliance=Alleanza⟧ è stato concesso l'accesso ai rami di Teldrassil per incontrare altri Kaldorei che si preparano alle avventure che li attendono.", "Per ora non preoccuparti del mondo sotto Teldrassil. Ci sarà tempo per quello più avanti. Ora va' a parlare con gli altri a ⟦Shadowglen=Vallombra⟧: possono raccontarti meglio ciò che è accaduto. Aiutali come puoi e, ogni volta che senti di aver bisogno di altro addestramento, torna da me e ti insegnerò ciò che posso.", 0x83a52cc5, 0xf53c2a50, 0xca5600b8, 0x1f4e46af, 0x1e10f375, "....." },
  [3120] = { "⟦Verdant Sigil=Sigillo Verdastro⟧", "Leggi il ⟦Verdant Sigil=Sigillo Verdastro⟧ e parla con Mardant Strongoak, nell'albero di Aldrassil a ⟦Shadowglen=Vallombra⟧.", "Questo sigillo mi è stato consegnato da un messaggero del nostro istruttore dei druidi, Mardant. Pare che Mardant voglia parlarti, quando hai un momento. Leggilo e poi portaglielo.", "Ah, giovane {class}. Vedo che sei ansios<o/a> di proseguire i tuoi studi. Bene.\n\nMi chiedo: hai già trascorso molto tempo nel ⟦Emerald Dream=Sogno di Smeraldo⟧? Forse non sei ancora pront<o/a> per questo... Col tempo, ne sono certo.\n\nMa fino ad allora, dovremmo parlare d'altro.", "Per ora sarò il tuo mentore e la tua guida. È mio dovere insegnarti a interpretare non solo ciò che gli spiriti ci comunicano, ma anche le complessità e i segreti del ⟦Emerald Dream=Sogno di Smeraldo⟧.\n\nMan mano che imparerai e crescerai in potere, scoprirai di più sulla nostra trance del sonno. Ma fino ad allora, torna da me tutte le volte che vuoi e ti insegnerò ciò che posso sulle vie della nostra gente.", 0xbdc6d3be, 0x67426736, 0xaf299504, 0x240343bf, 0x0f1fd4af, "....." },
  [3121] = { "Una strana richiesta", "Porta il ⟦Shrunken Head=Teschio Rimpicciolito⟧ a Neeru Fireblade a Orgrimmar.", "Neeru Fireblade a Orgrimmar ha ciò che mi serve per cominciare qui! Ha preparato un intruglio che mi serve per il mio... be', vedrai.\n\nE ora fila, a Orgrimmar. Ecco, porta questo con te. È una testa rimpicciolita che ho promesso a Neeru in cambio delle erbe. È la testa di un povero nano in cui mi sono imbattuto nella foresta. Sono sicuro che Neeru ne sarà contento.\n\nTroverai Neeru nel Cleft of Shadow.", "Sì?", "Aspettavo che Uzer'i mi consegnasse questo...\n\nLascia che ti dia la miscela di erbe che ho preparato per i suoi... be', esperimenti...", 0x88b8407c, 0xaadb8829, 0x55fb2183, 0x0c07a888, 0x87bbbd29, "....." },
  [3122] = { "Ritorno dal santone Uzer'i", "Consegna la Neeru's Herb Pouch al santone Uzer'i a Feralas.", "Ecco le erbe, {name}. Portale al santone Uzer'i.\n\nE per favore fagli sapere che sono soddisfatto della testa rimpicciolita.", "Hai parlato con Neeru?", "È proprio ciò che mi serve per preparare il ricettacolo dello spirito, {name}. Presto vedremo se i miei ultimi incantesimi si dimostreranno potenti come speravo.\n\nUn momento, ti prego. Devo celebrare il rituale e applicare le erbe.", 0x8de30558, 0x030a5f43, 0x21a6e903, 0xc26e6919, 0xb1bd0568, "....." },
  [3123] = { "Alla prova del ricettacolo", "Vai nelle Entroterre e trova i silvagufi. Uccidine 10 e usa il Muisek Vessel per rimpicciolire e catturare i silvagufi caduti.\n\nPorta 10 Wildkin Muisek e il Muisek Vessel al santone Uzer'i, a Feralas.", "Sarà una prova: sia del rituale che ho compiuto, sia delle tue capacità. Prendi questo ricettacolo, {name}. Con esso avrai il potere di rimpicciolire una creatura e catturarla al suo interno.\n\nVa' nelle Entroterre e cerca le creature chiamate silvagufi, che un tempo erano gli animali prediletti di Elune, la dea degli elfi della notte. I tuoi bersagli sono i Vicious Owlbeast, i Primitive Owlbeast e i Savage Owlbeast, {name}. Uccidine 10 e usa il ricettacolo per rimpicciolirli e catturarli prima che i loro spiriti possano fuggire.", "Sei riuscit<o/a> a catturare i silvagufi?\n\nSe ci riesci, saremo pronti a rimpicciolire e catturare gli spiriti delle creature di Feralas.", "Dopo una morte violenta, lo spirito di una creatura può fuggire e cercare vendetta. Rimpicciolire le creature, come hai fatto tu, {name}, impedisce allo spirito di fuggire. Ora possiamo usarlo come ci pare!", 0xf5e2ea5b, 0xc317e71e, 0xcb4afa95, 0xc42ca850, 0xcd9b46cd, "....." },
  [3124] = { "⟦Hippogryph Muisek=Spirito di Piumaribelle⟧", "Uccidi 10 Frayfeather Hippogryph di qualsiasi tipo, poi usa il Muisek Vessel per rimpicciolirli e catturarli.", "Poiché hai dimostrato di essere sia degno di fiducia sia dotato della capacità di usare il ricettacolo, ora voglio che tu catturi un'altra creatura.\n\nDa molti anni gli ippogrifi sono fedeli compagni degli elfi della notte; i loro spiriti sono leali e saldi.\n\nIl tuo compito è uccidere 10 ippogrifi Piumaribelle e, in fretta, rimpicciolirli e catturarli con il ricettacolo, così che il loro spirito possa essere conservato. Troverai gli ippogrifi nell'⟦High Wilderness=Altopiano Selvaggio⟧, a sud di qui.", "Sei riuscit<o/a> a catturare gli ippogrifi?", "Se, dopo aver ucciso un animale, lasciassimo fuggire il suo spirito, potrebbe assumere la forma di una creatura ancora più grande. Non saremmo mai al sicuro dalla sua vendetta.\n\nQuello che ti ho affidato è un compito pericoloso, {name}. Ancora una volta l'hai portato a termine egregiamente.", 0xcb542dcf, 0xc078abbc, 0x0632f376, 0x0741c451, 0xe04d853a, "....." },
  [3125] = { "⟦Faerie Dragon Muisek=Spirito di Drago Fatato⟧", "Uccidi 8 Sprite Darter o Sprite Dragon. Usa il ricettacolo dello spirito per rimpicciolire e catturare i draghi fatati caduti.", "{name}, ora devo chiederti di catturare una creatura che all'aspetto può sembrare piuttosto fragile, ma è il suo spirito possente quello che cerchiamo davvero. I draghi fatati di cui parlo sono stati alleati degli elfi della notte. Dobbiamo catturarne uno, così che anche l'Orda possa trarre beneficio da questa forza dello spirito.\n\nEcco il ricettacolo dello spirito, {name}. Uccidi 8 Sprite Darter o Sprite Dragon e cattura il loro spirito. Li troverai a ovest di qui.", "Sei riuscit<o/a> a catturare lo spirito dei draghi fatati?", "Grazie, {name}. Ora i poteri spirituali del drago fatato saranno a nostra disposizione.\n\nSpero che tu sia dispost<o/a> a svolgere un altro compito per me.", 0x58acbb3c, 0xea4fd892, 0x3883f869, 0xf13dd93d, 0x98072748, "....." },
  [3126] = { "⟦Treant Muisek=Spirito di Treant⟧", "Uccidi 3 Wandering Forest Walker. Usa il ricettacolo dello spirito per rimpicciolire e catturare i treant caduti.", "I Wandering Forest Walker che vagano per la foresta sono il nostro prossimo bersaglio, {name}. Gli elfi della notte hanno arruolato i treant come alleati nella lotta contro l'Orda. Si muoveranno anche lentamente, ma il loro ruolo di protettori è innegabile.\n\nPresto potremo usare questo potere a nostro vantaggio.\n\nTrova 3 Wandering Forest Walker; uccidili e usa il ricettacolo dello spirito per rimpicciolirli e catturarli.", "Sei riuscit<o/a> a catturare i Wandering Forest Walker?", "Grazie, {name}. La nostra raccolta di spiriti è quasi completa.", 0x5084286b, 0xbd74e013, 0x97418bcc, 0xdb5de487, 0x65bce135, "....." },
  [3127] = { "⟦Mountain Giant Muisek=Spirito del Gigante di Montagna⟧", "Uccidi 7 Land Walker o Cliff Giant. Usa il ricettacolo dello spirito per rimpicciolire e catturare i giganti di montagna caduti.", "L'ultimo compito che ti chiederò è di andare a nord-ovest e trovare l'ultimo nemico.\n\nI giganti di montagna lasciarono le montagne per aiutare gli elfi della notte quando la Legione Infuocata comparve nel mondo. Li riconoscerai dalla loro mole enorme e da come il terreno comincia a tremare mentre attraversi le loro terre rocciose.\n\nNon vedo l'ora di imbrigliare un potere di quelle dimensioni. Uccidi 7 giganti di montagna, poi usa il ricettacolo dello spirito per catturare il loro potente spirito.", "Sei riuscit<o/a> a catturare i giganti di montagna?", "Pensa a tutte le possibilità di ciò che ora possediamo, {name}. Insieme ai materiali che hai raccolto, potrò imprigionare per sempre lo spirito di queste creature in qualunque cosa io desideri.", 0xa0493aa5, 0x716fafad, 0x2be653a6, 0x0f0962f1, 0x14052580, "....." },
  [3128] = { "Materiali naturali", "Porta 2 Ceppo Tagliato, 6 ⟦Encrusted Minerals=Minerali Incrostati⟧, 20 ⟦Resilient Sinew=Tendine Resiliente⟧ e 40 ⟦Metallic Fragments=Frammenti Metallici⟧ al santone Uzer'i all'⟦Camp Mojache=Accampamento Mojache⟧.", "Mi serviranno certi materiali per portare a termine la mia impresa... Puoi occupartene insieme agli altri compiti che ti affiderò.\n\nMi serve un ceppo tagliato da un treant di Feralas. Poi minerali incrostati, che si trovano sui giganti di montagna e sui draghi fatati a ovest. Trovami anche del tendine resiliente dai silvagufi delle Entroterre o dagli ippogrifi di Feralas. Infine, mi servirà una grande quantità di frammenti metallici da una qualsiasi delle creature che ho nominato.", "Sei riuscit<o/a> a raccogliere i materiali che mi servono?", "Eccellente! Questi materiali, uniti agli spiriti, dovrebbero darci proprio i risultati che volevamo.", 0xca658549, 0x59ecd377, 0x753f2fae, 0xd18efce3, 0xf2fd7adb, "....." },
  [3129] = { "Armi dello spirito", "Il santone Uzer'i vuole che tu aspetti un momento mentre prepara le armi.", "Infondere lo spirito nelle armi è un procedimento difficile. Ora che ho tutti i materiali necessari e lo spirito delle creature che hai catturato, posso cominciare. Aspetta, ti prego; torno tra un momento.", nil, "Come promesso, puoi scegliere, {name}. Lo spirito delle creature è stato sigillato per sempre nel potere di queste armi.\n\nOra puoi brandire la loro energia come se fosse tua. Usala bene.", 0xd12a1fcd, 0xb07b6bf4, 0x08cd8251, nil, 0x3a33ace4, "...m." },
  [3130] = { "Contro i Crestaostile", "Fa' rapporto a Latronicus Moonspear, a Feathermoon Stronghold.", "A questo punto ti indirizzerò al mio secondo in comando, Latronicus. Finora ha tenuto d'occhio da vicino le forze dei naga. Io valuterò la situazione generale riguardo ai naga; per quanto vorrei impegnare tutte le nostre forze contro di loro, lasciare la roccaforte esposta a un attacco diretto dell'⟦Horde=Orda⟧, o di peggio, non mi sembra la scelta migliore.\n\nComunque, Latronicus ti aspetta. Ottimo lavoro finora, {name}. Continua così.\n\nPuoi andare.", nil, "Eccellente, {name}: apprezzo lo spirito intraprendente in chi lavora con me.\n\nLa generale Feathermoon mi ha incaricato di affrontare i naga in modo diretto. I miei piani sono due: primo, indeboliremo le loro forze sia nel numero sia nel comando; secondo, scopriremo cosa stanno tramando tra le rovine. Con il tuo aiuto contrasteremo la presenza dei naga senza sacrificare la sicurezza generale della roccaforte.", 0xbaae3916, 0x9a6ce96c, 0xfc773ddd, nil, 0x746a107e, "...m." },
  [3141] = { nil, "Ascolta la storia di Loramus Thalipedes.", "Vuoi combattere i demoni? Faresti bene ad ascoltare la mia storia.", "Non interrompermi, {race}.", "E così sia...", 0x91a14087, 0xc42c437e, 0xc10e0092, 0x3220e0c2, 0xef47da38, "e...." },
  [3161] = { nil, "Marvon Rivetseeker, a Tanaris, vuole che tu raccolga 30 Ornamento Gahz'ridian.", "{name}, sono uno scienziato, ma in fondo al cuore anche un cacciatore di tesori!\n\nTanto tempo fa, quando i troll occupavano queste terre, crearono grandi quantità di ornamenti a immagine di Gahz'rilla, un'idra che veneravano come una divinità. Questi ornamenti sono scolpiti in un elemento che io chiamo \"Gahz'ridian\", dal nome del dio idra.\n\nNe ho trovati alcuni io stesso, ma vorrei averne altri da studiare: magari tu riesci a trovarne qualcuno?\n\nHo persino inventato un rilevatore che rende un gioco da ragazzi trovare il Gahz'ridian! Basta indossarlo e la ricerca comincia!", "Hai qualche difficoltà?\n\nIl Gahz'ridian si trova un po' ovunque a Tanaris, {name}, quindi continua a cercare!", "Perfetto; questi ornamenti sono perfetti per i miei studi. Grazie mille dell'aiuto, {name}.\n\nOh, posso riavere il mio elmo?", 0x0b56dac1, 0x4998da48, 0x0dde7e0d, 0xdaa6c3da, 0x30577316, "e...." },
  [3181] = { "Il corno della bestia", "Porta il ⟦Margol's Gigantic Horn=Corno Gigante di Margol⟧ alla montanara Pebblebitty.", "Il corno gigantesco è pieno di graffi e crepe. Uno strano oggetto di metallo è conficcato nella superficie ruvida.\n\nEsaminandolo meglio, noti che il metallo è in realtà la testa di un'ascia spezzata. Sul metallo sono incise le seguenti parole:\n\nProprietà della montanara Pebblebitty.\n\nQuando provi a staccare la testa d'ascia spezzata, va in mille pezzi.\n\nOps!", "No, non aprirò il cancello.", "Cos'hai lì? Un falso, ovviamente!\n\nMi sono trovata faccia a faccia con Margol e so per certo che il suo corno è grande almeno otto volte quello che hai in mano, {name}. Probabilmente l'hai preso a uno Stormsnout nelle ⟦Barrens=Savane⟧. No, <signore/signora>, non puoi fregare Pebblebitty!", 0x2e5f0c0b, 0xb93db2d2, 0x3392c641, 0x2dfa9f43, 0xe1a41449, ".....", nil, nil, nil, nil, 0x7710ebcd },
  [3182] = { "⟦Proof of Deed=Certificazione di Eroismo⟧", "Porta il ⟦Margol's Gigantic Horn=Corno Gigante di Margol⟧ al curatore Thorius a ⟦Ironforge=Forgiardente⟧.", "Ti aspetti che creda a una storia del genere? Il vero corno avrebbe ancora la mia testa d'ascia spezzata conficcata nella superficie.\n\nSenti, porta quel falso evidente al curatore Thorius a ⟦Ironforge=Forgiardente⟧. Se convalida la tua versione, riceverai una certificazione di eroismo. Riportami quella certificazione e ti darò la chiave della ⟦Searing Gorge=Gorgia Rovente⟧.\n\nMuoviti!", "Ma salve, <giovanotto/signorina>. Ti andrebbe una visita guidata del museo?", "Cos'è questo?\n\nCielo, non ci credo! Ti rendi conto di cosa hai qui, {race}? Questo è il corno di Margol la Furiosa! Margol, la rovina di ogni archeologo che abbia mai messo piede nella ⟦Searing Gorge=Gorgia Rovente⟧.\n\nPosso tenerlo?", 0x63d25e29, 0x5939f719, 0xb834107c, 0x8e279b3a, 0xe346b32f, ".....", nil, nil, nil, 0xf600fc7f, nil },
  [3201] = { "Finalmente!", "Riporta la ⟦Proof of Deed=Certificazione di Eroismo⟧ alla montanara Pebblebitty.", "Non posso credere che Pebblebitty abbia dubitato dell'autenticità del corno. Detto tra noi, credo che sia solo gelosa. So che voleva davvero uccidere quella bestia con le sue mani, con tutto quell'\"incidente\" e il resto.\n\nQuindi ti serve una certificazione di eroismo? Dopo il contributo che hai appena dato al museo, non sarà un problema.\n\n<Il curatore Thorius comincia a compilare un grosso documento.>\n\nEcco fatto! Puoi riportarla a Pebblebitty.", "Non ci credo.", "Non so come una mezza calzetta come te abbia avuto la meglio su Margol, ma un patto è un patto. Ecco la chiave.\n\nSe dopo ti succede qualcosa, sarà colpa tua.", 0xe8848fc6, 0xf8522386, 0x06cca93a, 0x422d6af8, 0x9cad295e, "....." },
  [3221] = { "Parla con Renferrel", "Parla con lo speziale Renferrel alla ⟦Sepulcher=Mausolea⟧.", "Mentre eri fuori ad aiutare i nostri Inseguitori della Morte, lo speziale Renferrel ti ha mandato a chiamare. Non mi ha dato dettagli, ma voleva parlarti dei cuori di lupo che gli hai consegnato.", nil, "Ah, molto bene. C'è una questione riguardo ai cuori di lupo che mi hai portato prima che richiede la nostra attenzione.", 0x043c659a, 0x3eb5474e, 0x5ca32cb6, nil, 0x95d52ec0, "...m." },
  [3261] = { nil, "Parla con Jorn Skyseer a Camp Taurajo.", "Il tuo tempo con me è finito, {name}. Per imparare di più devi andare a Camp Taurajo, a sud, e parlare con Jorn Skyseer. Sarà lui a guidarti d'ora in poi.", nil, "Salute, giovane. Sei qui per percorrere il sentiero del cacciatore?\n\nMolto bene. Cominciamo.", 0x4d1b9bdc, 0x038243ce, 0x2e23d78b, nil, 0x88022d9d, "e..m." },
  [3281] = { "⟦Stolen Silver=Argento Rubato⟧", "Porta l'⟦Stolen Silver=Argento Rubato⟧ a Gazrog, al ⟦Crossroads=Crocevia⟧.", "Avrai anche ucciso i raptor, ma l'argento che hanno rubato va recuperato! Mi riferiscono che i raptor hanno un grande gruppo di nidi a sud di ⟦Ratchet=Porto Paranco⟧, noto come Raptor Grounds. Probabilmente hanno portato lì il nostro argento rubato.\n\nVa' in quel covo di raptor e cerca l'argento rubato. Quando lo trovi, riportamelo.", "Hai l'argento?", "Ah-ah! Allora i raptor hanno davvero nascosto l'argento nella loro tana. È difficile credere che queste bestie possano desiderare l'argento. Forse le storie sulla loro intelligenza non sono così lontane dal vero come pensavo!\n\nGrazie, {name}. Prendi questo come ricompensa per il servizio che ci hai reso, e sappi che le guardie del Crocevia devono a te la paga del mese prossimo.", 0xe35e0500, 0x12efa283, 0x2983e37d, 0xf2e4b6ca, 0x1f48ebc1, "....." },
  [3301] = { nil, "Parla con Mura Runetotem, alla ⟦Sepulcher=Mausolea⟧.", "La mia compagna di clan, Mura Runetotem, è andata a ⟦Silverpine=Pinargento⟧ per aiutare i nostri alleati non morti. ⟦Silverpine=Pinargento⟧ è una foresta malata, una foresta morente, e Mura sperava di riportarla alla vita. Forse la strana vita che si trova qui nelle ⟦Barrens=Savane⟧ può aiutarla nel suo lavoro a ⟦Silverpine=Pinargento⟧.\n\nPrendi un campione dei gusci che hai raccolto e portalo a Mura, a ⟦Silverpine=Pinargento⟧. Si trova alla ⟦Sepulcher=Mausolea⟧. Con un po' di fortuna, studiare il guscio le darà l'intuizione che le serve per guarire quel luogo morente.", "Sento su di te la polvere delle ⟦Barrens=Savane⟧, {class}. Hai viaggiato a lungo.", "Ah, che cos'è questo? Questo guscio ha un bagliore interno, come se pulsasse ancora di vita. Straordinario! Devo studiarlo più a fondo.\n\nGrazie, {name}. Con un po' di fortuna, questo guscio custodirà un segreto che potrò usare per aiutare la povera terra di ⟦Silverpine=Pinargento⟧.", 0x6ec1c3d1, 0x36a63bfc, 0xc0bed28e, 0xf5936a1e, 0x520dd133, "e...." },
  [3321] = { "Hai perso questo?", "Aspetta che Trenton finisca il suo lavoro.", "Hai fatto molto per l'Ordine, {name}. La sola dedizione che serve per arrivare fin qui avrebbe scoraggiato chiunque. Non ho alcun dubbio, e non ne ha Galvan, che tu sia uno di noi.\n\nPer questo credo che tu meriti una piccola ricompensa. Non è niente, davvero, solo un ninnolo. Forse ne conosci già le proprietà, perché credo proprio che sia ciò che ti ha portato da noi la prima volta.", "Oggi concludiamo la celebrazione della tua dedizione all'Ordine.", "Alzati e ricevi il tuo riconoscimento, {name}, fabbro del Mithril Order.", 0x6c8c8581, 0xc8d14884, 0x3d6a7db3, 0x38770b41, 0x65d75799, "....." },
  [3341] = { "Porta la fine", "Andrew Brownell vuole che tu uccida Amnennar the Coldbringer e riporti il suo teschio.", "Nelle ⟦Barrens=Savane⟧ si trova un orrendo groviglio di rampicanti chiamato ⟦Razorfen Downs=Sotterranei di Lamaspina⟧. Se le nostre prime osservazioni di quel luogo avevano rivelato poche minacce, le nostre scoperte più recenti sono molto più gravi...\n\nI verrospini dei ⟦Razorfen Downs=Sotterranei di Lamaspina⟧ si sono alleati con il Flagello. Ora li governa un lich di nome Amnennar l'Araldo del Freddo, che usa il potere della sua immensa coscienza per controllare ogni loro mossa.\n\nAmnennar ha un legame telepatico diretto con Ner'zhul; dobbiamo spezzare questo legame, {name}. L'Araldo del Freddo deve trovare la sua fine.", "Questa faccenda è della massima importanza, {name}. Dobbiamo fermare ogni tentativo del Flagello di rinforzare i suoi ranghi.", "La lealtà di un lich è incrollabile, {name}. Fa' sapere loro che una simile lealtà porterà loro solo distruzione.", 0x1f522a28, 0xa3eec115, 0xdcaf73d5, 0xb3d2ae26, 0xeda91eee, "....." },
  [3361] = { "Il dilemma del profugo", "Porta la ⟦Felix's Box=Scatola di Felix⟧, la ⟦Felix's Chest=Cassa di Felix⟧ e il ⟦Felix's Bucket of Bolts=Contenitore di Viti di Felix⟧ a Felix Whindlebolt, a ⟦Anvilmar=Forgiamara⟧.", "Abbiamo cacciato i trogg da Gnomeregan, ma poi è andato tutto terribilmente storto! Ora la nostra casa è completamente irradiata e noi gnomi siamo sparpagliati per tutto il Dun Morogh.\n\nNella fretta di fuggire dalle radiazioni ho perso tutti i miei effetti personali e i miei attrezzi. Sono stati i troll a prenderli. Mi hanno rubato la cassa, la scatola e il contenitore di viti! Se li sono portati nei loro accampamenti a sud-ovest di ⟦Anvilmar=Forgiamara⟧.\n\nIo non sono un avventuriero... potresti ritrovare le mie cose e portarmele qui, per favore?", "Santo cielo, {name}, questo posto non fa proprio per uno come me. Qui ci sono tante brutte creature quante ce n'erano a Gnomeregan prima dell'incidente!\n\nHai le mie cose? Se non le hai, chissà cosa ne avranno fatto i troll...", "Evviva, li hai trovati! Sei proprio la mia salvezza, amico mio. Ecco, non è molto, ma è qualcosa per il disturbo che ti ho dato! Grazie!", 0x71d49aac, 0x8c5c5442, 0x7b36eefc, 0xe6a8fff5, 0x6f038cb6, "....." },
  [3362] = { "⟦Thistleshrub Valley=Valle dei Cardosecco⟧", "Tran'rek a ⟦Gadgetzan=Meccania⟧ vuole che tu uccida 8 Gnarled Thistleshrub e 8 Thistleshrub Rootshaper.", "Hai mai visto la ⟦Thistleshrub Valley=Valle dei Cardosecco⟧? È un posto parecchio pericoloso, {name}.\n\nQuelle strane bestie che ci vivono, non mi fido di loro nemmeno per un minuto! Gnarled Thistleshrub e Thistleshrub Rootshaper, mi pare si chiamassero così...\n\nComunque, io voglio entrare nella valle, ma con tutti quei Thistleshrub in giro non ci torno per niente al mondo. Ed è qui che entri in gioco tu: se ne fai fuori un po', potrei anche pensare di tornarci. Che ne dici, {name}? Mi dai una mano?", "Vorrei dare un'occhiata più da vicino a quei cactus nella valle... Quindi lasciane qualcuno tutto intero, eh?", "Sono così grossi? Forse dovrò rivedere il mio piano...\n\nMa tu hai mantenuto la tua parte dell'accordo, quindi ecco ciò che ti ho promesso.", 0x8cd85dbd, 0x4d0981fc, 0x3c4f4162, 0x43b6929c, 0x1a09be46, "....." },
  [3364] = { "Consegna di Scalding Mornbrew", "Porta uno Scalding Mornbrew a Durnan Furcutter, dentro ⟦Anvilmar=Forgiamara⟧, prima che si raffreddi tra cinque minuti!", "Accidenti! Dovevo portare questo delizioso Scalding Mornbrew a Durnan Furcutter, dentro ⟦Anvilmar=Forgiamara⟧, già da un pezzo, ma prima ho dovuto consegnarne uno a Grelin qui. Non arriverò mai a ⟦Anvilmar=Forgiamara⟧ prima che si raffreddi!\n\nTu sembri veloce. Forse ce la fai. Questa tazza resterà calda solo per altri cinque minuti, e Durnan non ha ordinato un mornbrew \"freddo\", quindi muoviti. ⟦Anvilmar=Forgiamara⟧ è a nord-est, un insediamento scavato nella montagna.\n\nGrazie, {name}, e non dimenticare di riportarmi il boccale!", "Sì, sono Durnan Furcutter. Hai qualcosa per me?", "Ah, bene, questo sì che ci vuole. Permettimi di fare una piccola pausa mentre mi godo questo mornbrew bollente!", 0xf0284895, 0x5506e41b, 0xbce4688b, 0x65bfe9d2, 0xd3b1def7, "....." },
  [3365] = { "Il ritorno del boccale", "Restituisci il ⟦Nori's Mug=Boccale di Nori⟧ a Nori Pridedrift.", "Ah, questo sì che ci voleva! Niente di meglio di un mornbrew caldo, anzi, BOLLENTE, in una fredda giornata d'inverno per scaldarti il fondo dell'anima.\n\nEcco qua, {name}: fammi un favore e riporta questo boccale vuoto a Nori da parte mia, eh?", "Spero che il mornbrew bollente sia arrivato a Durnan in tempo! Ti sei ricordat<o/a> di riportarmi il boccale?", "Eccellente, {name}! Non immagini quanti corrieri incontro che si dimenticano di fare una cosa semplice come riportare il boccale. I boccali non crescono sugli alberi, o almeno così mi dicono!\n\nEcco un piccolo compenso per il disturbo. Grazie ancora per l'aiuto.", 0x8db5a5c3, 0x1075f009, 0x2d2a6b06, 0x795e536d, 0x3d3438fe, "....." },
  [3366] = { "La ⟦Glowing Shard=Scheggia Brillante⟧", "Va' a ⟦Ratchet=Porto Paranco⟧ per scoprire il significato del ⟦Nightmare Shard=Frammento d'Incubo⟧.", "Il frammento è di un verde brillante e, benché solido, appena sotto la superficie sembra vorticare del fumo. Non riesci a smettere di fissare le profondità del cristallo; al tempo stesso, sai che c'è qualcosa di molto inquietante in esso.\n\nForse dovresti vedere se qualcuno a ⟦Ratchet=Porto Paranco⟧ sa dirti di più su questo strano frammento.", nil, nil, 0x855951c0, 0xa0c652c0, 0xf1eddfb4, nil, nil, "...mm" },
  [3367] = { "Le pietre di Suntara", "Aiuta Dorius a tornare a ⟦Ironforge=Forgiardente⟧.", "<Dorius geme.>\n\nSono ferito gravemente, {race}. Mi gira... la testa... Il mondo gira... Sanguino... dentro.\n\nDevo tornare a ⟦Ironforge=Forgiardente⟧. Aiutami, {name}.", "Non ce la farò...", "Questa lettera è caduta a Dorius quando gli hanno sparato.", 0x49144676, 0xb36e1cd6, 0xa87dc59b, 0xf779cab5, 0x8d0bdc13, "....." },
  [3368] = { "Le pietre di Suntara", "Porta la ⟦Singed Letter=Lettera Bruciata⟧ a Thorius a ⟦Ironforge=Forgiardente⟧. Si trova nella Hall of Explorers.", "Fratello,\n\nse stai leggendo questa lettera, io non ci sono più. Non so come sia arrivata fino a te, ma ringrazia e ricompensa chi se ne è occupato.\n\nQuanto alle pietre: esistono, e le hanno i Ferroscuro. Il loro capo, ⟦Lathoric the Black=Lathoric il Nero⟧, usa il potere delle pietre per rendere schiava la mia squadra di scavo. Li hanno portati alla Caldera Magmatica. Le loro menti sono corrotte, lavorano notte e giorno per completare qualcosa chiamato Obsidion.\n\nAiutali, fratello. È l'ultimo desiderio di un uomo morto.\n\n-Dorius", "<Thorius singhiozza.>", "<Thorius si asciuga il viso.>\n\nNel nome della Luce, il suo desiderio sarà esaudito. Lo giuro.", 0x49144676, 0x54c7e8e2, 0x6d1813a8, 0xd7580be9, 0x125e0856, "....." },
  [3369] = { "Negli incubi", "Porta il ⟦Nightmare Shard=Frammento d'Incubo⟧ a Hamuul Runetotem, sull'⟦Elder Rise=Altura degli Anziani⟧.", "Questo frammento custodisce grandi segreti: è l'essenza pura del ⟦Emerald Dream=Sogno di Smeraldo⟧. Eppure ciò che vedo in questo frammento non è un sogno; una visione del genere si chiamerebbe piuttosto un incubo.\n\nNon voglio allarmarti, {name}, ma credo sia meglio che tu consegni questo frammento nelle mani di un saggio druido il prima possibile.\n\nÈ Hamuul Runetotem, sull'⟦Elder Rise=Altura degli Anziani⟧, che devi trovare. Va' a ⟦Thunder Bluff=Picco del Tuono⟧. Non posso dirti di più.", "Posso aiutarti in qualche modo?", "Ti ha mandato Falla? Bene, vediamo questo frammento di cui, a quanto dici, era così restia a parlare...\n\n<Hamuul scruta nel frammento>\n\nOh... non avevo... Be'.\n\n{name}, grazie per avermelo portato. Ma non è saggio parlare di cose come questa, te lo consiglio. Sono questioni di cui non dovresti occuparti.\n\nDiciamo solo che nel ⟦Emerald Dream=Sogno di Smeraldo⟧ le cose non stanno come pensavamo...\n\nForse in futuro le nostre strade si incroceranno di nuovo.", 0x768d8fac, 0xe8a601a6, 0x45fe85a3, 0x42e8d794, 0xcb46c0bc, "....." },
  [3370] = { "Negli incubi", "Porta il ⟦Nightmare Shard=Frammento d'Incubo⟧ a Mathrengyl Bearwalker a Darnassus.", "Questo frammento custodisce grandi segreti: è l'essenza pura del ⟦Emerald Dream=Sogno di Smeraldo⟧. Eppure ciò che vedo in questo frammento non è un sogno; una visione del genere si chiamerebbe piuttosto un incubo.\n\nNon voglio allarmarti, {name}, ma credo sia meglio che tu consegni questo frammento nelle mani di un saggio druido il prima possibile...\n\nÈ Mathrengyl Bearwalker, del ⟦Cenarion Circle=Circolo Cenariano⟧, che devi trovare. Va' a Darnassus. Non posso dirti di più.", "Posso aiutarti in qualche modo?", "Ti ha mandato Falla? Bene, vediamo questo frammento di cui, a quanto dici, era così restia a parlare...\n\n<Mathrengyl scruta nel frammento>\n\nOh... non avevo... Be'.\n\n{name}, grazie per avermelo portato. Ma non è saggio parlare di cose come questa, te lo consiglio. Sono questioni di cui devono occuparsi soltanto i druidi cenariani.\n\nDiciamo solo che nel ⟦Emerald Dream=Sogno di Smeraldo⟧ le cose non stanno come pensavamo...\n\nForse in futuro le nostre strade si incroceranno di nuovo.", 0x768d8fac, 0x92596199, 0x891baadf, 0x42e8d794, 0x1d9fadb2, "....." },
  [3371] = { "Giustizia nanica", "Torna alla ⟦Searing Gorge=Gorgia Rovente⟧ e trova la squadra archeologica di Dorius.", "C'è un buco vuoto, un abisso, dove un tempo c'era il mio cuore, {name}. Non mi riprenderò presto dalla perdita di Dorius. Devo realizzare il suo ultimo desiderio: i responsabili di questo omicidio a sangue freddo devono essere consegnati alla giustizia.\n\nTorna alla ⟦Searing Gorge=Gorgia Rovente⟧ ed esaudisci la sua ultima richiesta: libera i suoi uomini.", nil, "Lascia stare me, aiuta gli altri.", 0x040d1a14, 0x1d757d60, 0x16a99128, nil, 0x7f1395e5, "...m." },
  [3372] = { "Liberali", "Trova il ⟦Mysterious Artifact=Manufatto Misterioso⟧ sorvegliato dai Twilight's Hammer Idolater nel quadrante nord-occidentale della ⟦Searing Gorge=Gorgia Rovente⟧.", "Liberali, {race}. Anche dopo che i loro corpi hanno ceduto, il potere di Suntara li costringe a portare a termine i loro compiti.\n\nL'altare di Suntara è la chiave. Va' a nord-ovest; sulle colline sopra la grotta... il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ sorveglia una reliquia. Recuperala e posala sull'altare di Suntara.\n\n<L'archeologo morente si accascia.>", "L'altare è vuoto.", "Posi il manufatto misterioso sull'altare di Suntara.", 0x2d84374c, 0xdca71d8a, 0x3df5ce39, 0xa6dc1ec3, 0xcfff63de, "....." },
  [3373] = { "L'essenza di Eranikus", "Metti l'Essence of Eranikus nella fonte dell'essenza che si trova in questa tana, nel Tempio di Atal'Hakkar.", "Quando tocchi la gemma, una voce profonda risuona nella tua mente.\n\n«Mortale, ascolta questa supplica. Io sono Eranikus dello Stormo dei Draghi Verdi, custode di questo tempio maledetto. Il mio compito di impedire che i troll riportassero in vita il loro abominio di dio è, per ora, fallito. Mentre infondo in questa gemma una parte della mia essenza, sento la mia presa sul Sogno contorcersi nel caos. Ti prego: metti questa gemma nella fonte dell'essenza della mia tana, e lascia che la nostra magia purifichi la mia mente dalla corruzione, perché io possa riposare.»", "Mentre ti avvicini alla fonte dell'essenza di cui ti ha parlato Eranikus, la sua voce sfiora di nuovo la tua mente.\n\n«Sì, mortale, questa fonte dell'essenza redimerà la parte incorrotta della mia mente che resta infusa in questa gemma. Metti la gemma nella fonte e lascia che la magia dello Stormo dei Draghi Verdi purifichi il mio essere dalla corruzione e dalla contaminazione. Solo allora troverò la vera liberazione, e solo allora lo Stormo potrà riaffermare la sua custodia sugli Atal'ai.»", "Metti la gemma nella fonte dell'essenza.\n\n«Grazie, mortale, hai... no... questo, questo non può essere! No! La corruzione di questo dio maledetto contamina persino la sacralità di una fonte dell'essenza dello Stormo dei Draghi Verdi! No, ti prego, sento la mia essenza strapparsi via da me! CHE DOLORE! Sento la stretta di un incubo eterno che si impadronisce di me...»\n\n«Mortale, ti imploro! Trova uno dello Stormo dei Draghi Verdi che fermi tutto questo... aiutami... sono incatenato nelle tenebre... per sempre nell'agonia... ti prego, non torturare...»", 0x1b4a9b28, 0x3918be39, 0xea0661cc, 0x25aa7bf2, 0xc5685f76, "....." },
  [3374] = { "L'essenza di Eranikus", "Porta la ⟦Oathstone of Ysera's Dragonflight=Pietra del Giuramento dello Stormo di Ysera⟧ e la Chained Essence of Eranikus a Itharius, nella ⟦Swamp of Sorrows=Palude del Dolore⟧. Lì sceglierai se aiutare o no lo Stormo di Ysera.", "Attivi la Pietra del Giuramento e Itharius parla direttamente alla tua mente attraverso la pietra.\n\n«Accettando l'incarico racchiuso in questa Pietra del Giuramento, accetti di aiutare la mia causa e quella dello Stormo di Ysera nel redimere l'anima corrotta di Eranikus. Il primo sacrificio, uno dei molti che senza dubbio faremo tu e io, sarà consegnarmi la gemma che tiene incatenata la parte libera della mente di Eranikus che ancora resta.»\n\n«Fallo, {name}, e lavoreremo insieme per redimere un'anima degna di redenzione.»", "Eccoci, {name}, a un altro bivio. È giunto il momento di fare un'altra scelta. Quale scelta fai, mortale?", "Hai fatto la tua scelta, e così ha inizio. Finora le tue scelte sono state quelle che considererei giuste; le tue azioni e le tue imprese d'ora in poi decideranno se continuerà a essere così.", 0x1b4a9b28, 0x028ab8e5, 0x066c19dc, 0x05791b0e, 0x2675acb2, "....." },
  [3376] = { "Abbattere Sharptusk!", "Porta la testa del capo Sharptusk Thornmantle al valoroso Windfeather, a ⟦Red Cloud Mesa=Mesa Nuvola Rossa⟧.", "{name}... ho sentito parlare di te, nuov<o/a> arrivat<o/a>. Forse sarai tu ad aiutarci, dove altri hanno fallito.\n\nNoi tauren ci siamo ricavati una casa in questa terra, ma non senza un prezzo. I verrospini ⟦Bristleback=Mantotergo⟧ della ⟦Brambleblade Ravine=Depressione di Rovoaguzzo⟧, guidati dal capo Sharptusk Thornmantle, ci rendono la vita difficile con la loro guerra incessante contro di noi. Ti incarico di portarmi la testa del capo!\n\nLo troverai nella gola a est, nel loro villaggio di fortuna.", "Sharptusk non ci darà più fastidio quando mi avrai portato la prova della sua morte. È la sua testa che voglio, {name}.\n\nNoi tauren viviamo per la caccia, e non c'è caccia più grande di quella contro chi è abbastanza astuto da poter dare la caccia a noi. Se riuscirai in questo compito, giovane, comincerai a capire cosa intendo.", "Oggi giustizia è stata fatta grazie alla tua prontezza, {name}. Che quest'impresa serva da monito a chiunque voglia minacciare la nostra casa.\n\nTi sei guadagnat<o/a> questa ricompensa che ti aiuterà nel tuo cammino, giovane {class}.", 0x1204c4b0, 0xa500ec30, 0x72c9ab91, 0x5068b9a6, 0x42acf4c0, "....." },
  [3377] = { "⟦Prayer to Elune=Preghiera a Elune⟧", "Ascolta il racconto di Zamael.", "Mi aiuterai, mortale? Ascolta il mio racconto.", "Lasciami finire la mia storia.", "Ho accettato il mio destino qui in questa gabbia, ma la preghiera deve essere ritrovata.", 0x033b2fe0, 0x90a3b258, 0x68d49b69, 0x5c717573, 0x6d9aa4c2, "....." },
  [3378] = { "⟦Prayer to Elune=Preghiera a Elune⟧", "Trova la ⟦Prayer to Elune=Preghiera a Elune⟧ e portala ad Astarii Starseeker a Darnassus.", "Mi aiuterai, mortale? Troverai la preghiera a Elune?\n\nCome ti ho detto, la preghiera era incisa su una tavoletta d'oro. Uno di questi furfanti adoratori di idoli deve averla con sé.\n\nSe recupererai la mia preghiera, portala ad Astarii Starseeker a Darnassus. Poco importa che la mia fede si sia riaccesa dopo le innumerevoli azioni malvagie che ho compiuto contro questo mondo e i suoi abitanti, ma la mia preghiera deve essere ascoltata. L'assoluzione è l'ultima cosa che mi aspetto.", "Che cosa ti porta al ⟦Temple of the Moon=Tempio della Luna⟧, {name}?", "Elune ti sorride questa sera, {name}. Le hai restituito un'anima perduta. Accetta questo come segno della nostra gratitudine.", 0x033b2fe0, 0x4ad2902a, 0x5e5c5ebc, 0x08a22fe6, 0xa1cb3fb2, "....." },
  [3379] = { nil, "Uccidi il gruppo di Shadow Silk Poacher che si aggira per la ⟦Searing Gorge=Gorgia Rovente⟧. Nilith ha motivo di credere che siano cinque quelli da sterminare. Torna da Nilith nella ⟦Searing Gorge=Gorgia Rovente⟧ quando avrai finito.", "I ragni della ⟦Searing Gorge=Gorgia Rovente⟧ sono una fonte preziosissima di seta d'ombra. Come sai, la seta d'ombra è molto ricercata dagli artigiani del nostro mestiere.\n\nDi recente un gruppo di bracconieri ha invaso queste terre, massacrando ragni in massa senza il minimo pensiero per gli effetti a lungo termine delle loro azioni. Il primo compito che ti chiedo, quindi, è semplice: trovali... e falli fuori.\n\nComincia a cercare a nord.\n\nSe ti serve aiuto, parla con Raze.", "Che informazioni hai?", "Ottimo lavoro, {name}.\n\nDi certo questo è un pezzo di stoffa dell'ombra che non hai ancora visto.", 0xa980b06f, 0xcb129914, 0xdfea1643, 0x9a301625, 0xf0243f05, "e...." },
  [3380] = { "Il Tempio di Atal'Hakkar", "Trova Marvon Rivetseeker a Tanaris.", "In questo mondo ci sono spiriti inquieti, {name}. Spiriti contaminati dal loro isolamento, legati a un male antico...\n\nHo sentito parlare di un luogo che giace nelle profondità della terra, confinato laggiù da poteri più grandi di qualunque altro io abbia mai visto.\n\nSe vuoi saperne di più su questo luogo, il Tempio di Atal'Hakkar, cerca un goblin di nome Marvon Rivetseeker. Ha studiato molti luoghi antichi del mondo, e l'ultima notizia che si ha di lui è che ha lasciato la sua casa a ⟦Ratchet=Porto Paranco⟧ per studiare le rovine troll di Tanaris.", nil, "Sì, il Tempio di Atal'Hakkar: posso dire di averlo visto con i miei occhi. Forse ti piacerebbe saperne di più?\n\nHai l'aria di chi ama l'avventura... So cose che potrebbero incuriosirti...", 0x49245186, 0xd5fc3f18, 0x8e0c57bd, nil, 0x8af0f4e1, "...m." },
  [3381] = { "Un incontro con il maestro", "Porta 2 Piuma di Ippogrifo Intonsa a Sanath Lim-yo ad Azshara, se vuoi parlare con il suo maestro.", "Ah, <un/una> giovane {race} venut<o/a> a parlare con Sanath. Che giornata meravigliosa! Sono così onorato che tu mi conceda la tua presenza. Grazie!\n\nTi prego... non essere così arrogante da credere che il mio sarcasmo fosse un complimento. Mettiamo in chiaro una cosa: non mi piaci. Ma questa conversazione non riguarda noi due: riguarda il mio maestro.\n\nPortami un paio di piume di ippogrifo per le mie frecce e ti darò il permesso di vederlo. Mi ha chiesto di mandargli gli avventurieri che si dimostrano abbastanza degni.", "Resto qui per volere del mio maestro. Mi ha concesso di chiedere qualsiasi prezzo per il trasporto fino alla sua torre. Per ora, a ogni viaggiatore chiedo solo due piume, così posso continuare a fabbricare le mie frecce speciali.\n\nSe non stai attento, alzo il prezzo. Che ne dici di mezza dozzina di monete d'oro?\n\nGià, lo immaginavo. Bada a come ti comporti e il prezzo resterà quello che è.", "Due piume, proprio come ti avevo chiesto. E per niente male.\n\nPront<o/a>, allora? Basta una parola e ti metti in viaggio.\n\nOh, e ancora una volta, bada a come ti comporti... il mio maestro non sopporta gli imbecilli, ma è molto generoso con chi lo accontenta.", 0x7ce7cb7c, 0x97998acb, 0xcdcdd2e9, 0x33ecde61, 0x26a739ed, "....." },
  [3382] = { "Un equipaggio sotto attacco", "Difendi la capitana Vanessa Beltis, il suo equipaggio e i passeggeri della Horizon Scout dall'attacco dei naga. La capitana Vanessa Beltis deve sopravvivere.", "Eravamo appena al largo della costa, in cerca di un approdo sicuro dove gettare l'ancora. Il sole era tramontato da nemmeno un'ora quando hanno attaccato... quei maledetti naga!\n\nNon so cosa cercassero, ma è chiaro che non l'hanno trovato: sono già tornati una volta. Un paio delle mie vedette sono di guardia all'ingresso della valle, per darci l'allarme in tempo quando arriverà il prossimo attacco.\n\nMi dispiace che tu sia arrivat<o/a> proprio ora, {name}, ma non dipende da me.\n\nSei pront<o/a> per la battaglia della tua vita?", "Sarà una battaglia dura...", "Ce l'hai fatta! Grazie! Questa è stata di certo una delle battaglie più brutali a cui abbia mai partecipato. Non so come ringraziarti.\n\nVorrei solo che più membri del mio equipaggio fossero sopravvissuti a questa prova.\n\nTi chiederei di parlare con i passeggeri della Horizon Scout sopravvissuti. Alcuni avevano affari in zona, e potrebbero avere una o due richieste per te, se te la senti. Grazie ancora per tutto il tuo aiuto.", 0x81d369b3, 0x8cfbc87a, 0x8e32956b, 0xb5e0794a, 0x343ea4a6, "....." },
  [3385] = { "L'Undermarket", "Uccidi Trade Master Kovic e il suo tirapiedi Clunk. Recupera la ⟦Trader's Satchel=Sacca del Commerciante⟧ dal suo cadavere e riportala a Nilith.", "Si fanno chiamare Undermarket: mercanti tagliagole pronti a vendere, trasportare, scambiare e fare quasi qualunque cosa per il giusto prezzo.\n\nE c'è di peggio, {name}. Hanno stabilito una base operativa qui nella ⟦Searing Gorge=Gorgia Rovente⟧. A capo dell'operazione c'è il mastro mercante Kovic, che ha stretti legami con i nani ⟦Dark Iron=Ferroscuro⟧ della regione.\n\nDobbiamo colpire duro e mandare un messaggio ai loro capi. Uccidi il mastro mercante Kovic e il suo tirapiedi Clunk. Riporta la sua sacca del commerciante quando avrai finito.\n\nAlla Caldera Magmatica!", "Il mastro mercante è ancora vivo?", "Hai inferto un colpo decisivo all'Undermarket. I loro capi ci penseranno due volte prima di mandare altri scagnozzi nella gola.\n\nAh, e nella sacca del commerciante non ho trovato niente di utile. Puoi tenerti tutto ciò che trovi dentro.", 0xcf667eb3, 0xf4eef121, 0xce7df4b5, 0x6d94a2b9, 0xd4a893c2, "....." },
  [3402] = { "L'Undermarket", "Parla con Vizzklick a ⟦Gadgetzan=Meccania⟧.", "Voglio che sia tu a portare di persona la notizia della sconfitta di Kovic a Vizzklick, a ⟦Gadgetzan=Meccania⟧. Sarà così felice di sapere che Kovic è morto che di certo ti darà una gran bella ricompensa.", nil, "Kovic è morto??! Che giorno glorioso, {name}! Per anni quel furfante ha gestito i loschi traffici dell'Undermarket, rovinando mercanti onesti e laboriosi in tutto il mondo.\n\nTi meriti una bella ricompensa per questa impresa! E una bella ricompensa avrai!", 0xcf667eb3, 0x12988fe1, 0xb3552e5b, nil, 0x8fb04460, "...m." },
  [3441] = { "Punizione divina", "Ascolta Velarok Windblade mentre racconta la sua storia.", "Ascolta la mia storia, avventuriero.", "Lasciami finire, mo... {race}.", "Hai sentito abbastanza? Sei pront<o/a> ad agire?", 0xa32f5c7d, 0x3d7177a4, 0xaefd1f11, 0x8a28a26a, 0xf4e4b7a3, "....." },
  [3442] = { "La fiamma perfetta", "Raccogli 4 Cuore di Fiamma e 4 globi di ⟦Golem Oil=Olio di Golem⟧ e porta tutto a Velarok Windblade.", "Hai preso la decisione giusta, {name}.\n\nDobbiamo colpire dove faremo più danni: le quattro torri di guardia.\n\nCon le quattro torri in fiamme, potremo lanciare un'offensiva prima che abbiano il tempo di reagire.\n\nTi servirà lo strumento adatto per incendiare le torri. Per fabbricarlo occorrono alcuni materiali.\n\nPortami quattro cuori di fiamma e quattro olii di golem e forgerò la torcia della fiamma perfetta.\n\nI golem e gli elementali di queste terre dovrebbero essere i tuoi primi bersagli.", "Hai raccolto i materiali?", "Ben fatto, {name}. Siamo quasi pronti.", 0x74ef41b1, 0x77191ec6, 0x0085154c, 0xb9773f73, 0x032b23bf, "....." },
  [3443] = { "Forgiare l'asta", "Porta 8 Pugnale Corazzato di Torio a Velarok Windblade.", "Per reggere la fiamma perfetta ci serviranno un'asta e un involucro. Prima devi trovare un'asta adatta.\n\nI coordinatori e gli schiavisti ⟦Dark Iron=Ferroscuro⟧ della Caldera Magmatica usano armi di torio incantato, una lega estremamente robusta. Se mi porti otto pugnali corazzati di torio, posso scomporre la lega e forgiare di nuovo un'asta.", "Otto, {name}. Me ne servono otto!", "Sei <un/una> lavorat<ore/rice> eccezionale, {name}. Hai mai pensato di cambiare mestiere? Magari l'investigatore? Il raccoglitore di rottami? Oh, ci sono: uno di quegli gnomi sciocchi che girano per le spiagge di Azeroth con i loro aggeggi cercametalli, a caccia di tesori perduti. Sì, sarebbe il posto ideale per te.", 0x95631eee, 0x8b5268ea, 0x723eec46, 0x4b5e1cf6, 0x854a703c, "....." },
  [3444] = { "Il ⟦Stone Circle=Cerchio Pietroso⟧", "Recupera il ⟦Stone Circle=Cerchio Pietroso⟧ dal laboratorio di Marvon Rivetseeker a ⟦Ratchet=Porto Paranco⟧.", "Un tempo entrai nelle sinistre sale del Tempio di Atal'Hakkar. Il male di quel luogo penetra chiunque vi entri; a fatica riuscii a trovare la via d'uscita, guadando la melma che ora ricopre i pavimenti. Ricordo soltanto di aver attraversato barcollando una grande sala circolare, piena di statue di serpenti...\n\nDi recente ho scoperto una pietra rotonda che sembrava avere impresso lo stesso simbolo del serpente. L'ho fatta imballare e spedire al mio laboratorio di ⟦Ratchet=Porto Paranco⟧. Recuperala, e forse potrò dirti di più.", "⟦Ratchet=Porto Paranco⟧ non è lontano da qui, {name}. Il viaggio non dovrebbe durare molto.", "Sì... Questa è la pietra.\n\nOra mi sta tornando tutto in mente, {name}...", 0xf6d90021, 0x0818ded7, 0x01a3b0a9, 0x56b42f76, 0x83595b35, "....." },
  [3445] = { "Il Tempio di Atal'Hakkar", "Trova Marvon Rivetseeker a Tanaris.", "Ho sentito parlare di un luogo che giace nelle profondità della terra, confinato laggiù da poteri più grandi di qualunque altro io abbia mai visto.\n\nSe vuoi saperne di più su questo luogo, il Tempio di Atal'Hakkar, cerca un goblin di nome Marvon Rivetseeker. Come me e Troyas, ha studiato molti luoghi antichi del mondo. L'ultima notizia che si ha di lui è che ha lasciato la sua casa a ⟦Ratchet=Porto Paranco⟧ per studiare le rovine troll di Tanaris.\n\nBuona fortuna nel trovarlo: è da un po' che non se ne sa nulla.", nil, "Sì, il Tempio di Atal'Hakkar: posso dire di averlo visto con i miei occhi. Forse ti piacerebbe saperne di più?\n\nHai l'aria di chi ama l'avventura... So cose che potrebbero incuriosirti...", 0x49245186, 0xd5fc3f18, 0x00e8289e, nil, 0x8af0f4e1, "...m." },
  [3446] = { "Nelle profondità", "Trova l'altare di Hakkar nel Tempio di Atal'Hakkar, nella ⟦Swamp of Sorrows=Palude del Dolore⟧.", "Dentro il tempio trovai una sala circolare con sei balconate, ognuna con una statua di serpente sul bordo. Per curiosità ne spinsi una per vedere cosa sarebbe successo, ed era una trappola! L'esplosione per poco non mi fece precipitare verso morte certa. Disteso sulla sporgenza, guardai giù e notai che c'era un'altra statua alla base della sala; una sorta di altare... Hakkar, credo si chiamasse.\n\nPenso che il segreto sia questo altare: devi portare questo pegno all'altare nel Tempio di Atal'Hakkar.", "Esaminando la statua, noti una cavità sul fianco, grande giusto quanto il pegno che ti ha dato Marvon...", "Spingi il cerchio pietroso nell'apertura e senti che si blocca al suo posto.\n\nOra che la pietra è al suo posto, puoi proseguire... ma cosa dovresti fare adesso?\n\nForse dovresti esaminare meglio questo altare...", 0xbc552e93, 0xd3d3a647, 0x5b0928d1, 0x3e0007dc, 0x923bbc72, "....." },
  [3447] = { "Il segreto del cerchio", "Entra nel Tempio di Atal'Hakkar e scopri il segreto nascosto nel cerchio di statue.", "I miei ricordi sono confusi, ma ti dirò ciò che posso. Il cerchio di statue nel Tempio di Atal'Hakkar, per quanto pericoloso, credo custodisca il segreto per accedere a un tesoro ancora più grande.\n\nDall'altare principale sono riuscito ad attivare una serie di luci. Credo che se scoprirai cosa significano quelle luci, potrai svelare qualunque segreto si nasconda in quella sala.\n\nTi avverto però, {name}. Nel tempio dimora un grande male. È probabile che qualunque cosa di valore sia sorvegliata con accanimento...", nil, "L'occhio dell'idolo brilla intensamente anche nella penombra del tempio. La sua trasparenza rivela qualcosa di luccicante dietro. Spostandolo di lato, infili la mano e afferri ciò che si trova dentro la statua.\n\nIl tesoro degli Atal'ai ora è tuo.", 0x6accd531, 0x0d09a55c, 0x42f0e580, nil, 0x0b0e6c7b, "...m." },
  [3448] = { "Passare il fardello", "Parla con Tymor a ⟦Ironforge=Forgiardente⟧.", "Di recente mi è stata affidata la responsabilità di indagare su Azshara, una regione un tempo splendida che gli elfi chiamavano casa. Parlo di quando praticavano la magia. Oggi è più pericolosa che bella, ma questo non ci impedisce di rivoltare ogni pietra in cerca di risposte sul nostro passato.\n\nUn mio compagno di nome Tymor si è offerto di aiutarmi a indagare sulla zona, dato che ha un interesse particolare per queste cose.\n\nHa un piccolo locale a destra della Hall of Mysteries, qui in città.", nil, "Ah, ti manda Karnik, eh? Mi aspettavo di avere sue notizie presto. Ho scoperto cose meravigliose su Azshara... So che gli Elfi della Notte vivono incredibilmente a lungo, ma a volte tutti dimenticano alcuni degli eventi più... sfortunati della propria vita. Non è una critica, solo un'osservazione.\n\nTanto tempo fa gli elfi crearono città piene di conoscenze sulla magia e su altre arti perdute. Essendo uno studioso di queste cose, ho avviato le mie ricerche. Ciò che ho trovato è stato davvero entusiasmante.", 0x3addab05, 0xf915132a, 0xc1d05228, nil, 0xbacc0aaf, "...m." },
  [3449] = { "Rune arcane", "Con il ⟦Drawing Kit=Corredo da Disegno⟧, ricava le copie della Runa di Beth'Amara, della Runa di Jin'yael, della Runa di Markri e della Runa di Sael'hai, poi raggiungi l'isoletta al largo della penisola meridionale di Azshara e fai segnale al pilota Xiggs Fuselighter perché venga a ritirarle.", "Per alcuni elfi, un tempo la magia era venerata quanto Elune stessa. Alcuni dei loro maghi più potenti crearono rune e tavolette che riportavano le leggi dell'arcano e le intuizioni delle loro scoperte. Le lasciavano in luoghi pubblici, perché tutti potessero meditarci sopra.\n\nVorrei tanto avere delle copie di queste rune dalle ⟦Ruins of Eldarath=Rovine di Eldarath⟧. Ho un corredo con cui potrai ricavarle, ma trovarle spetterà a te. Fa' attenzione, però: la Lega degli Esploratori non è l'unica a interessarsi a Eldarath.", "Bene, bene, bene, sono contento di vedere che sei arrivat<o/a> fin qui, {name}. Hai preso le copie per Tymor?\n\nPer quanto questo posto sia pericoloso, lungo la costa non c'è stato granché movimento. Forse è per via dei naga che nuotano sott'acqua, ma non è un problema mio... io pattuglio i cieli.", "Che bello vederti san<o/a> e salv<o/a>, {name}. Spero che non sia stata troppo dura per te.\n\nPorterò subito queste a Tymor. Sarà entusiasta di darci un'occhiata.\n\nPuoi pure buttare lo spararazzi... probabilmente non ti servirà più a niente, e io ne ho già uno nuovo.", 0x34f133ac, 0x434c007c, 0x1b184c56, 0x1803d3d6, 0xbd0b8d4a, "....." },
  [3450] = { "Un ritiro facile", "Parla con Xiggs Fuselighter a ⟦Ironforge=Forgiardente⟧.", "Voglio che le copie vengano consegnate alla mia torre, ma non c'è bisogno che tu vada fin lì. Le farò portare via da Azshara per via aerea.\n\nXiggs Fuselighter mi deve un favore o due e presto sarà in zona: si è arruolato per pattugliare la costa. Parlagli prima di partire. Può darti uno spararazzi per fargli segnale. Quando avrai le copie, va' dove ti dice e consegnagliele, così potrà portarle al sicuro alla mia torre. Dovrebbe essere nell'hangar del Military Ward.", nil, "Cosa posso fare per te, {name}? Sono un po' impegnato al momento, sto preparando il mio velivolo per un lungo viaggio. Sono passato solo per vedere alcuni piloti dei carri armati: mi servono delle criniere di wendigo per foderare la cabina di pilotaggio, e di solito ne hanno in più.\n\nPosso concederti un minuto se sei breve... uno dei ragazzi è appena partito per lo ⟦Steelgrill's Depot=Scalo di Grigliafredda⟧ a vedere se i piloti laggiù hanno qualche criniera in più per me.", 0xc51063db, 0x319e159e, 0x406ea5f6, nil, 0xc77d6b8a, "...m." },
  [3451] = { "Il segnale per il ritiro", "Parla con Xiggs Fuselighter a ⟦Ironforge=Forgiardente⟧ e fatti dare uno ⟦Standard Issue Flare Gun=Spararazzi Standard⟧.", "Ah, quindi ti manda Tymor, eh? Già, gli devo un favore o due. Cos'è questo? Ma guarda quel diavoletto. Sì, posso aiutarlo. Allora ti servono uno spararazzi e un posto... facile.\n\nAl largo della penisola meridionale di Azshara c'è un'isoletta dove abbiamo costruito una piattaforma d'atterraggio. Prendi questo spararazzi e usalo lì. Vedrò il tuo segnale e passerò a ritirare questo... quello che vuole lui, insomma.", nil, "Ecco il mio spararazzi standard. E dopo aver sparato abbi pazienza: ce ne sono solo un paio di cariche, e potrei metterci un minuto ad arrivare da te, a seconda di quanto sarò al largo. Dopo aver sparato il razzo, tieni d'occhio il mare.", 0x111e6b45, 0xcd6871bc, 0x0ad9695b, nil, 0xebcc5e87, "...m." },
  [3452] = { "L'involucro della fiamma", "Trova un ⟦Symbol of Ragnaros=Simbolo di Ragnaros⟧ e portalo a Velarok Windblade.", "Ci serve un ultimo pezzo per formare la torcia.\n\nSulle montagne a nord-ovest troverai un grande accampamento del ⟦Twilight's Hammer=Martello del Crepuscolo⟧. Si dice che portino con sé simboli e idoli in onore del loro dio. Quei simboli e idoli potrebbero contenere un incantamento sufficiente a formare un involucro magico. Portami un solo simbolo di Ragnaros e cercherò di estrarne la magia per creare l'involucro.", "Senza una fonte adatta di energia arcana, la Torcia del Castigo non può essere completata.", "Il simbolo irradia una magia immonda; perfetto per il nostro scopo.", 0xf6dbe91a, 0xa55f0a57, 0x82d0ba66, 0xf41fce2b, 0x5608c2de, "....." },
  [3453] = { "La ⟦Torch of Retribution=Torcia del Castigo⟧", "Aspetta che Velarok Windblade completi la ⟦Torch of Retribution=Torcia del Castigo⟧.", "Dammi un momento per unire i pezzi e applicare gli incantamenti necessari.", "Non interrompere il processo di incanalamento.", "C'è un ultimo compito che devi portare a termine.", 0x302cf31b, 0x71e960aa, 0x261e14d8, 0x0a1289be, 0x5248e48e, "....." },
  [3454] = { "La ⟦Torch of Retribution=Torcia del Castigo⟧", "Prendi la ⟦Torch of Retribution=Torcia del Castigo⟧.", "Ora la torcia deve essere vincolata al suo proprietario. Prendi la torcia, {name}.", nil, "Afferri la torcia con entrambe le mani; ondate di odio e di rabbia ti pulsano in tutto il corpo.", 0x302cf31b, 0xaeeb041a, 0xab51fc7a, nil, 0x7f85ed76, "...m." },
  [3461] = { "Ritorno da Tymor", "Restituisci a Tymor il suo ⟦Drawing Kit=Corredo da Disegno⟧, a ⟦Ironforge=Forgiardente⟧.", "Tymor non mi ha dato niente con cui pagarti, quindi ti consiglio di parlarne con lui quando tornerai a ⟦Ironforge=Forgiardente⟧. Di sicuro sarà ancora nel suo locale nel Mystic Ward. Va' a bussare e assicurati che ti paghi bene. Questo posto non è una passeggiata... poco ma sicuro.\n\nGrazie ancora per averlo aiutato, comunque, e buona fortuna.\n\nAh, e il corredo da disegno non mi serve. Perché non lo riporti tu a Tymor quando vai a trovarlo?", "Sei tornat<o/a>! Ottimo. Hai anche il mio corredo da disegno?", "Magnifico! Sono proprio contento di sentirlo.\n\nNon vedo l'ora di arrivare alla mia torre ed esaminare quelle copie. Ti invidio tanto... andare in un posto come Azshara. È il sogno di qualunque studioso dell'arcano, immagino.\n\nBe', non abbiamo mai parlato di una ricompensa, visto che lavoravi solo per la Lega degli Esploratori, ma qualcosa te la meriti.", 0x260f8ba5, 0x90d05445, 0x3997cdc0, 0x03a24046, 0x34b90840, "....." },
  [3462] = { "Lo scudiero Maltrake", "Parla con lo scudiero Maltrake.", "Parla con il mio emissario, lo scudiero Maltrake. Ti darà altre istruzioni sull'uso della ⟦Torch of Retribution=Torcia del Castigo⟧.", nil, "Sei pront<o/a> a colpire?", 0x0069fcce, 0x987eebfd, 0xbabc11c0, nil, 0x1e917c10, "...m." },
  [3463] = { "Incendiale!", "Incendia la North Sentry Tower, la South Sentry Tower, la East Sentry Tower e la West Sentry Tower usando la ⟦Torch of Retribution=Torcia del Castigo⟧ all'interno di ciascun edificio.", "Ascoltami bene, {name}. Anche se le quattro torri non potranno mai essere distrutte, puoi usare la ⟦Torch of Retribution=Torcia del Castigo⟧ per incendiarle per moltissimo tempo: un fuoco che nessun elemento né forza può domare.\n\nFinché bruciano, nessuna guardia o sentinella potrà occupare i posti di guardia, e così la loro prima linea di difesa sarà annullata.\n\nDevi entrare in ciascuna torre e usare la ⟦Torch of Retribution=Torcia del Castigo⟧ dentro le loro fortificazioni. Guardati dalle sentinelle scelte dei Ferroscuro, {name}.", "Ti sei pers<o/a>, {name}?", "È magnifico! Non è magnifico, padrone?", 0x41623cfd, 0x9b337002, 0xe9f6762f, 0xf721a64c, 0x5652553c, "....." },
  [3481] = { "Ninnoli...", "Apri il forziere.", "Il forziere sembra chiuso a chiave.", nil, "Il forziere si apre al tuo tocco. Quanto formaggio potrà mai esserci qui dentro? C'è un solo modo per scoprirlo.", 0xba04bbaa, 0x6a8234a8, 0xa520e789, nil, 0x5f10c2f0, "...m." },
  [3501] = { "Tutto conta in grandi quantità", "Porta a Kum'isha i Frammenti di Draenetista Imperfetti e ricevi una ricompensa per ognuno che consegni.", "Anche se forse non troverai mai una sfera perfetta di draenetista, esplorando queste terre scoprirai senza dubbio vari frammenti imperfetti di draenetista.\n\nÈ improbabile che Kum'isha riesca a usare i frammenti difettosi per tornare a casa, ma potrebbero servire ai draenei per altri scopi utili.\n\nRiportami qualsiasi frammento di draenetista imperfetto che trovi e ti ricompenserò.", "Hai avuto fortuna nelle tue esplorazioni?", "Mi disgusti davvero, {race}. <Un/Una> <uomo/donna> adult<o/a> che sbava su un mucchio di cianfrusaglie? Patetico! Prendi la tua ricompensa e sparisci dalla mia vista.", 0x710e9f91, 0xf35fbef0, 0xd8e321c4, 0x480f2e19, 0xe2c4a2a8, ".....", nil, nil, nil, nil, 0x93155b22 },
  [3504] = { "Tradimento", "Consegna la ⟦Sealed Letter to Ag'tor=Lettera Sigillata per Ag'tor⟧ ad Ag'tor Bloodfist, ad Azshara.", "Elfa traditrice e ladra! Così la chiamo, ed è tutto ciò che sarà mai!\n\nPotrei aver commesso un grave errore, {name}. Mi sono fidato di un'Elfa del Sangue.\n\nDiceva che Azshara custodiva grandi ricchezze... oggetti potenti. Bastava che le mandassi qualche guerriero a proteggerla e sarei stato ricompensato. Be', guarda chi è lo sciocco: li ha uccisi tutti.\n\nVoglio vendetta, {name}, ma non posso permettermi di mandare nessun altro. Trova Ag'tor a Valormok, a nord dell'⟦Haldarr Encampment=Accampamento di Haldarr⟧. Ti dirà di più.", "Ah, alla fine Belgrom ha messo giudizio e ha mandato ad aiutarci qualcuno che non è dei suoi, eh?\n\nQuesto accampamento contava una dozzina di guerrieri, {name}, ma ora sono tutti morti. Quella maga, Rimtori, li ha uccisi tutti. Ha suonato Belgrom come un liuto... l'ha perfino sedotto. Non sono affari miei, ma detto tra noi, è una vera tentatrice. Probabilmente è per questo che sono ancora qui ad aiutare Belgrom: con ogni probabilità avrei fatto lo stesso.", "Abbiamo mandato tutto ciò che avevamo contro di lei e i suoi lavoratori, ma in battaglia sono forti. Nessuno si è preso la briga di tornare. Immagino che alcuni siano morti, ma sono sicuro che altri sono semplicemente scappati... codardi.\n\nMa ora che sono arrivati i rinforzi, forse possiamo ancora fare qualcosa. Forse possiamo ancora punirla per aver mentito a Belgrom e averlo tradito.\n\nChe ne dici, ci stai?", 0xebf1036b, 0xfb1801e8, 0x24633632, 0x2f76370e, 0x03d70660, "....." },
  [3505] = { "Tradimento", "Uccidi 10 Blood Elf Reclaimer e 10 Blood Elf Surveyor prima di cercare l'accampamento della magus Rimtori. Una volta trovato, cerca qualcosa di importante per lei che possa servire ad attirarla in combattimento.", "Lo immaginavo.\n\nCominciamo la nostra crociata contro i suoi lavoratori lungo le scogliere meridionali della penisola settentrionale di Azshara. Uccidili con rabbia sanguinaria: che sappiano di aver tradito gli alleati sbagliati.\n\nPer ora non preoccuparti di lei: passa gran parte del tempo a perlustrare Azshara con le sue guardie del corpo. Dopo aver ucciso i suoi lavoratori, sarebbe prudente trovare il suo accampamento personale. Scoprire dove possiamo attaccarla sarebbe saggio. Forse lì c'è qualcosa che possiamo usare per provocarla.", "Il titolo del libro è impresso in foglia d'oro sulla copertina di cuoio nero: Kaldorei Tome of Summoning. Sfogliandolo, vedi che il libro è molto antico ma in condizioni eccellenti.\n\nSupponi che il testo sia in una lingua antica... forse kaldorei?\n\nL'istinto ti dice che dovresti tornare qui dopo aver inflitto agli Elfi del Sangue la punizione per il loro tradimento.", "Cominci a sfogliare alcune pagine finché non arrivi a una segnata da una sottile striscia di seta nera.\n\nMentre cerchi di decifrare la scrittura, noti un diagramma in fondo a una delle pagine. Un rapido sguardo alla scena davanti a te e ti rendi conto che i cristalli, il cerchio e perfino alcuni degli altri componenti sul terreno sono disposti secondo uno schema simile a quello del diagramma.", 0xebf1036b, 0xda5e2dce, 0xb1d5f78a, 0xe0f0f6a7, 0xe176809c, "....." },
  [3506] = { "Tradimento", "Distruggi il cristallo di focalizzazione arcana legato a Magus Rimtori, poi uccidila. In seguito porta la ⟦Head of Magus Rimtori=Testa della Magus Rimtori⟧ ad Ag'tor Bloodfist, ad Azshara.", "Riflettendo ancora qualche istante ti vengono in mente alcune idee, e una di queste ti strappa un sorriso: forse distruggere i cristalli sconvolgerebbe l'elfa del sangue responsabile del massacro di tanti orchi e del tradimento di Belgrom?\n\nContinui a decifrare la scrittura e le figure e ti rendi conto che uno dei cristalli è legato a chi ha creato il cerchio, mentre gli altri sono legati a qualcosa di ben più sinistro.\n\nChiudi il libro e cominci a decidere quale cristallo distruggere.", "Come procede il massacro dei traditori elfi del sangue, {name}? Hai fatto progressi?\n\nSpero che tu abbia la forza di mettere in ginocchio quella cagna! Merita solo una morte dolorosa per tutto quello che ha fatto!", "RAR!! Incredibile!\n\nCe l'hai fatta! Belgrom ne sarà contento! Finalmente gli spiriti di decine dei nostri guerrieri potranno trovare pace. Grazie, {name}.", 0xebf1036b, 0x7c93eea7, 0xae3913b5, 0x95829dd6, 0xa4ec0c3f, "....." },
  [3507] = { "Tradimento", "Parla con Belgrom Rockmaul a Orgrimmar.", "Torna da Belgrom a Orgrimmar. Vorrà vedere la sua testa con i propri occhi! Noi ci torneremo a breve.\n\nAh, questo è davvero un bel giorno. Grazie per il tuo aiuto, {name}.", "Mi ricordo di te, {class}. Ti avevo chiesto di andare ad Azshara a distruggere quella sgualdrina che mi ha tradito! Sembrano passate molte lune. Non dirmi che anche Ag'tor e gli altri sono morti!", "AHAH! Guardati ora, donna patetica! Sputo sui tuoi resti!\n\nGrazie, {name}. Grazie dal profondo del cuore! Questo è davvero un gran giorno!\n\nTi darei un regno, se fosse in mio potere! Ma forse ti accontenterai di questo.\n\n<Belgrom abbassa lo sguardo sulla testa della maga che lo aveva tradito.>\n\nAhah! Stupida elfa del sangue, guardati ora... in un sacco di iuta e senza più il tuo corpo! Non avresti mai dovuto tradire Belgrom!", 0xebf1036b, 0x93cd53eb, 0x76dc5375, 0x2e6dd780, 0x339d3b7b, "....." },
  [3508] = { "Spezzare la protezione", "Attendi che Loramus completi l'incantesimo di illuminazione.", "Sei temerari<o/a>, {name}. È una qualità ammirevole della tua specie: gettarsi alla cieca in battaglia con poche o nessuna possibilità di successo. Ti aiuterò, se non altro per veder cadere anche uno solo dei servitori di Razelikh.\n\nSpezzare la protezione posta sui sottoposti di Razelikh richiederà tempo e il recupero di manufatti rari.\n\nNon muoverti, prima devo eseguire il rituale di illuminazione. Le informazioni che raccoglierò mi aiuteranno a forgiare armi di grande potere.", nil, "Bisogna trovare il nome della bestia.", 0xd775797a, 0x0104195d, 0xd405f8b2, nil, 0xf09e3aa3, "...m." },
  [3509] = { "Il nome della bestia", "Parla con lord Arkkoroc ad Azshara. Inizia la ricerca in riva al mare per trovare il Temple of Arkkoran.", "C'è un solo modo per ferire il signore dei demoni e i suoi servitori. Bisogna forgiare un'arma di potere che porti il suo vero nome.\n\nQuando un'arma simile sarà forgiata, il demone e tutti quelli al suo comando saranno vulnerabili.\n\nAd Azshara risiede una divinità minore: lord Arkkoroc. Devi cercarlo, ma sta' in guardia: se ti scoprono, i suoi servitori non si fermeranno davanti a nulla pur di distruggerti.\n\nSenza dubbio dovrai pagare un prezzo per un'informazione simile.", nil, "Un signore dei demoni?\n\n<Lord Arkkoroc ride.>\n\nForse colui che ti sta davanti potrà aiutarti con questa informazione; ma prima dovrai aiutarlo tu.", 0xa611ce38, 0x6018f1ae, 0xa96f0987, nil, 0x6af53384, "...m." },
  [3510] = { "Il nome della bestia", "Uccidi Hetaera e porta la ⟦Hetaera's Bloodied Head=Testa Insanguinata di Hetaera⟧, la ⟦Hetaera's Beaten Head=Testa Colpita di Hetaera⟧ e la ⟦Hetaera's Bruised Head=Testa Bruciata di Hetaera⟧ a lord Arkkoroc.", "Uccide i miei figli, mortale. Lei, che si proclama sovrana di questi oceani. Una falsa dea, niente di più. Schiacciala e riportami tutte le sue teste.\n\nIn cambio riceverai il nome che cerchi e qualcos'altro di pari importanza.\n\nSi aggira per il suo nido... Si chiama Hetaera.\n\n<Lord Arkkoroc indica verso sud-ovest.>\n\nVa'!", "<Lord Arkkoroc si china per esaminarti.>\n\nDove sono?", "Finalmente qualcuno degno della saggezza di Arkkoroc!", 0xa611ce38, 0xd218c689, 0x6555b2ac, 0xde44a003, 0x04ec8c62, "....." },
  [3511] = { "Il nome della bestia", "Porta la tempra a Loramus Thalipedes.", "Come promesso, ti rivelerò il nome del signore dei demoni, Razelikh il Profanatore. Prima, però, devo preparare qualcosa della massima importanza per il tuo viaggio.\n\nL'arma che vuoi creare richiede una tempra. Dammi un momento per drenare il sangue da queste teste.\n\n<Lord Arkkoroc stringe le teste tra i suoi pugni giganteschi, spremendone tutto il sangue.>\n\nPorta la tempra a Loramus insieme al nome della bestia: Rakh'likh.", "Sei tornat<o/a>! Sorprendente, {race}. Hai scoperto il vero nome?", "La tempra aggiungerà il vetriolo che ci serve per forgiare le armi. Manca un solo passaggio per crearle.", 0xa611ce38, 0x68861385, 0x4e66ca0d, 0x6c8a8f84, 0x38e867c7, "....." },
  [3512] = { "Con le parole di Eranikus", "Va' nella parte orientale di ⟦Winterspring=Fontefredda⟧ e parla con Umbranse the Spiritspeaker.", "{name}, il nostro primo passo sarà trovare un modo per parlare con Eranikus attraverso la gemma. Ora giace in uno stato precario tra il sonno e la morte, avvolto in una trama di incubi. Anche se l'essenza che mi hai dato è gravemente corrotta, c'è una possibilità di raggiungerlo.\n\nViaggia fino alle terre ghiacciate della parte orientale di ⟦Winterspring=Fontefredda⟧ e cerca uno dei nostri alleati mortali, Umbranse the Spiritspeaker. È un medium umano che parla per i morti. Anche se Eranikus non è davvero morto, potrebbe comunque esserci d'aiuto.", nil, "Itharius ha fatto bene a mandarti da me. Anche se non è morto come tu intendi la morte, Eranikus presto ci darà consiglio con le sue stesse parole. Per ora, però, non posso aiutarti direttamente... almeno non ancora.\n\nTi presterò la mia arte di parlare con i morti, ma prima ho bisogno dell'aiuto di qualcuno che, a differenza di me, non sia limitato dagli acciacchi della vecchiaia. Il mio più potente strumento divinatorio mi è stato portato via contro la mia volontà, e se non lo riavrò non potremo aiutare Eranikus.", 0xd0c7f188, 0xea321243, 0x511aba56, nil, 0x3fc8d4f6, "...m." },
  [3513] = { "La ⟦Runed Scroll=Pergamena Runica⟧", "Porta la ⟦Runed Scroll=Pergamena Runica⟧ alla torre di guardia settentrionale nelle ⟦Barrens=Savane⟧.", "La pergamena, dall'aspetto ufficiale, è avvolta stretta da un nastro argentato. Sei <certo/certa> che a qualcuno interesserebbe vederla, ma a chi?\n\nC'è un avamposto vicino al confine con ⟦Ashenvale=Valtetra⟧, a nord: se le informazioni di questa pergamena riguardano gli Elfi della Notte, è lì che conviene portarla.", "Che c'hai?", "Bene, bene... Dove l'hai trovata?", 0x4918e4bc, 0xa4caed64, 0x97a4a11f, 0x0364734f, 0xa9e181b5, "....." },
  [3514] = { "Presenza dell'⟦Horde=Orda⟧", "Uccidi il capo dell'Eremo Grinfialunga, Rynthariel the Keymaster.", "Questa pergamena viene da quella driade intrigante, Rynthariel, custode delle chiavi dell'Eremo Grinfialunga sul ⟦Stonetalon Peak=Picco di Petrartiglio⟧.\n\nNon avrà più contatti con il messaggero a cui l'hai presa, eh, ma dobbiamo tenere la posizione qui. L'⟦Horde=Orda⟧ non tollererà le sue staffette da queste parti.\n\n{name}, va' all'Eremo Grinfialunga. Uccidi Rynthariel, e poi innalza un simbolo che tutti possano vedere. Prendi questa bandiera dell'⟦Horde=Orda⟧, {name}. Piantala nell'Eremo Grinfialunga, così non saranno tanto avventati da mandare un altro messaggero attraverso il nostro territorio.", "Non possiamo permettere all'⟦Alliance=Alleanza⟧ di stare sulla nostra terra, {name}. Fallo sapere a tutti.", "Sei <un/una> dur<o/a>! Liberare l'Eremo da Rynthariel è un grande passo, {name}. Ci metteranno molto a riorganizzarsi, e quindi possiamo contare su meno corrieri dell'⟦Alliance=Alleanza⟧ nelle ⟦Barrens=Savane⟧. Ci penseranno due volte prima di mandarne un altro da questa parte.\n\nGrazie.", 0x247781f9, 0xe57bf0f8, 0x07dbeb87, 0xc47b2c26, 0x9451d022, "....." },
  [3517] = { "Sapere rubato", "Trova la ⟦Tablet of Beth'Amara=Tavoletta di Beth'Amara⟧, la ⟦Tablet of Jin'yael=Tavoletta di Jin'yael⟧, la ⟦Tablet of Markri=Tavoletta di Markri⟧ e la ⟦Tablet of Sael'hai=Tavoletta di Sael'hai⟧, poi torna da Jediga ad Azshara.", "Lo ammetto, {name}, ho sfruttato al massimo la mia situazione ad Azshara. La punizione di Belgrom ha avuto i suoi vantaggi.\n\nPrima di partire ho fatto qualche ricerca, e ti stupiresti di quanti oggetti di valore ci siano in giro.\n\nTi racconterò di più sui miei affari, e ti darò persino una parte dei profitti, se mi aiuti a raccoglierne alcuni.\n\nNelle ⟦Ruins of Eldarath=Rovine di Eldarath⟧, a est, ci sono delle tavolette che mi servono. Tutte e quattro portano il nome di maghi degli ⟦Highborne=Alti Nobili⟧. Procuramele e ne riparleremo.", "Le tavolette che ti faccio raccogliere dovrebbero fruttare qualche bella moneta di rame dalle persone giuste. Ti dirò a chi consegnarle dopo che le avrai trovate. Ma non sono una sciocca... avrai la tua parte quando avrò la prova che sono state consegnate.\n\nQuindi datti da fare: non abbiamo tutto il giorno. Potrei dover trovare qualcun altro che mi aiuti.", "Perfetto, {name}, e anche in buone condizioni. Dovrebbero fruttarci un buon prezzo da tutte le parti interessate.\n\nNon perdiamo qui più tempo del necessario. Abbiamo dei soldi da fare.", 0x47276997, 0x7a5f9504, 0x828570cd, 0x1a819558, 0x7018a42b, "....." },
  [3518] = { "Consegna a Magatha", "Porta la ⟦Tablet of Beth'Amara=Tavoletta di Beth'Amara⟧ a Magatha a ⟦Thunder Bluff=Picco del Tuono⟧.", "La prima tavoletta va a una femmina tauren... una certa Magatha. È tra gli anziani di ⟦Thunder Bluff=Picco del Tuono⟧ ed è una delle sostenitrici dell'alleanza tra i tauren e i Reietti. Più di chiunque altro tra gli anziani, crede che i tauren e le loro usanze possano aiutare i Reietti a ritrovare la via per tornare umani.\n\nPortale la ⟦Tablet of Beth'Amara=Tavoletta di Beth'Amara⟧. La tavoletta potrebbe essere l'anello che le manca per trovare un modo di aiutare i Reietti... o almeno così dice lei.", "Sì, {name}. Cosa posso fare per te? Ho molte faccende di cui occuparmi, quindi ti prego, sii breve.", "Ah, finalmente, la ⟦Tablet of Beth'Amara=Tavoletta di Beth'Amara⟧. Mi chiedevo se la mia collaborazione con Jediga fosse fallita o se la povera orchessa avesse trovato la morte ad Azshara. Sono lieta che ci sia riuscita.\n\nBeth'Amara era uno degli alchimisti più influenti degli Alti Nobili. Si diceva che il mago da solo avesse padroneggiato la trasmutazione dei metalli, tra le altre cose.", 0xd4c2c45f, 0x2ea1ce4f, 0x2c5f5d08, 0x901d8ed6, 0xb3df3437, "....." },
  [3519] = { "Un amico in difficoltà", "Parla con Dirania Silvershine a ⟦Shadowglen=Vallombra⟧.", "Ughhh... mentre esploravo la caverna dei ragni qui vicino mi ha morso, e molto male, un ragno di nome Githyiss il Vile. Sono sicuro di essere stato avvelenato gravemente; devi aiutarmi.\n\nTi prego, avverti Dirania Silvershine. Lei potrà aiutarmi.\n\nPresto... mi gira tanto la testa...", nil, "Oh, cielo; mi chiedevo perché oggi non avessi ancora visto Iverron. E l'ho sempre avvertito di quei ragni...", 0x14600625, 0xd73f79e1, 0x6dca0a7e, nil, 0xcf23564b, "...m." },
  [3520] = { "Gli spiriti stridenti", "Cattura gli spiriti di 3 screecher a Feralas, poi torna da Yeh'kinya, al ⟦Steamwheedle Port=Porto degli Spargifumo⟧.", "Cerco gli spiriti degli stridenti delle valli di Feralas. Sono cugini di un dio antico, antichissimo, e i loro spiriti sono legati a lui.\n\nPrendi questa bacchetta di rovo e va' a Feralas. Trova e sconfiggi gli stridenti delle valli nel sud e nel centro di Feralas, poi agita il mio rovo sopra i loro corpi caduti. Questo indurrà il loro spirito a rivelarsi. Tocca lo spirito e raccogline l'essenza.\n\nTorna da me con il mio rovo e con l'essenza raccolta, e ti dirò di più sul dio antico di cui ho parlato.", "Hai raccolto l'essenza degli spiriti stridenti, {name}?", "Hai fatto bene, {name}. Forse ora è il momento di rivelarti di più...\n\nTra i troll c'è un'antica profezia, secondo cui il dio morto Hakkar lo Scortica Anime un giorno tornerà su questa terra. Alcuni dicono che la venuta di Hakkar porterà gioia e gloria alla stirpe dei troll, mentre altri credono che la sua resurrezione segnerà la fine di tutte le cose.\n\nIo non credo a questo mito, ma so che l'essenza di Hakkar racchiude un grande potere, e questo potere andrebbe tenuto lontano da chi ne abuserebbe...", 0x2d7c7613, 0xa123a982, 0x2d39ef63, 0x6a3c5251, 0xe1d531df, "....." },
  [3521] = { "⟦Iverron's Antidote=Antidoto di Iverron⟧", "Raccogli 7 Fungo Giacinto, 4 Moonpetal Lily e 1 ⟦Webwood Ichor=Icore di Telalegno⟧ per Dirania Silveshine a ⟦Shadowglen=Vallombra⟧.", "Forse possiamo aiutare Iverron: conosco un antidoto che dovrebbe funzionare contro il veleno. Prima di prepararlo, però, mi servono alcuni ingredienti.\n\nMi servono dei funghi giacinto. Li trovi sotto gli alberi, oppure puoi prenderli ai grell a sud di qui: sembra che ne vadano ghiotti. Mi servono anche dei gigli di lunafoglia, che crescono solo vicino agli specchi d'acqua.\n\nL'ultimo ingrediente potrebbe essere il più difficile da trovare. Raccogli l'icore di Telalegno proprio dai ragni che hanno avvelenato Iverron.", "Ti prego, raccogli gli ingredienti, {name}. Iverron ha bisogno del nostro aiuto.", "Sia ringraziata Elune, hai raccolto questi ingredienti così in fretta!\n\nTra un attimo avrò pronto l'antidoto.", 0xf8fbaf1b, 0x12503cdc, 0x32bb4179, 0xd4e56d7d, 0xbaa1ea59, "....." },
  [3522] = { "⟦Iverron's Antidote=Antidoto di Iverron⟧", "Porta l'⟦Iverron's Antidote=Antidoto di Iverron⟧ a Iverron prima che scada il tempo. Iverron si trova presso la caverna a nord.", "L'antidoto è pronto, {name}. Ti prego, fa' in modo che Iverron lo beva.\n\nC'è una cosa che devi sapere: l'antidoto resterà efficace solo per 5 minuti. Devi portarglielo in tempo.\n\nChe la rapidità sia con te, {name}.", "Oh... {name}, sono così felice che tu sia tornat<o/a>.", "Che cos'è questo, {name}?\n\nOh, lo sapevo che Dirania sarebbe riuscita ad aiutarmi!\n\n<Iverron beve l'antidoto.>\n\nMi caccio sempre nei guai e Dirania, be', riesce sempre a tirarmene fuori.\n\nMi sento molto meglio, ma credo che resterò seduto qui ancora un po', finché non mi sentirò del tutto bene. Be', per questo, e perché speravo che mi aprissi un passaggio tra quei feroci ragni Telalegno...", 0xf8fbaf1b, 0x19c81d7f, 0x9296895f, 0x4cd0a6af, 0xc1dde192, "....." },
  [3523] = { "Il Flagello dei Sotterranei", "Se accetti di aiutare Belnistrasz, parlagli di nuovo e restituiscigli la Pietra del Giuramento che ti ha dato.", "Magnifico! Mi chiamo Belnistrasz, e ti ringrazio per avermi salvato. Mi ero già dato per morto... o peggio, per pasto di questi parassiti infestati dal Flagello. Sì, ho detto proprio Flagello: hanno stretto una specie di patto con i verrospini di qui, e questo incubo ne è il risultato.\n\nAscolta... invece di fuggire e basta, voglio fare qualcosa di buono, per il bene di tutti noi. Te la senti di aiutarmi a questo scopo? Probabilmente è pericoloso, ma mi sembri il tipo che non se ne preoccupa troppo.", "Non m'interessa la politica; poco mi importa se stai con l'⟦Horde=Orda⟧ o con l'⟦Alliance=Alleanza⟧. Mi interessa di più soffocare le minacce dirette e gravi per tutte le razze... e qui dentro ne abbiamo una bella grossa.\n\nSe vuoi essere un vero eroe per tutti i popoli, consegnami la pietra del giuramento che ti ho dato come segno del tuo impegno. Io... non sono di queste parti; per la gente della mia stirpe una pietra del giuramento è importante, è il sigillo di un patto.", "Fantastico, mi sembravi proprio il tipo eroico! Ci aspetta un bel lavoro, {name}, non ti mentirò. Se restiamo concentrati sul compito, dovremmo riuscire a spuntarla.\n\nOra lascia che ti metta al corrente di quello che sta succedendo...", 0xae7d8ef9, 0x85690b77, 0x9c1e1ebf, 0x00a114d7, 0xd298f8e8, "....." },
  [3524] = { "Trascinata a riva", "Recupera le ⟦Sea Creature Bones=Ossa di Creature Marine⟧ dalla creatura marina arenata appena a sud di Auberdine, poi portale a Gwennyth Bly'Leggonde ad Auberdine.", "Si sa che le maestose creature marine si gettano sulla costa di ⟦Darkshore=Rivafosca⟧, dove restano arenate finché non muoiono. Ultimamente queste bestie si arenano in numero sempre maggiore. Il ⟦Temple of the Moon=Tempio della Luna⟧ mi ha mandato qui a indagare, ma la presenza dei murloc lungo l'acqua ha reso difficili le mie ricerche.\n\nAppena a sud di Auberdine c'è una creatura gigantesca arenata, circondata dagli immondi murloc Greymist. Potresti andare lì e recuperare delle ossa della creatura per il nostro studio?", "Solo di recente queste creature hanno cominciato ad arenarsi sulla costa di ⟦Darkshore=Rivafosca⟧ in numero così allarmante. Non posso fare a meno di pensare che sia un cattivo presagio. Recuperare un campione delle ossa di quella creatura a sud aiuterebbe noi di Darnassus a valutare la situazione!", "Spero che i murloc non ti abbiano dato troppi problemi mentre le raccoglievi per noi! Mi assicurerò di mandarle a Darnassus con il prossimo ippogrifo. Il ⟦Temple of the Moon=Tempio della Luna⟧ mi ha dato dei fondi da distribuire a chi ci aiuta: accettane una parte, con i nostri ringraziamenti.\n\nIl tuo successo qui mi incoraggia a offrirti l'occasione di aiutare ancora il ⟦Temple of the Moon=Tempio della Luna⟧, se ti interessa...", 0x8079e34a, 0xdf94400b, 0xdd2f6ea9, 0xb30873ce, 0x899e5ad6, "....." },
  [3525] = { "Spegnere l'idolo", "Scorta Belnistrasz fino all'idolo dei verrospini nei ⟦Razorfen Downs=Sotterranei di Lamaspina⟧.\n\nProteggi Belnistrasz mentre esegue il rituale per spegnere l'idolo.", "Vicino all'ingresso c'è un idolo che fa da macabro forno per i verrospini; quelle bestie... divorano letteralmente le persone che rapiscono nelle ⟦Barrens=Savane⟧. Posso spegnere l'idolo e impedire che lo usino di nuovo, ma mi serve il tuo aiuto. Il mio piano: scortami fino all'idolo. Una volta arrivati, darò inizio al rituale. Riuscirò a stento a comunicare con te, figuriamoci a difendermi. Proteggimi mentre spengo l'idolo. Se mi abbattono, per noi è finita.\n\nSei con me?!", nil, "L'improvvisa partenza di Belnistrasz ha lasciato dietro di sé un braciere acceso. Mentre fissi la fiamma, l'immagine di un grande drago rosso dalle ampie ali ti riempie la mente. Una versione più roca della voce di Belnistrasz ti parla direttamente.\n\n\"Davvero, mortali, siete gli eroi che speravo. Grazie a voi, il massacro che queste bestie compivano appartiene al passato. La mia fiducia nei mortali come voi si è rinnovata ancora una volta. Prendi questo, una ricompensa degna di un eroe.\"", 0x17d394ac, 0xb46725ca, 0x55b0d5af, nil, 0x0f1269c0, "...m." },
  [3526] = { "⟦Goblin Engineering=Ingegneria dei Goblin⟧", "Se vuoi saperne di più sull'⟦Goblin Engineering=Ingegneria dei Goblin⟧, porta il ⟦Manual of Engineering Disciplines=Manuale delle Discipline Ingegneristiche⟧ a Nixx Sprocketspring, a ⟦Gadgetzan=Meccania⟧.", "L'ingegneria di livello esperto si divide in due discipline distinte: quella degli gnomi e quella dei goblin. È chiaro che l'Ingegneria dei Goblin è la scelta di tutti gli ingegneri brillanti. Impara a dominare il mondo con un uso giudizioso di esplosivi potenti e di congegni fantastici!\n\n{name}, leggi questo manuale. Se vuoi conoscere l'Ingegneria dei Goblin, portalo a Nixx Sprocketspring, a ⟦Gadgetzan=Meccania⟧. Ricorda: l'iscrizione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati che sia ciò che vuoi prima di completare il suo compito.", "Le reclute fresche le fiuto come fiuto un'ottima polvere esplosiva: a un miglio di distanza. Sei venut<o/a> per imparare a padroneggiare l'esplosione?", "Be', {name}, hai fatto bene a cercare la mia guida! Qualsiasi sprovveduto può diventare esperto nelle basi dell'ingegneria: gli gnomi e la loro casa radioattiva, Gnomeregan, ne sono la prova. Ma per padroneggiare la disciplina dell'⟦Goblin Engineering=Ingegneria dei Goblin⟧ ci vogliono una mente forte e una mano ferma (e sottolineo FERMA).\n\nTieni le orecchie dritte, {name}, e forse imparerai qualcosa.", 0x4ccb3e9c, 0x84f932f9, 0x31040b00, 0x21f4153d, 0xad63c1bf, "....." },
  [3527] = { "La profezia di Mosh'aru", "Porta la Prima Tavoletta Mosh'aru e la Seconda Tavoletta Mosh'aru a Yeh'kinya, a Tanaris.", "L'antica profezia di Mosh'aru parla di un modo per imprigionare l'essenza del dio Hakkar. Fu scritta su due tavolette che vennero portate nella città troll di ⟦Zul'Farrak=Zul'farrak⟧, a ovest di ⟦Gadgetzan=Meccania⟧.\n\nPortami le tavolette di Mosh'aru!\n\nLa prima tavoletta è custodita da Theka il Martire, un troll morto da tempo. Si dice che i suoi persecutori siano stati tramutati in scarabei e che ora zampettino attorno al suo santuario.\n\nLa seconda tavoletta è custodita dall'idromante Velratha, vicino alla pozza sacra di Gahz'rilla.\n\nQuando avrai le tavolette, portamele.", "Hai le tavolette della profezia di Mosh'aru, {name}?\n\nQuando avrò le tavolette, le studierò e imparerò come imprigionare l'essenza di Hakkar!", "Ah, ottimo. Posso fondere insieme queste antiche tavolette e poi studiarne i segreti nascosti.\n\nIl mio debito con te cresce, {name}. E crescerà ancora.", 0xd364c406, 0x5779c127, 0x04cf4634, 0x501c1184, 0xc5a84974, "....." },
  [3528] = { "Il dio Hakkar", "Porta l'⟦Filled Egg of Hakkar=Uovo di Hakkar Pieno⟧ a Yeh'kinya, a Tanaris.", "Ora è il momento di catturare l'essenza dell'avatar di Hakkar.\n\nPorta l'⟦Egg of Hakkar=Uovo di Hakkar⟧ al Sanctum of the Fallen God, nel Tempio di Atal'Hakkar, ad Azeroth. Invoca il potere dell'uovo per risvegliare il dio morto.\n\nLui manderà contro di te i suoi servitori. Sconfiggi i suoi bevitori di sangue e prendi il loro sangue degli Hakkari, poi usa il sangue per spegnere le fiamme eterne che trattengono lo spirito di Hakkar. Quando tutte le fiamme si saranno spente, l'avatar di Hakkar entrerà nel nostro mondo.\n\nSconfiggilo e metti la sua essenza nell'⟦Egg of Hakkar=Uovo di Hakkar⟧.", "Hai sconfitto l'avatar di Hakkar, {name}? La sua essenza ha già riempito di potere l'uovo che ti ho dato?", "L'essenza di Hakkar è stata raccolta! Già ora l'uovo freme di vita! Possibile che i miti su Hakkar siano veri?\n\nNon devono esserlo, perché allora temo ciò che Hakkar potrebbe fare se rinascesse. Terrò quest'uovo al sicuro e farò in modo che non cada in mani malvagie.\n\nIl tuo lavoro con me è finito, {name}. Hai sfiorato una leggenda, e le tue azioni un giorno potrebbero cambiare il volto del nostro mondo.", 0x238c5bf2, 0x9b475888, 0xd9ea8d5c, 0x6654d44b, 0xef77c52c, "....." },
  [3541] = { "Consegna a Jes'rimon", "Porta la ⟦Tablet of Jin'yael=Tavoletta di Jin'yael⟧ a Jes'rimon a Orgrimmar.", "Ho un ricettatore a Orgrimmar. Sta a The Drag. È difficile da scovare se non sai dove cercare, ma se guardi in uno degli edifici più alti, non dovresti avere problemi a trovarlo.\n\nFammi però un favore: non andare a gridare a tutto Kalimdor che è lì e di che cosa si occupa. Sarebbe un guaio per tutti e due.\n\nCi darà un prezzo più che giusto per la ⟦Tablet of Jin'yael=Tavoletta di Jin'yael⟧. Non so perché, ma avresti dovuto vedere quanto era emozionato quando ha saputo dove si trovava.", "Sì, cosa ti serve, amico? Io avere tante cose da sbrigare oggi, e tu non essere nella mia lista. Seccami, e io faccio in modo che le cose cambiano.", "Ahhh, Jediga manda il suo pacco fin da Azshara. Bene. Io aspettare questo.\n\nJediga, quella sì che essere una bella donna... e anche letale. Cosa può esserci di meglio?\n\nGuarda qua... la tavoletta essere in perfette condizioni. Tu fare <un/una> buon<o/a> messagger<o/a>, {name}.", 0x4e34a97a, 0x41e30fa4, 0x20977793, 0xf2fc3677, 0x7c6a3519, "....." },
  [3542] = { "Consegna ad Andron Gant", "Porta la ⟦Tablet of Markri=Tavoletta di Markri⟧ ad Andron Gant a ⟦Undercity=Sepulcra⟧.", "Andron Gant è il mio prossimo contatto. Di solito se ne sta rintanato a ⟦Undercity=Sepulcra⟧... proprio vicino all'Apothecarium.\n\nÈ stato un po' più loquace quando si è trattato di dire a cosa gli serviva la tavoletta. A quanto pare alcuni maghi di ⟦Undercity=Sepulcra⟧ vogliono studiare certi incantesimi arcani usati dagli Alti Nobili. Pensano che questa tavoletta li aiuterà. Markri era abile nell'evocare creature, specialmente elementali.\n\nPorta la ⟦Tablet of Markri=Tavoletta di Markri⟧ e torna da me per la tua parte della ricompensa.", "Ma guarda... <hic>... che sorpresa! Qualcuno in cerca d'avventurerererere... <hic>!\n\nCosa poss'io fare per te... <hic>?", "Ecco, prendi qualche moneta... comprati... <hic>... un'armatura nuova o qualcosa del genere....\n\nQuesta qua frutterà una o due belle monete d'oro dalle... <hic> persone giuste.", 0xeafb35da, 0x59e7d7dc, 0x51a61fdf, 0x12ec3263, 0xf29d0364, "....." },
  [3561] = { "Consegna all'arcimago Xylem", "Porta la ⟦Tablet of Sael'hai=Tavoletta di Sael'hai⟧ all'arcimago Xylem ad Azshara.", "Quest'ultima tavoletta va a una persona molto pericolosa, {name}. Dammi retta quando ti dico che di lui mi fido molto meno che di chiunque altro ti abbia chiesto di incontrare.\n\nL'arcimago Xylem ha una torre sulle colline che dominano Azshara. È umano, ma non si comporta come nessun umano che io abbia incontrato... o ucciso. Emana potere, e non oso chiedergli cosa intenda fare con la tavoletta.\n\nÈ venuto lui da me, ma mi ha detto che la sua guardia del corpo, Sanath, mi avrebbe aiutata a raggiungere la torre quando fossi stata pronta a incontrarlo. Cerca Sanath a nord.", "In cosa posso aiutarti, {name}?", "Ah, la ⟦Tablet of Sael'hai=Tavoletta di Sael'hai⟧... quanto ho desiderato studiarla.\n\nGrazie, {name}. Puoi dire a Jediga che ha fatto un buon lavoro. Questa varrà di certo il pagamento che ha chiesto.", 0x1e83cbca, 0x0aa23362, 0x8a0ebd1b, 0xcb59cbf2, 0xcdfb217a, "....." },
  [3562] = { "Il pagamento di Magatha a Jediga", "Consegna la ⟦Magatha's Note=Nota di Magatha⟧ a Jediga ad Azshara.", "Porta questa nota a Jediga. Dille che il pagamento sarà qui per lei al suo ritorno. E dille che sono soddisfatta del suo lavoro.\n\nVa' in fretta, {name}. Di' alla tua padrona che la aspetterò qui.", "Allora, cosa ha detto Magatha? Quella vecchia megera... scommetto che non è stata molto cortese.", "Ah, bene. È stata molto più ragionevole di quanto mi aspettassi... almeno con te. Mi aspettavo quasi che ti facesse punire per l'insolenza che ho avuto mandando qualcun altro al mio posto. Deve volere davvero tanto quella tavoletta. Interessante.\n\nCi penserò un'altra volta.", 0x3b14ab9f, 0x02e806f2, 0xf71b8e6c, 0x96d1bd37, 0x1707e51a, "....." },
  [3563] = { "Il pagamento di Jes'rimon a Jediga", "Consegna la ⟦Jes'rimon's Note=Lettera di Jes'rimon⟧ a Jediga ad Azshara.", "Porta questa lettera a Jediga. Falle sapere che il nostro affare essere stato vantaggioso e che io essere contento del suo lavoro.\n\nTu dirle di tornare presto a Orgrimmar, e Jes'rimon si prende buona cura di lei.\n\nDille questo, e forse in futuro io avere ancora bisogno dei tuoi servigi, {name}.", "Hai già parlato con Jes'rimon?\n\nÈ un cinghiale tra i troll, ma le sue informazioni di solito sono precise e i suoi lavori ben pagati.\n\nSe riesci a sopportare il suo atteggiamento, dai suoi affari puoi ricavare un bel po' di monete.", "A giudicare dalla sua nota, vedo che era più che soddisfatto.... fin troppo soddisfatto.\n\nForse un giorno troverò il tempo di fargli sapere quanto apprezzo anch'io le sue avances. Be', almeno c'è un motivo per non vedere l'ora di passare altro tempo ad Azshara.\n\nEcco la tua parte del nostro compenso.", 0xa9046055, 0x807e2f79, 0xb7a80dcb, 0xf55ca601, 0xce0311b9, "....." },
  [3564] = { "Il pagamento di Andron a Jediga", "Consegna la ⟦Andron's Note=Lettera di Andron⟧ a Jediga ad Azshara.", "Ecco... porta... <hic> questa a Jediga. Buona fortuna, eh!", "Hai già incontrato Andron? Lascia di rado ⟦Undercity=Sepulcra⟧, quindi non credo che sarà troppo difficile trovarlo.", "Perfetto... aspetta un attimo.\n\nAh ah! Cosa gli hai detto quando gli hai consegnato la tavoletta, {name}? Ci ha pagato decisamente troppo! Non che mi lamenti. Gli hai detto che l'accordo era cambiato? O era di nuovo ubriaco?\n\nNon importa... ecco, prendi anche una parte in più.", 0xd9ca2a68, 0xa50e8b74, 0x5384d93c, 0x8cbc2e7f, 0x9ea5ab0f, "....." },
  [3565] = { "Il pagamento di Xylem a Jediga", "Consegna la ⟦Xylem's Note=Lettera di Xylem⟧ a Jediga ad Azshara.", "Che c'è? Ah, sì, il tuo pagamento. Certo.\n\nPrendi questo e vattene. Sono certo che Jediga stia aspettando il tuo ritorno con taaanta pazienza.", "Allora, cosa ti ha detto Xylem? Non ti ha fatto niente, vero? Non ti ha lanciato un incantesimo? Non ti ha raggirat<o/a> per farti lavorare per lui?", "Nessun problema? Proprio nessuno? Be', questo è già qualcosa... Mi aspettavo che mostrasse una certa riluttanza, o almeno che tradisse il nostro accordo. Mmh, forse ci si può fidare di lui, dopotutto.\n\nBe', non serve rimuginarci troppo. Ecco la tua parte. Grazie per l'aiuto.", 0x09c7ab2f, 0xbc90260c, 0x8ce9adbd, 0x73c5e1a6, 0x8079cdfc, "....." },
  [3566] = { "Sorgi, Obsidion!", "Uccidi Lathoric the Black e Obsidion, poi torna da Thorius a ⟦Ironforge=Forgiardente⟧ con la ⟦Head of Lathoric the Black=Testa di Lathoric il Nero⟧ e il ⟦Heart of Obsidion=Cuore di Obsidion⟧.", "È... è... era tutta una trappola.\n\nPerdona... mi.\n\nUccidi quel bastardo... uccidilo per noi... per Thorius.", "Non ti credo! Mostrami le prove!", "<Il volto di Thorius diventa pallido.>\n\nQuesto... questo non può essere. Mio fratello? Ha architettato tutto lui?\n\n<Il volto di Thorius si contorce dalla rabbia.>\n\nHa tradito me, ha tradito ⟦Ironforge=Forgiardente⟧! Sembra che l'influenza degli Dei Antichi sia ancora forte in queste terre. Temo che, se mio fratello, un tempo uomo nobile e onorevole, si è piegato così facilmente alla volontà di Ragnaros, nessuno sia al sicuro.", 0x7fb05197, 0xfb84ebff, 0x88e5dd78, 0x4f3925a0, 0xe365ffe6, "....." },
  [3568] = { "Corruzione strisciante", "Riempi tutte e 4 le Empty Vial nelle pozze di marea lungo la costa delle ⟦Ruins of Eldarath=Rovine di Eldarath⟧, ad Azshara, poi torna dal chimico Cuely.", "Vedi quella tauren dietro di me, quella che sembra sul punto di sentirsi male da un momento all'altro? È stata ad Azshara di recente. Dice di essere stata ferita da alcuni naga mentre attraversava le ⟦Ruins of Eldarath=Rovine di Eldarath⟧.\n\nDopo averne respinti un paio, si è riposata sulla spiaggia e ha bevuto da una delle pozze di marea. Ora ha la nausea... e non solo.\n\nVorrei scoprire che cosa ha bevuto. Prendi questa scatola: dentro ci sono alcune fiale vuote che ho etichettato. Riempile in pozze diverse e torna qui.", "Sai dove porta tutto questo, vero, {name}? Non c'è modo che sopravviva... guardala. La cosa migliore per lei ora è aiutarci a trovare una cura per la pestilenza. L'acqua che ha bevuto potrebbe contenere un indizio che ci aiuti a capire come. Morirà comunque: tanto vale che, prima di morire, faccia qualcosa di nobile per il nostro popolo. Non sei d'accordo?", "Magnifico. Sei tornat<o/a> prima che morisse. Bene, bene.\n\nAllora cominciamo, che ne dici?\n\nStudio i suoi sintomi da un po' di tempo, e il quadro è piuttosto brutto. Mi sorprende che stia ancora in piedi. Ha vomitato tre o quattro volte dappertutto... un odore davvero gradevole.\n\nDammi solo un momento per preparare qualcosa da provare sulla nostra... amica.", 0x38d70828, 0x3680eba9, 0x6b26740e, 0xe6d21164, 0x046aa600, "....." },
  [3569] = { "Corruzione strisciante", "Dai l'⟦Cuely's Elixir=Elisir di Cuely⟧ a Thersa Windsong a ⟦Undercity=Sepulcra⟧.", "Da' questo a Thersa. Forse la curerà... forse no. Non lo sapremo davvero finché non l'avrà bevuto.", "Sono venuta a ⟦Undercity=Sepulcra⟧ perché ho sentito che i loro alchimisti studiano da tempo e con impegno come trovare una cura per il loro stesso male. Mi hanno suggerito che forse potevano aiutare anche me.\n\nAnche se in questo posto mi sento tutt'altro che benvenuta, non avevo scelta: la malattia che mi ha colpita mi sta divorando dentro e avevo bisogno subito del loro aiuto.", "Il chimico Cuely è stato molto disponibile... in modo inquietante. Ma se dice che questo mi aiuterà, non ho altra scelta. Non ho tempo per trovare un'altra soluzione. Ho già parlato con sacerdoti e sciamani, e nessuno di loro è riuscito ad aiutarmi.\n\nSperiamo che la Madre Terra vegli sul mio spirito.", 0x38d70828, 0x8ecbdf01, 0xdc5e548a, 0x37c1ae49, 0x59105d6c, "....." },
  [3570] = { "Corruzione strisciante", nil, nil, nil, "Non avrei mai immaginato che l'elisir avrebbe fatto effetto così in fretta. Grazie, {name}. Mi metterò subito al lavoro sul resto di questi campioni. Di certo presto potranno servire a Lady Sylvanas e ai Reietti.", 0x38d70828, nil, nil, nil, 0x38bb3b3e, ".mmm." },
  [3601] = { "Altro che Kim'jael!", "Cerca nel Thalassian Base Camp la Bussola, il Mirino, il Pollo Ripieno e lo Spreminoci di Kim'jael, poi riportali a Kim'jael, ad Azshara.", "Altro che Kim'jael!! Lo sai cosa significa Kim'jael per gli elfi del sangue, {name}? Topolino... o qualcosa del genere. Quei grossi prepotenti!\n\nMi hanno assunto per aiutarli a perlustrare la zona in cerca di non so quali tesori perduti. Naturalmente sono saltato a bordo appena hanno detto \"tesoro\" e la cifra che erano disposti a pagare, ma ovviamente mi si sono rivoltati contro e hanno cercato di uccidermi... ME!\n\nIl che dimostra che non ci si può fidare di un elfo del sangue.\n\nIl problema è che hanno ancora la mia attrezzatura e io non riesco a riprendermela. Mi dai una mano?", "Quei puzzolenti elfi del sangue. Te lo dico io, se fossi forte come te andrei laggiù a dargli una lezione di persona! Ma mi dovrò accontentare di pagare te perché te ne occupi al posto mio.", "Ah ah! Gliel'hai fatta vedere, eh?!\n\nFantastico! Così impareranno, quegli elfi del sangue, a tradire i loro soci... soprattutto uno leale come un mercante goblin! Bah, elfi del sangue...!\n\nBe', il minimo che posso fare è pagarti per il tuo tempo... proprio come avevo promesso.\n\nEcco qua... questi dovrebbero esserti utili.", 0xa956ad63, 0xfa7d5231, 0xab350b2c, 0xeca2c37d, 0xc1cbc6a5, "....." },
  [3602] = { nil, "Recupera 20 ⟦Crystallized Azsharite=Azsharite Cristallizzata⟧ nel sud di Azshara. Puoi usare il vilsegugio per «fiutare» la posizione dei depositi ben nascosti.\n\nTorna da Loramus quando avrai finito.", "Gli antichi giganti delle scogliere della regione meridionale di Azshara si nutrono delle rocce e degli edifici di queste terre. Ciò che espellono dopo averli consumati è un cristallo molto malleabile ed estremamente resistente, noto come azsharite.\n\nLe formazioni sono sparse lungo tutto l'arco meridionale, ma se ne recuperano ben poche a causa dell'indole estremamente violenta dei giganti.\n\nDevi spingerti a sud e recuperare abbastanza azsharite da creare il corpo dell'arma. I miei vilsegugi ti aiuteranno a recuperare il cristallo.", "Il male non dorme, sciocc<o/a>. Avrai tempo per riposare quando sarai finalmente mort<o/a>. Ora portami quei cristalli.", "I tuoi compiti ad Azshara sono conclusi, mortale. Ora devo forgiare i componenti necessari per il prossimo passo della tua avventura.", 0xe0c1e16e, 0xc8bece98, 0xa5e86e50, 0x9f1d4c72, 0xc180ec49, "e...." },
  [3621] = { "La creazione del Vilmale", "Porta la ⟦Shipment to Galvan=Spedizione per Galvan⟧ a Galvan l'Antico, nella Valle di Rovotorto.", "Le armi sono pronte per essere forgiate. Devi portare l'azsharite temprata a qualcuno capace di imbrigliare l'energia vile.\n\nNella Valle di Rovotorto esiste un fabbro simile. Galvan l'Antico, capo del Mithril Order, forgerà le armi secondo le tue indicazioni. Troverai il suo accampamento tra ⟦Zul'Gurub=Zul'gurub⟧ e il Tumulo degli Ogre Mosh'ogg.\n\nChe la tua determinazione e la tua fede ti sostengano in questa prova. Se dovessi fallire, sappi che il tuo Dio ti sorride dall'alto, mortale.", "Loramus, eh? Sono passati molti anni dall'ultima volta che ho sentito quel nome.", "Santo cielo, posso solo immaginare cosa hai passato per procurarti questi materiali. Pochi si avventurano ad Azshara e tornano vivi, figuriamoci chi affronta semidei e giganti!", 0xccbcf585, 0x99abba77, 0x50c2a1b5, 0x28677752, 0x61496e75, "....." },
  [3625] = { "Armi vili di Azsharite incantata", "Attendi che Galvan finisca di forgiare le armi.", "{name}, la creazione di ogni arma richiederà un po' di tempo.\n\nInoltre, potrai usare il potere del Felcurse solo una volta ogni tre minuti. La durata del suo effetto indebolente su Razelikh il Profanatore e sui suoi servitori può variare. Per questo devi scatenare il Felcurse solo al momento giusto!\n\nOra dammi un momento per forgiare la tua arma, {name}.", "Interrompere la forgiatura potrebbe dare un'arma imperfetta. Pazienza, {name}.", "<Galvan si asciuga il sudore dalla fronte.>\n\nNon è mai esistita un'arma ammazzademoni migliore, {name}.", 0x730cdf69, 0x60b82d6d, 0xa22882fb, 0x6169881c, 0x241a8eea, "....." },
  [3626] = { "Ritorno alle ⟦Blasted Lands=Terre Devastate⟧", "Torna dall'Eroe Caduto dell'⟦Horde=Orda⟧.", "L'ora della redenzione è vicina, {name}. Devi tornare nelle ⟦Blasted Lands=Terre Devastate⟧ con le tue nuove armi e parlare con l'Eroe Caduto dell'⟦Horde=Orda⟧ per ricevere il tuo ultimo obiettivo.", nil, "Sembri temprat<o/a> dalla battaglia, {name}. Sei pront<o/a> ad affrontare Razelikh e i suoi servitori?", 0xabec8174, 0xa1f27799, 0xac47adc8, nil, 0x2aac230d, "...m." },
  [3627] = { "Riunire l'amuleto infranto", "Uccidi Grol the Destroyer, Lady Sevine e Archmage Allistarj. Prendi dai loro cadaveri l'⟦Amulet of Grol=Amuleto di Grol⟧, l'⟦Amulet of Sevine=Amuleto di Sevine⟧ e l'⟦Amulet of Allistarj=Amuleto di Allistarj⟧.\n\nRicorda di USARE le tue armi incantate di Azsharite del Vilmale per indebolire la triade. Altrimenti non si possono uccidere, ma usale con giudizio...", "Per raggiungere il Profanatore devi prima distruggere la triade del potere e recuperare i frammenti dell'amuleto. Quando avrai recuperato tutti e tre i frammenti, torna da me e ti darò altre istruzioni.\n\nVa', {name}! Nelle ⟦Blasted Lands=Terre Devastate⟧! Sevine, Allistarj e Grol devono cadere!", "I tre formeranno l'uno, l'uno illuminerà la via.", "L'amuleto di Razelikh il Profanatore è di nuovo completo, ma lui avverte la frattura nella sua catena di comando. Sa che stai venendo a cercarlo...", 0x44f1cf37, 0x2d4201e5, 0xeaa447f3, 0xede28e58, 0x281d72b0, "....." },
  [3628] = { "Tu sei Rakh'likh, demone", "Distruggi Razelikh the Defiler e riporta il ⟦Severed Horn of the Defiler=Corno del Profanatore Staccato⟧ all'Eroe Caduto dell'⟦Horde=Orda⟧. Dovrai anche riportare il Ward of the Defiler, così che l'Eroe Caduto possa distruggerlo e impedire che finisca mai in mani sbagliate.", "Il covo di Razelikh si trova in cima alla montagna più alta delle ⟦Blasted Lands=Terre Devastate⟧. L'unico modo per raggiungerlo è usare le rune di teletrasporto vicino alla montagna. Finché avrai con te l'amuleto, potrai trasportarti liberamente fino al covo. Una volta lì, dovrai evocare la bestia. L'amuleto è la tua chiave, {name}. Usalo sull'altare del Profanatore.\n\nSe sconfiggerai il Profanatore, riportami il suo corno. Diventerà un simbolo di speranza per chiunque lo veda: la prova che gli eroi esistono davvero in questo mondo dilaniato dalla guerra.", "Non c'è più nulla da temere.", "Oggi è un giorno che sarà ricordato per l'eternità. Il signore supremo demoniaco delle ⟦Blasted Lands=Terre Devastate⟧ è finalmente caduto!", 0xb2d1d4a9, 0x9f71e0ee, 0xd0cab34d, 0xad069565, 0x28cc70b1, "....." },
  [3629] = { "⟦Goblin Engineering=Ingegneria dei Goblin⟧", "Se vuoi saperne di più sull'⟦Goblin Engineering=Ingegneria dei Goblin⟧, porta il ⟦Manual of Engineering Disciplines=Manuale delle Discipline Ingegneristiche⟧ a Nixx Sprocketspring, a ⟦Gadgetzan=Meccania⟧.", "L'ingegneria di livello esperto si divide in due discipline distinte: quella degli gnomi e quella dei goblin. Ti parlo dell'Ingegneria dei Goblin solo perché sono un istruttore onesto. Ai goblin piace costruire cose che esplodono, e raramente si curano di ciò che sta in mezzo... nemmeno di se stessi.\n\n{name}, leggi questo manuale. Se vuoi imparare a farti saltare in aria, portalo a Nixx Sprocketspring, a ⟦Gadgetzan=Meccania⟧. Ricorda: l'iscrizione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati che sia ciò che vuoi prima di completare il suo compito.", "Le reclute fresche le fiuto come fiuto un'ottima polvere esplosiva: a un miglio di distanza. Sei venut<o/a> per imparare a padroneggiare l'esplosione?", "Be', {name}, hai fatto bene a cercare la mia guida! Qualsiasi sprovveduto può diventare esperto nelle basi dell'ingegneria: gli gnomi e la loro casa radioattiva, Gnomeregan, ne sono la prova. Ma per padroneggiare la disciplina dell'⟦Goblin Engineering=Ingegneria dei Goblin⟧ ci vogliono una mente forte e una mano ferma (e sottolineo FERMA).\n\nTieni le orecchie dritte, {name}, e forse imparerai qualcosa.", 0x4ccb3e9c, 0x84f932f9, 0x52e16ce5, 0x21f4153d, 0xad63c1bf, "....." },
  [3630] = { "Ingegneria degli Gnomi", "Se vuoi saperne di più sull'Ingegneria degli Gnomi, porta il ⟦Manual of Engineering Disciplines=Manuale delle Discipline Ingegneristiche⟧ al mastro inventore Overspark, a ⟦Ironforge=Forgiardente⟧.", "L'ingegneria di livello esperto si divide in due discipline: quella degli gnomi e quella dei goblin. L'Ingegneria degli Gnomi è di gran lunga la migliore delle due! Si occupa della costruzione di congegni e dispositivi meravigliosi che rendono la vita migliore!\n\n{name}, leggi questo manuale. Se vuoi saperne di più sull'Ingegneria degli Gnomi, porta il manuale al mastro inventore Overspark, a ⟦Ironforge=Forgiardente⟧. Ricorda: l'iscrizione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati di esserne <sicuro/sicura> prima di completare il suo compito!", "Sì, sì, di che cosa hai bisogno oggi? Il tempo di certo non mi manca, visto che non faccio altro che starmene qui mentre la nostra amata città giace in una nube di morte radioattiva.", "Ah, una giovane mente dell'ingegneria che vuole seguire l'unica, vera disciplina dell'ingegneria! Be', perdona il mio melodramma, amico. Anche se la nostra situazione resta disperata, è sempre una bella giornata quando un altro ingegnere risponde allo squillo di tromba della vera ingegneria!", 0x963c40b5, 0xab72bd39, 0xf53fb9a4, 0xc8d72920, 0x23d1ca8c, "....." },
  [3631] = { "L'evocazione del vildestriero", "Parla con Strahad Farsan nelle ⟦Barrens=Savane⟧.", "Mpf. Io dico che non sei pront<o/a>, ma non spetta a me deciderlo. Strahad la pensa diversamente, e la decisione è sua... stavolta.\n\nVuole parlarti, e in fretta. Lo troverai ancora sopra ⟦Ratchet=Porto Paranco⟧, nelle ⟦Barrens=Savane⟧, nella sua piccola torre insieme ai suoi accoliti.\n\nNon perdere tempo.", nil, "Dunque hai deciso di onorarmi di nuovo della tua presenza. Che gentilezza.\n\nI miei accoliti si chiedevano se saresti mai venut<o/a>. Ho detto loro che non c'era alcun dubbio. Quando si tratta di potere, ne sei attratt<o/a> come una falena dalla fiamma.", 0x5220fbc8, 0xf356d493, 0xc98053e2, nil, 0x23773eba, "...m." },
  [3632] = { "Ingegneria degli Gnomi", "Se vuoi saperne di più sull'Ingegneria degli Gnomi, porta il ⟦Manual of Engineering Disciplines=Manuale delle Discipline Ingegneristiche⟧ al mastro inventore Overspark, a ⟦Ironforge=Forgiardente⟧.", "L'ingegneria di livello esperto si divide in due discipline: quella degli gnomi e quella dei goblin. L'Ingegneria degli Gnomi è di gran lunga la migliore delle due! Si occupa della costruzione di congegni e dispositivi meravigliosi che rendono la vita migliore!\n\n{name}, leggi questo manuale. Se vuoi saperne di più sull'Ingegneria degli Gnomi, porta il manuale al mastro inventore Overspark, qui a ⟦Ironforge=Forgiardente⟧. Ricorda: l'iscrizione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati di esserne <sicuro/sicura> prima di completare il suo compito!", "Sì, sì, di che cosa hai bisogno oggi? Il tempo di certo non mi manca, visto che non faccio altro che starmene qui mentre la nostra amata città giace in una nube di morte radioattiva.", "Ah, una giovane mente dell'ingegneria che vuole seguire l'unica, vera disciplina dell'ingegneria! Be', perdona il mio melodramma, amico. Anche se la nostra situazione resta disperata, è sempre una bella giornata quando un altro ingegnere risponde allo squillo di tromba della vera ingegneria!", 0x963c40b5, 0xab72bd39, 0x73a63c06, 0xc8d72920, 0x23d1ca8c, "....." },
  [3633] = { "⟦Goblin Engineering=Ingegneria dei Goblin⟧", "Se vuoi saperne di più sull'⟦Goblin Engineering=Ingegneria dei Goblin⟧, porta il ⟦Manual of Engineering Disciplines=Manuale delle Discipline Ingegneristiche⟧ a Nixx Sprocketspring, a ⟦Gadgetzan=Meccania⟧.", "L'ingegneria di livello esperto si divide in due discipline distinte: quella degli gnomi e quella dei goblin. È chiaro che l'Ingegneria dei Goblin è la scelta di tutti gli ingegneri brillanti. Impara a dominare il mondo con un uso giudizioso di esplosivi potenti e di congegni fantastici!\n\n{name}, leggi questo manuale. Se vuoi conoscere l'Ingegneria dei Goblin, portalo a Nixx Sprocketspring, a ⟦Gadgetzan=Meccania⟧. Ricorda: l'iscrizione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati che sia ciò che vuoi prima di completare il suo compito.", "Le reclute fresche le fiuto come fiuto un'ottima polvere esplosiva: a un miglio di distanza. Sei venut<o/a> per imparare a padroneggiare l'esplosione?", "Be', {name}, hai fatto bene a cercare la mia guida! Qualsiasi sprovveduto può diventare esperto nelle basi dell'ingegneria: gli gnomi e la loro casa radioattiva, Gnomeregan, ne sono la prova. Ma per padroneggiare la disciplina dell'⟦Goblin Engineering=Ingegneria dei Goblin⟧ ci vogliono una mente forte e una mano ferma (e sottolineo FERMA).\n\nTieni le orecchie dritte, {name}, e forse imparerai qualcosa.", 0x4ccb3e9c, 0x84f932f9, 0x31040b00, 0x21f4153d, 0xad63c1bf, "....." },
  [3634] = { "Ingegneria degli Gnomi", "Se vuoi saperne di più sull'Ingegneria degli Gnomi, porta il ⟦Manual of Engineering Disciplines=Manuale delle Discipline Ingegneristiche⟧ al mastro inventore Overspark, a ⟦Ironforge=Forgiardente⟧.", "L'ingegneria di livello esperto si divide in due discipline: quella degli gnomi e quella dei goblin. Anche se credo che sia uno spreco, dovresti conoscere la specializzazione degli gnomi. Costruiscono oggetti e congegni che pretendono di cambiare il mondo, ma che raramente funzionano.\n\n{name}, leggi questo manuale. Se vuoi imparare a fabbricare fermacarte di metallo, porta il manuale al mastro inventore Overspark, a ⟦Ironforge=Forgiardente⟧. Ricorda: l'iscrizione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati di esserne <sicuro/sicura> prima di completare il suo compito!", "Sì, sì, di che cosa hai bisogno oggi? Il tempo di certo non mi manca, visto che non faccio altro che starmene qui mentre la nostra amata città giace in una nube di morte radioattiva.", "Ah, una giovane mente dell'ingegneria che vuole seguire l'unica, vera disciplina dell'ingegneria! Be', perdona il mio melodramma, amico. Anche se la nostra situazione resta disperata, è sempre una bella giornata quando un altro ingegnere risponde allo squillo di tromba della vera ingegneria!", 0x963c40b5, 0xab72bd39, 0xc301270e, 0xc8d72920, 0x23d1ca8c, "....." },
  [3635] = { "Ingegneria degli Gnomi", "Se vuoi saperne di più sull'Ingegneria degli Gnomi, porta il ⟦Manual of Engineering Disciplines=Manuale delle Discipline Ingegneristiche⟧ a Oglethorpe Obnoticus, alla ⟦Booty Bay=Baia del Bottino⟧.", "L'ingegneria di livello esperto si divide in due discipline: quella degli gnomi e quella dei goblin. Anche se credo che sia uno spreco, dovresti conoscere la specializzazione degli gnomi. Costruiscono oggetti e congegni che pretendono di cambiare il mondo, ma che raramente funzionano.\n\n{name}, leggi questo manuale. Se vuoi imparare a fabbricare fermacarte di metallo, porta il manuale a Oglethorpe Obnoticus, alla ⟦Booty Bay=Baia del Bottino⟧. Ricorda: l'iscrizione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati di esserne <sicuro/sicura> prima di completare il suo compito.", "Salve! Se sei qui per un robot a ricerca automatica che potrebbe aver sfondato un muro della tua abitazione, ti rimando fin d'ora al mio avvocato. Altrimenti, che cosa posso fare per te oggi?", "Sei venut<o/a> a conoscere l'Ingegneria degli Gnomi, eh? Be', sei venut<o/a> dallo gnomo giusto. La fazione che governa Gnomeregan può anche usare la politica per emarginare chi considera una minaccia intellettuale, ma sa bene che la conoscenza è qualcosa che non può controllare.\n\nSia loro che io sappiamo che, quando ho lasciato Gnomeregan, hanno perso uno dei più grandi ingegneri gnomi oggi in vita. Se sei <un/una> <allievo/allieva> capace, ti insegnerò ciò che so.", 0x963c40b5, 0x6595257c, 0x478a11f0, 0x110595dc, 0xebc8c2cf, "....." },
  [3636] = { "Porta la Luce", "L'arcivescovo Bendictus vuole che tu uccida Amnennar the Coldbringer nei ⟦Razorfen Downs=Sotterranei di Lamaspina⟧.", "Il Flagello è una minaccia costante per l'⟦Alliance=Alleanza⟧, cosa che sono certo tu sappia molto bene. Di recente abbiamo fatto alcune scoperte davvero singolari, {name}.\n\nNelle ⟦Barrens=Savane⟧ si trova un orrendo intrico di rovi chiamato ⟦Razorfen Downs=Sotterranei di Lamaspina⟧. Un tempo era la dimora di semplici verrospini, ma ora è chiaro che è stato stretto un patto con il Flagello, che ha generato creature ben peggiori... Ora sono governati dal lich Amnennar l'Araldo del Freddo.\n\nSchierati con la Luce, {name}; poni fine a questa malvagia unione.", "Amnennar deve essere annientato. Va', presto.", "Grazie, {name}. Ora il Flagello ci penserà due volte prima di tentare di nuovo di rinforzare i suoi ranghi.\n\nChe la Luce ti benedica.", 0x15219363, 0x58355ea6, 0xf1d2ffc7, 0x30367c57, 0xaa15e714, "....." },
  [3637] = { "Ingegneria degli Gnomi", "Se vuoi saperne di più sull'Ingegneria degli Gnomi, porta il ⟦Manual of Engineering Disciplines=Manuale delle Discipline Ingegneristiche⟧ a Oglethorpe Obnoticus, alla ⟦Booty Bay=Baia del Bottino⟧.", "L'ingegneria di livello esperto si divide in due discipline: quella degli gnomi e quella dei goblin. Anche se credo che sia uno spreco, dovresti conoscere la specializzazione degli gnomi. Costruiscono oggetti e congegni che pretendono di cambiare il mondo, ma che raramente funzionano.\n\n{name}, leggi questo manuale. Se vuoi imparare a fabbricare fermacarte di metallo, porta il manuale a Oglethorpe Obnoticus, alla ⟦Booty Bay=Baia del Bottino⟧. Ricorda: l'iscrizione è permanente e impedisce di unirsi all'altra disciplina, quindi assicurati di esserne <sicuro/sicura> prima di completare il suo compito.", "Salve! Se sei qui per un robot a ricerca automatica che potrebbe aver sfondato un muro della tua abitazione, ti rimando fin d'ora al mio avvocato. Altrimenti, che cosa posso fare per te oggi?", "Sei venut<o/a> a conoscere l'Ingegneria degli Gnomi, eh? Be', sei venut<o/a> dallo gnomo giusto. La fazione che governa Gnomeregan può anche usare la politica per emarginare chi considera una minaccia intellettuale, ma sa bene che la conoscenza è qualcosa che non può controllare.\n\nSia loro che io sappiamo che, quando ho lasciato Gnomeregan, hanno perso uno dei più grandi ingegneri gnomi oggi in vita. Se sei <un/una> <allievo/allieva> capace, ti insegnerò ciò che so.", 0x963c40b5, 0x6595257c, 0x478a11f0, 0x110595dc, 0xebc8c2cf, "....." },
  [3638] = { "Il patto di segretezza", "Se accetti di dedicarti all'⟦Goblin Engineer=Ingegneria dei Goblin⟧, clicca con il tasto destro sul Giuramento di Segretezza e parla di nuovo con Nixx Sprocketspring, a ⟦Gadgetzan=Meccania⟧.", "L'Ingegneria dei Goblin punta agli usi pratici: grandi profitti e una potenza esplosiva ancora più grande! I nostri schemi ci permettono di costruire bombe potenti e armi formidabili; il manuale che hai letto ne parlava.\n\nIl manuale parlava anche del nostro antichissimo giuramento di segretezza sui nostri schemi. Una volta diventato ingegnere goblin, non si torna indietro. Non avrai alcun accesso all'Ingegneria degli Gnomi.\n\nSe vuoi ancora diventare ingegnere goblin, firma questo documento con cui giuri segretezza per tutta la vita e parla di nuovo con me. Pensaci bene, {name}.", "Se hai firmato il documento e sei pront<o/a> a consegnarmelo, allora è fatta. Ti è stato detto che è un viaggio di sola andata. Se sei pront<o/a>, sali a bordo!", "Benvenut<o/a> a bordo nell'⟦Goblin Engineer=Ingegneria dei Goblin⟧, ingegner {name}! Presto avrai accesso agli schemi d'ingegneria più potenti di tutta Azeroth.\n\nOra che ti sei impegnat<o/a> a perseguire questa conoscenza, è il momento di esaminare il tuo lavoro d'ingegneria in stile goblin. Da lì ti aiuteremo a costruire un piano per sfruttare al massimo il tuo talento nell'⟦Goblin Engineer=Ingegneria dei Goblin⟧!", 0x377e89c9, 0x1c9a7579, 0xe3b7826f, 0x488e5de6, 0xac54b098, "....." },
  [3639] = { "Mostra il tuo lavoro", "Porta 20 Grande Bomba di Ferro, 20 ⟦Solid Dynamite=Dinamite Solida⟧ e 5 ⟦Explosive Sheep=Pecora Esplosiva⟧ a Nixx Sprocketspring, a ⟦Gadgetzan=Meccania⟧.", "Come tuo mentore, voglio dei campioni del tuo lavoro. Sei un ingegnere abile, su questo non c'è dubbio, {name}. Però vorrei analizzarli per capire come dare più spazio alle tecniche goblin nei tuoi lavori futuri. Mi serve questo: venti grandi bombe di ferro, venti candelotti di dinamite solida e cinque pecore esplosive... e tieni le sicure inserite!\n\nConsegnami questi oggetti e ti rilascerò la tua ⟦Goblin Engineer Membership Card=Tessera di Socio degli Ingegneri Goblin⟧; è necessaria per accedere a tutti gli istruttori di Ingegneria dei Goblin!", "Quando avrò ricevuto gli oggetti d'ingegneria che hai costruito, da esaminare, ti consegnerò un'autentica ⟦Goblin Engineer Membership Card=Tessera di Socio degli Ingegneri Goblin⟧! Finché la tessera è valida, avrai accesso illimitato a qualsiasi istruttore di Ingegneria dei Goblin del mondo.", "Ecco la tua prima ⟦Goblin Engineer Membership Card=Tessera di Socio degli Ingegneri Goblin⟧!\n\nQuesta tessera ha la quota pagata in anticipo per quattordici giorni; tutte le tessere scadono dopo due settimane di attività. Quando succede, paga la quota successiva a un qualsiasi istruttore di Ingegneria dei Goblin per avere un'altra tessera; senza la tessera, la tua iscrizione sarà temporaneamente sospesa e non potrai accedere a nuovi schemi.\n\nQuesto non tocca mai ciò che sai già: ingegnere goblin una volta, ingegnere goblin per sempre.", 0x28ad35d0, 0x60c595fd, 0x22d1c014, 0x1dccf7ff, 0xaf83734e, "....." },
  [3640] = { "Il patto di segretezza", "Se accetti di dedicarti all'Ingegneria degli Gnomi, clicca con il tasto destro sul Patto di Segretezza e parla di nuovo con il mastro inventore Overspark, a ⟦Ironforge=Forgiardente⟧.", "L'Ingegneria degli Gnomi è teoria ingegneristica plasmata per servire le nostre necessità! I nostri schemi ci permettono di costruire dispositivi che controllano il mondo intorno a noi; il manuale che hai letto ne parlava.\n\nIl manuale parlava anche del nostro antichissimo giuramento di segretezza sui nostri schemi. Una volta diventato ingegnere gnomico, non si torna indietro. Non avrai alcun accesso all'Ingegneria dei Goblin.\n\nSe vuoi ancora diventare ingegnere gnomico, firma questo documento con cui giuri segretezza per tutta la vita e parla di nuovo con me. Pensaci bene, {name}.", "Se hai firmato il documento e sei pront<o/a> a consegnarmelo, allora è fatta.\n\nI segreti che condividerò con te sono di tale portata che firmare il Patto di Segretezza è assolutamente fondamentale. Io l'ho firmato, e così i miei fratelli e le mie sorelle ingegneri gnomi. Entrerai a far parte di una cerchia davvero illustre, ingegner {name}!", "Benvenut<o/a> a bordo, {name}! Presto avrai accesso agli schemi d'ingegneria più avanzati di tutta Azeroth.\n\nOra che ti sei impegnat<o/a> a perseguire questa conoscenza, è il momento di esaminare il tuo lavoro d'ingegneria in stile gnomico. Da lì ti aiuteremo a costruire un piano per sfruttare al massimo il tuo talento nell'Ingegneria degli Gnomi!", 0x377e89c9, 0x84e69e0f, 0x214b7ad1, 0x19cea1d0, 0xfdd2709b, "....." },
  [3641] = { "Mostra il tuo lavoro", "Porta 6 Tubo di Mithril, un ⟦Accurate Scope=Mirino Accurato⟧ e 2 Manichino a Molla Avanzato al mastro inventore Overspark, a ⟦Ironforge=Forgiardente⟧.", "Come tuo mentore, voglio alcuni campioni del tuo lavoro. Sei un ingegnere abile, su questo non c'è dubbio, {name}. Però vorrei analizzare il tuo lavoro per capire come dare più spazio alle tecniche gnomiche nei tuoi lavori futuri. Mi servono questi campioni: sei tubi di mithril, un mirino accurato e due manichini a molla avanzati.\n\nConsegnami questi oggetti e ti rilascerò la tua ⟦Gnome Engineer Membership Card=Tessera di Socio degli Ingegneri Gnomi⟧; è necessaria per accedere a tutti gli istruttori di Ingegneria degli Gnomi!", "Quando avrò ricevuto gli oggetti d'ingegneria che hai costruito, da esaminare, ti consegnerò un'autentica ⟦Gnome Engineer Membership Card=Tessera di Socio degli Ingegneri Gnomi⟧! Finché la tessera è valida, avrai accesso illimitato a qualsiasi istruttore di Ingegneria degli Gnomi del mondo.", "Ecco la tua prima ⟦Gnome Engineer Membership Card=Tessera di Socio degli Ingegneri Gnomi⟧!\n\nQuesta tessera ha la quota pagata in anticipo per quattordici giorni; tutte le tessere scadono dopo due settimane di attività. Quando succede, paga la quota successiva a un qualsiasi istruttore di Ingegneria degli Gnomi per avere un'altra tessera; senza la tessera, la tua iscrizione sarà temporaneamente sospesa e non potrai accedere a nuovi schemi.\n\nQuesto non tocca mai ciò che sai già: ingegnere gnomico una volta, ingegnere gnomico per sempre.", 0x28ad35d0, 0x8f3af78f, 0x0315cb1b, 0x6d0fae99, 0xd8998a19, "....." },
  [3642] = { "Il patto di segretezza", "Se accetti di dedicarti all'Ingegneria degli Gnomi, clicca con il tasto destro sul Patto di Segretezza e parla di nuovo con Oglethorpe Obnoticus, alla Baia del Bottino.", "L'Ingegneria degli Gnomi è teoria ingegneristica plasmata per servire le nostre necessità! I nostri schemi ci permettono di costruire dispositivi che controllano il mondo intorno a noi; il manuale che hai letto ne parlava.\n\nIl manuale parlava anche del nostro antichissimo giuramento di segretezza sui nostri schemi. Una volta diventato ingegnere gnomico, non si torna indietro. Non avrai alcun accesso all'Ingegneria dei Goblin.\n\nSe vuoi ancora diventare ingegnere gnomico, firma questo documento con cui giuri segretezza per tutta la vita e parla di nuovo con me. Pensaci bene, {name}.", "Se hai firmato il documento e sei pront<o/a> a consegnarmelo, allora è fatta.\n\nAnche se in politica posso essere in profondo disaccordo con Gnomeregan, specialmente con quello sciocco del mastro inventore Overspark, il Patto di Segretezza trascende ogni altra cosa! Devi accettare di impegnarti in un'unica strada e restarle fedele per tutta la vita.", "Benvenut<o/a> a bordo, {name}! Presto avrai accesso agli schemi d'ingegneria più avanzati di tutta Azeroth.\n\nOra che ti sei impegnat<o/a> a perseguire questa conoscenza, è il momento di esaminare il tuo lavoro d'ingegneria in stile gnomico. Da lì ti aiuteremo a costruire un piano per sfruttare al massimo il tuo talento nell'Ingegneria degli Gnomi!", 0x377e89c9, 0x2d86b3ca, 0x214b7ad1, 0x6e5d0046, 0xfdd2709b, "....." },
  [3643] = { "Mostra il tuo lavoro", "Porta 6 Tubo di Mithril, un ⟦Accurate Scope=Mirino Accurato⟧ e 2 Manichino a Molla Avanzato a Oglethorpe Obnoticus, alla ⟦Booty Bay=Baia del Bottino⟧.", "Come tuo mentore, voglio alcuni campioni del tuo lavoro. Sei un ingegnere abile, su questo non c'è dubbio, {name}. Però vorrei analizzare il tuo lavoro per capire come dare più spazio alle tecniche gnomiche nei tuoi lavori futuri. Mi servono questi campioni: sei tubi di mithril, un mirino accurato e due manichini a molla avanzati.\n\nConsegnami questi oggetti e ti rilascerò la tua ⟦Gnome Engineer Membership Card=Tessera di Socio degli Ingegneri Gnomi⟧; è necessaria per accedere a tutti gli istruttori di Ingegneria degli Gnomi!", "Quando avrò ricevuto gli oggetti d'ingegneria che hai costruito, da esaminare, ti consegnerò un'autentica ⟦Gnome Engineer Membership Card=Tessera di Socio degli Ingegneri Gnomi⟧! Finché la tessera è valida, avrai accesso illimitato a qualsiasi istruttore di Ingegneria degli Gnomi del mondo.", "Ecco la tua prima ⟦Gnome Engineer Membership Card=Tessera di Socio degli Ingegneri Gnomi⟧!\n\nQuesta tessera ha la quota pagata in anticipo per quattordici giorni; tutte le tessere scadono dopo due settimane di attività. Quando succede, paga la quota successiva a un qualsiasi istruttore di Ingegneria degli Gnomi per avere un'altra tessera; senza la tessera, la tua iscrizione sarà temporaneamente sospesa e non potrai accedere a nuovi schemi.\n\nQuesto non tocca mai ciò che sai già: ingegnere gnomico una volta, ingegnere gnomico per sempre.", 0x28ad35d0, 0xa2c12436, 0x0315cb1b, 0x6d0fae99, 0xd8998a19, "....." },
  [3661] = { "Prediletti di Elune?", "Raccogli 15 Penna di Silvagufo nelle Entroterre per Erelas Ambersky, a ⟦Rut'theran Village=Rut'theran⟧.", "I silvagufi sono creature piuttosto imprevedibili, {name}. Capaci di una dolcezza incredibile, mostrano una ferocia estrema se qualcosa che ritengono importante è minacciato.\n\nSi dice che queste bestie siano state create da Elune, e mi interessa scoprire se è davvero così.\n\nDi recente ho sentito parlare di una popolazione di silvagufi che vive nelle Entroterre: Vicious Owlbeast, Primitive Owlbeast e Savage Owlbeast. Si trovano tra la fauna del posto. Mi raccoglieresti delle penne di silvagufo?", "Cerca di evitarli, se puoi, {name}. I silvagufi potrebbero scambiare il tuo interesse per l'intenzione di far loro del male...", "Grazie di avermele portate, {name}.\n\nChe cosa hai scoperto sui silvagufi?\n\nForse queste penne ci diranno di più. Mostri feroci, o semplicemente animali prediletti smarriti? Un giorno vorrei conoscere la verità...\n\nContinuerò le mie ricerche; torna a parlarmi quando sarà passato un po' di tempo.", 0xc37a4269, 0xcccfc461, 0x07d63186, 0x6980b3e3, 0x9787a159, "....." },
  [3681] = { "⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "Scusa se interrompo i tuoi viaggi, {race}, ma ho pensato che dovessi sapere che di recente è arrivata notizia da ⟦Stormwind=Roccavento⟧: si chiede ai paladini di presentarsi lì per l'addestramento.\n\nSe non sbaglio, direi che ti stai avvicinando a un momento speciale ed è ora che cominci a studiare i Tomi.\n\nCerca Duthorian Rall a ⟦Stormwind=Roccavento⟧. Di solito addestra i paladini nella ⟦Cathedral of Light=Cattedrale della Luce⟧.", nil, "Benvenut<o/a> nella ⟦Cathedral of Light=Cattedrale della Luce⟧, {class}.", 0x85861feb, 0xfa9ae08e, 0x355bcc91, nil, 0x252bde23, "...m." },
  [3701] = { "Le fumanti ⟦Ruins of Thaurissan=Rovine di Thaurissan⟧", "Avventurati fino alle ⟦Ruins of Thaurissan=Rovine di Thaurissan⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧, e ricava informazioni dalle Thaurissan Relics. Quando avrai recuperato le informazioni, torna dallo storico reale Archesonus.", "Avventurati fino alle fumanti rovine di Thaurissan, nelle ⟦Burning Steppes=Steppe Ardenti⟧, e raccogli quante più informazioni puoi.\n\nSi dice che misteriose reliquie siano sparse tra le rovine. Forse dovresti cominciare la ricerca da lì, {name}. Attento ai guardiani di Thaurissan: assassini che sorvegliano le rovine e proteggono qualunque segreto vi sia ancora sepolto.", "Porti nuove informazioni?", "Oh, cielo! Queste informazioni spiegano parecchie cose su Thaurissan.\n\nC'è ancora molto da imparare!", 0x1388ff2f, 0x7fad64f0, 0x44373936, 0x9da52d5c, 0xba8be352, "....." },
  [3702] = { "Le fumanti ⟦Ruins of Thaurissan=Rovine di Thaurissan⟧", "Ascolta lo storico reale Archesonus raccontare la storia di Thaurissan.", "Vuoi ascoltare una breve storia dei nani ⟦Dark Iron=Ferroscuro⟧?", "Permettimi di finire di raccontarti la storia di Thaurissan.", "Proseguiamo?", 0x1388ff2f, 0x6e7ab0a1, 0x0e208f1c, 0xe4703b62, 0x759e0656, "....." },
  [3721] = { "Un OOX tutto tuo", nil, nil, nil, "Hai recuperato tre dei miei robot autoguidati OOX! Sei andat<o/a> ben oltre il necessario, quindi ti darò qualcosa di speciale per tutto il tuo aiuto. È una versione in miniatura dello stesso robot che hai imparato a conoscere e ad amare: l'OOX!\n\nDi solito non lascerei a nessuno un congegno potenzialmente così letale, ma mi sei stat<o/a> di grande aiuto. E poi, i meccanismi di combattimento e la logica di autoguida di questo esemplare sono stati disattivati.\n\nA parte questo, è un OOX in tutto e per tutto, perbacco!", 0xe02f962a, nil, nil, nil, 0xb41bd7fe, ".mmm." },
  [3741] = { "La collana di Hilary", "Trova la collana di Hilary e riportala a Hilary, a ⟦Lakeshire=Borgolago⟧.", "La mia amica Hilary ha perso la sua collana e non riusciamo a trovarla. Abbiamo pescato qui tutto il giorno e abbiamo già cercato qui intorno. L'unica cosa che mi viene in mente è che sia caduta nel lago. I nostri genitori non vogliono che facciamo il bagno nel lago... la mia mamma dice che sott'acqua ci sono delle cose cattive, ma tu non sembri aver paura delle cose cattive.\n\nPotresti trovarla per lei, per favore?", "Ciao. Mi manca la mia collana. Me l'aveva regalata il mio papà. Papà dice che nel lago ci sono i mostri. Hai picchiato qualche mostro?", "Grazie per aver trovato la mia collana, <signor/signorina> {class}... sei tanto gentile! Ti ringrazia anche il mio gattino, vero Effsee?", 0x42188c01, 0x56803c15, 0xf3c09303, 0xe8736a32, 0x7a3fe990, ".....", nil, nil, nil, nil, 0xed8e927e },
  [3761] = { "⟦Un'Goro Soil=Terreno di Un'Goro⟧", "Porta 20 campioni di ⟦Un'Goro Soil=Terreno di Un'Goro⟧ a Ghede, sull'⟦Elder Rise=Altura degli Anziani⟧ di ⟦Thunder Bluff=Picco del Tuono⟧.", "Si dice che il suolo del ⟦Un'Goro Crater=Cratere di Un'Goro⟧ sia ricco di potenti proprietà magiche. Il ⟦Cenarion Circle=Circolo Cenariano⟧ vuole studiarlo in grandi quantità: addentrati nelle terre selvagge di Un'Goro e procuratene abbastanza per proseguire le nostre ricerche.\n\nIl terreno fertile affiora qua e là in mucchi, e alcune bestie potrebbero averne addosso dei campioni utilizzabili. Portali tutti qui fuori a Ghede: cerca i mucchi di terra e il tauren che abbaia ordini. Ha buone intenzioni, basta non farlo arrabbiare!", "Riposo, soldato. Se sei qui per scaricare terra da Un'Goro, allora magnifico! Altrimenti, sparisci.", "Ma certo, soldato {name}, non fare il minimo sforzo per aiutarmi a scaricare questa terra sui mucchi! Se i Grandi Spiriti avessero voluto farlo, ce l'avrebbero portata lassù con un miracolo, non ti pare?!\n\nL'arcidruido Runetotem vuole parlarti di nuovo, ma per il suo prossimo incarico ti sarà utile una discreta conoscenza dell'Erbalismo. Se però non la possiedi, troverà comunque il modo di servirsi di te.", 0x158a6d09, 0x2d72886c, 0x7f829e93, 0x861e8e17, 0x8b0d244a, "....." },
  [3762] = { "In aiuto dell'arcidruido Runetotem", "Parla con l'arcidruido Hamuul Runetotem, a ⟦Thunder Bluff=Picco del Tuono⟧.", "Scusami, {class}, ma vorrei un momento del tuo tempo, se possibile.\n\nIl ⟦Cenarion Circle=Circolo Cenariano⟧ di ⟦Thunder Bluff=Picco del Tuono⟧ cerca avventurieri esperti come te che lo aiutino in un progetto di ricerca di vitale importanza. Non ne conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che Hamuul Runetotem.\n\nTi prego, se ti interessa, parla direttamente con lui sull'⟦Elder Rise=Altura degli Anziani⟧, a ⟦Thunder Bluff=Picco del Tuono⟧.", nil, "Salute, {class}; sono lieto che tu voglia aiutarci nella nostra ricerca. C'è molto da fare, e ti farei un torto se ti dicessi che questo lavoro non è pericoloso. Spero che non ti spaventi... ma, a giudicare dal tuo aspetto, direi che il pericolo è qualcosa che hai già affrontato.", 0xba8dc721, 0xaac27949, 0x6fcc5bd2, nil, 0x93151f63, "...m." },
  [3763] = { "In aiuto dell'arcidruido Staghelm", "Parla con l'arcidruido Fandral Staghelm, a Darnassus.", "Scusami, {class}, ma vorrei solo un momento del tuo tempo, se possibile.\n\nIl ⟦Cenarion Circle=Circolo Cenariano⟧ di Darnassus cerca avventurieri esperti come te, che lo aiutino in un progetto di ricerca d'importanza vitale. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che l'arcidruido Fandral Staghelm.\n\nTi prego, se ti interessa, parla direttamente con lui all'⟦Cenarion Enclave=Enclave Cenariana⟧, nel cuore di Darnassus.", nil, "Ebbene, {class}... visto che ti hanno detto che sono io stesso a guidare questa ricerca, sei ovviamente venut<o/a> il più in fretta possibile.\n\nOra che sei qui, assicurati di prestare attenzione la prima volta che ti spiego i dettagli: non ho alcuna intenzione di ripetermi.", 0x683edaeb, 0xf466e7fe, 0x53a106de, nil, 0x0de267fb, "...m." },
  [3764] = { "⟦Un'Goro Soil=Terreno di Un'Goro⟧", "Porta 20 campioni di ⟦Un'Goro Soil=Terreno di Un'Goro⟧ a Jenal, all'⟦Cenarion Enclave=Enclave Cenariana⟧ di Darnassus.", "Si dice che il suolo del ⟦Un'Goro Crater=Cratere di Un'Goro⟧ sia ricco di potenti proprietà magiche. Voglio distinguere i fatti dalle falsità: addentrati nelle terre selvagge di Un'Goro e procurati abbastanza campioni di qualità per proseguire il nostro studio.\n\nForse pensi che i compiti di raccolta siano al di sotto di te; un simile atteggiamento non ti procura la simpatia né mia né del ⟦Cenarion Circle=Circolo Cenariano⟧. Porta i campioni a Jenal, che di sicuro sta perdendo tempo qui fuori, dietro quest'albero: cerca i mucchi di terra. Della logistica si occupa lui, non io.", "Ah sì, la terra. L'arcidruido vuole venti carichi per ogni avventuriero, e venti carichi avrà. Che chi cospira contro di noi resti ai margini della strada!", "Scarica qui il tuo prezioso carico, nobile {class}. Dev'essere stato un bel fardello... non diverso dal fardello che porto io, essendo un visionario. Ecco un compenso per il tuo lavoro, come stabilito dall'arcidruido in persona.\n\nL'arcidruido Staghelm vuole parlarti di nuovo, {name}, ma per il suo prossimo incarico ti sarà d'aiuto una discreta conoscenza dell'Erbalismo. Se però non la possiedi, potrai comunque aiutare il Circolo!", 0x158a6d09, 0x765896a7, 0x8b6a582c, 0x33b60dd8, 0x132cb099, "....." },
  [3765] = { "La corruzione lontano da qui", "Raggiungi Gershala Nightwhisper ad Auberdine.", "⟦Stormwind=Roccavento⟧... un centro brulicante di attività.\n\nHo viaggiato da lontano per cercare aiuto. Si sente spesso dire che coraggiosi avventurieri girano per le strade di questa città.\n\nMio fratello, Gershala, ha bisogno di aiuto a ⟦Darkshore=Rivafosca⟧. Vive ad Auberdine, il villaggio sul mare.\n\nIl viaggio è lungo ed epico. Per questo chiedo l'aiuto di <un/una> {class} espert<o/a> come te.", nil, "Ah, quindi ti ha mandato mio fratello, Argos? Immagino che sarai stanc<o/a> per il viaggio. Ma abbiamo molto di cui parlare.", 0xba7186ed, 0xd3d2f1f5, 0x698b9ad9, nil, 0xb83a2954, "...m." },
  [3781] = { "Ricerche sul morrowgrain", "Porta il ⟦Seed Voucher=Buono per Sementi⟧ dell'arcidruido a Mathrengyl Bearwalker, nell'⟦Cenarion Enclave=Enclave Cenariana⟧ di Darnassus.", "Con quello che chiamiamo ⟦Evergreen Pouch=Zaino Sempreverde⟧ abbiamo coltivato semi di Tharlendris nel terreno del ⟦Un'Goro Crater=Cratere di Un'Goro⟧. Questi semi sbocciano in una varietà di erbe potenti e imprevedibili. Una di queste è il morrowgrain, un'erba misteriosa di cui sappiamo poco; intendo svelare questo mistero.\n\nPorta questo a Mathrengyl, al piano di sotto, e ti darà dei semi per cominciare. Se li finisci, dovrai comprarne altri da lui.", "Pace e serenità a te, amico. Sei qui per conto dell'arcidruido in persona, vero?", "Sì, questo buono vale venti pacchetti di semi. Se li finisci, possiamo fornirtene altri. Purtroppo, però, produrre semi di Tharlendris in quantità significative è piuttosto costoso. Per questo il ⟦Cenarion Circle=Circolo Cenariano⟧ chiede a chi ci aiuta di contribuire coprendo parte della spesa.\n\nChi torna con del morrowgrain scopre che la ricompensa offerta dall'arcidruido ripaga ampiamente la spesa.", 0x5cd3af85, 0xe666d2f2, 0x786c2f34, 0x2c0b9166, 0xd45cbd8d, "....." },
  [3782] = { "Ricerche sul morrowgrain", "Porta il ⟦Seed Voucher=Buono per Sementi⟧ a Bashana Runetotem, a ⟦Thunder Bluff=Picco del Tuono⟧.", "Con quello che chiamiamo ⟦Evergreen Pouch=Zaino Sempreverde⟧ abbiamo coltivato semi di Tharlendris nel terreno del ⟦Un'Goro Crater=Cratere di Un'Goro⟧. Questi semi sono sbocciati in una varietà di erbe potenti e imprevedibili. Una di queste è il morrowgrain, un'erba misteriosa di cui sappiamo poco; spero davvero di svelare questo mistero per il Circolo.\n\nPorta questo buono a mia figlia Bashana, e ti darà dei semi perché tu possa aiutarci. Se li finisci, dovrai comprarne altri da lei.", "La pace sia con te, amico. Sei qui per conto dell'arcidruido in persona, vero?", "Sì, questo buono vale venti pacchetti di semi. Se finisci i semi, ne ho altri che posso venderti.\n\nPurtroppo, {name}, produrre semi di Tharlendris in quantità significative è piuttosto costoso. Per questo il ⟦Cenarion Circle=Circolo Cenariano⟧ chiede a chi ci aiuta di contribuire coprendo parte della spesa. Chi torna con del morrowgrain scopre che la ricompensa offerta dall'arcidruido ripaga ampiamente la spesa.", 0x5cd3af85, 0xe58b0883, 0x547a911b, 0x410657db, 0x58f0c3f6, "....." },
  [3783] = { "Ci siamo, yeti?", "Raccogli 10 Pelliccia di Yeti Spessa per Umi Rumplesnicker a ⟦Everlook=Lungavista⟧.", "I miei amici hanno sempre grandi idee. Non ho mai pensato di essere alla loro altezza... fino a oggi! Ho appena disegnato i progetti di qualcosa di grandioso! Se prometti di non dirlo a nessuno, ti svelo il segreto...\n\nCostruirò uno yeti meccanico! I miei amici si spaventeranno a morte quando lo vedranno, e quando si saranno ripresi, so che resteranno a bocca aperta!\n\nPer cominciare mi serve della pelliccia di yeti spessa, quella degli yeti di Cardighiaccio. Mi aiuterai? Li troverai a sud-est.", "Ho un sacco di cose da avviare qui. Portami quelle pellicce il prima possibile, ti prego!", "Queste pellicce sono perfette, {name}. Siamo partiti alla grande!", 0xf5c82ef5, 0x1931bf53, 0xe5571af0, 0x0a62a942, 0xcf7621cb, "....." },
  [3784] = { "In aiuto dell'arcidruido Runetotem", "Parla con l'arcidruido Hamuul Runetotem, a ⟦Thunder Bluff=Picco del Tuono⟧.", "Scusami, {class}, ma vorrei un momento del tuo tempo, se possibile.\n\nIl ⟦Cenarion Circle=Circolo Cenariano⟧ di ⟦Thunder Bluff=Picco del Tuono⟧ cerca avventurieri esperti come te che lo aiutino in un progetto di ricerca di vitale importanza. Non ne conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che Hamuul Runetotem.\n\nTi prego, se ti interessa, parla direttamente con lui sull'⟦Elder Rise=Altura degli Anziani⟧, a ⟦Thunder Bluff=Picco del Tuono⟧.", nil, "Salute, {class}; sono lieto che tu voglia aiutarci nella nostra ricerca. C'è molto da fare, e ti farei un torto se ti dicessi che questo lavoro non è pericoloso. Spero che non ti spaventi... ma, a giudicare dal tuo aspetto, direi che il pericolo è qualcosa che hai già affrontato.", 0xba8dc721, 0xaac27949, 0x6fcc5bd2, nil, 0x93151f63, "...m." },
  [3785] = { "Ricerche sul morrowgrain", "Usa uno ⟦Evergreen Pouch=Zaino Sempreverde⟧ con un Pacchetto di Semi di Tharlendris e due campioni di ⟦Un'Goro Soil=Terreno di Un'Goro⟧ per provare a coltivare campioni di Morrowgrain.\n\nPorta 10 Morrowgrain a Mathrengyl Bearwalker, a Darnassus.", "Ecco il tuo ⟦Evergreen Pouch=Zaino Sempreverde⟧, che ti servirà per usare i semi di Tharlendis. Ti servono anche dei campioni di terreno di Un'Goro da usare come fertilizzante per i semi. Quando hai tutto, usa lo zaino: al resto penserà lui.\n\nQuando avrai abbastanza morrowgrain, portalo qui da me, nell'enclave. Ti prego, non disturbare l'arcidruido: è un uomo molto impegnato, e non ha bisogno di essere disturbato ogni volta che qualcuno torna con un'altra partita di morrowgrain!", "Sì, {name}, hai coltivato del morrowgrain per l'importante ricerca dell'arcidruido? Il lavoro che sta svolgendo per il ⟦Cenarion Circle=Circolo Cenariano⟧ è molto importante, e il tuo aiuto non passerà inosservato!", "Ben fatto, {name}: mi assicurerò di consegnarli all'arcidruido in persona quando ne avrà bisogno. Nel frattempo, accetta questo come segno della gratitudine del Circolo Cenariano.\n\nIl nostro bisogno di morrowgrain è continuo; se vuoi continuare ad aiutarci, torna da me quando avrai coltivato altro morrowgrain per noi.", 0x5cd3af85, 0xcfe1f98d, 0x81f87e3a, 0x859e04b5, 0xbb7b95ba, "....." },
  [3786] = { "Ricerche sul morrowgrain", "Usa uno ⟦Evergreen Pouch=Zaino Sempreverde⟧ con un Pacchetto di Semi di Tharlendris e due campioni di ⟦Un'Goro Soil=Terreno di Un'Goro⟧ per provare a coltivare campioni di Morrowgrain.\n\nPorta 10 Morrowgrain a Bashana Runetotem, a ⟦Thunder Bluff=Picco del Tuono⟧.", "Ecco il tuo ⟦Evergreen Pouch=Zaino Sempreverde⟧, che ti servirà per usare i semi di Tharlendis. Ti servono anche dei campioni di terreno di Un'Goro da usare come fertilizzante per i semi. Quando hai tutto, usa lo zaino: al resto penserà lui.\n\nQuando avrai abbastanza morrowgrain, portalo qui da me, sull'⟦Elder Rise=Altura degli Anziani⟧. Ti prego, non disturbare l'arcidruido: sarà molto impegnato con la ricerca, oltre che con le mille questioni di cui deve occuparsi!", "Sì, {name}, hai coltivato del morrowgrain per l'importante ricerca dell'arcidruido? Le misteriose proprietà del ⟦Un'Goro Crater=Cratere di Un'Goro⟧ diventano più chiare ogni giorno che passa, grazie all'aiuto che ci stai dando.", "Ben fatto, {name}: mi assicurerò di consegnarli all'arcidruido in persona quando ne avrà bisogno. Nel frattempo, accetta questo come segno della gratitudine del Circolo Cenariano.\n\nPer ora, il nostro bisogno di morrowgrain è costante; se vuoi continuare ad aiutarci, torna quando ne avrai coltivato dell'altro.", 0x5cd3af85, 0x779a0170, 0x0af38d1b, 0x7c5db02e, 0x3fc7561d, "....." },
  [3787] = { "La richiesta di Jonespyre", "Parla con Quintis Jonespyre, a Feathermoon Stronghold.", "Scusami, amico...\n\nUn mio collega vorrebbe parlarti della ricerca che stai svolgendo insieme al ⟦Cenarion Circle=Circolo Cenariano⟧. È un druido di nome Quintis Jonespyre, e risiede a Feathermoon Stronghold, a Feralas. Vorrebbe consultarsi con te sul morrowgrain... e gradirebbe molto che questa conversazione non giungesse alle orecchie dell'arcidruido.\n\nSe ti interessa, parla con lui; quando lo farai, tutto ti sarà rivelato, senza dubbio.", nil, "Ti ringrazio di essere venut<o/a>, <stanco/stanca> <viaggiatore/viaggiatrice>! Permettimi di presentarmi: sono Quintis Jonespyre, druido e umile servitore di Malfurion e del ⟦Cenarion Circle=Circolo Cenariano⟧. I miei colleghi (la generale Shandris Feathermoon e il Protectorate, forse hai sentito parlare di noi) e io volevamo parlarti del lavoro che stai svolgendo per Fandral Staghelm a Darnassus.\n\nPrima di andare avanti, vorrei chiederti che la nostra conversazione resti solo tra noi. Se per te non è un problema, possiamo procedere.", 0xb0b67119, 0xf2782e63, 0xaf54904d, nil, 0x8fcfd489, "...m." },
  [3788] = { "La richiesta di Jonespyre", "Parla con Quintis Jonespyre, a Feathermoon Stronghold.", "Scusami, amico...\n\nUn mio collega vorrebbe parlarti della ricerca che stai svolgendo insieme al ⟦Cenarion Circle=Circolo Cenariano⟧. È un druido di nome Quintis Jonespyre, e risiede qui a Feathermoon Stronghold. Vorrebbe consultarsi con te sul morrowgrain... e gradirebbe molto che questa conversazione non giungesse alle orecchie dell'arcidruido.\n\nSe ti interessa, parla con lui; quando lo farai, tutto ti sarà rivelato, senza dubbio.", nil, "Ti ringrazio di essere venut<o/a>, <stanco/stanca> <viaggiatore/viaggiatrice>! Permettimi di presentarmi: sono Quintis Jonespyre, druido e umile servitore di Malfurion e del ⟦Cenarion Circle=Circolo Cenariano⟧. I miei colleghi (la generale Shandris Feathermoon e il Protectorate, forse hai sentito parlare di noi) e io volevamo parlarti del lavoro che stai svolgendo per Fandral Staghelm a Darnassus.\n\nPrima di andare avanti, vorrei chiederti che la nostra conversazione resti solo tra noi. Se per te non è un problema, possiamo procedere.", 0xb0b67119, 0xf2782e63, 0x51236f26, nil, 0x8fcfd489, "...m." },
  [3789] = { "In aiuto dell'arcidruido Staghelm", "Parla con l'arcidruido Fandral Staghelm, a Darnassus.", "Scusami, {class}, ma vorrei solo un momento del tuo tempo, se possibile.\n\nIl ⟦Cenarion Circle=Circolo Cenariano⟧ di Darnassus cerca avventurieri esperti come te, che lo aiutino in un progetto di ricerca d'importanza vitale. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che l'arcidruido Fandral Staghelm.\n\nTi prego, se ti interessa, parla direttamente con lui all'⟦Cenarion Enclave=Enclave Cenariana⟧, nel cuore di Darnassus.", nil, "Ebbene, {class}... visto che ti hanno detto che sono io stesso a guidare questa ricerca, sei ovviamente venut<o/a> il più in fretta possibile.\n\nOra che sei qui, assicurati di prestare attenzione la prima volta che ti spiego i dettagli: non ho alcuna intenzione di ripetermi.", 0x683edaeb, 0xf466e7fe, 0x53a106de, nil, 0x0de267fb, "...m." },
  [3790] = { "In aiuto dell'arcidruido Staghelm", "Parla con l'arcidruido Fandral Staghelm, a Darnassus.", "Scusami, {class}, ma vorrei solo un momento del tuo tempo, se possibile.\n\nIl ⟦Cenarion Circle=Circolo Cenariano⟧ di Darnassus cerca avventurieri esperti come te, che lo aiutino in un progetto di ricerca d'importanza vitale. Non conosco i dettagli, ma posso dirti che a guidare questa ricerca è nientemeno che l'arcidruido Fandral Staghelm.\n\nTi prego, se ti interessa, parla direttamente con lui all'⟦Cenarion Enclave=Enclave Cenariana⟧, nel cuore di Darnassus.", nil, "Ebbene, {class}... visto che ti hanno detto che sono io stesso a guidare questa ricerca, sei ovviamente venut<o/a> il più in fretta possibile.\n\nOra che sei qui, assicurati di prestare attenzione la prima volta che ti spiego i dettagli: non ho alcuna intenzione di ripetermi.", 0x683edaeb, 0xf466e7fe, 0x53a106de, nil, 0x0de267fb, "...m." },
  [3791] = { "Il mistero del morrowgrain", "Porta 10 Morrowgrain a Quintis Jonespyre, a Feathermoon Stronghold.", "Lascia che sia franco con te, {name}. Sono incuriosito, anzi, preoccupato: perché l'arcidruido di Darnassus usa il nome del ⟦Cenarion Circle=Circolo Cenariano⟧, e le risorse del Circolo, per procurarsi enormi quantità di morrowgrain? Sono un ricercatore, e le maledizioni sono la mia specialità. Ho sentito dire che il morrowgrain, nelle giuste condizioni, sprigiona proprietà simili a quelle di altre erbe usate nelle maledizioni primitive.\n\nVoglio saperne di più, e ti chiedo aiuto. Portami dieci morrowgrain e saprò ricompensarti a dovere.", "Mi servono dieci morrowgrain: dovrebbero bastare almeno per avviare la mia ricerca. Senza dubbio ne brucerò parecchi seguendo strade sbagliate, ma la ricerca funziona così.", "Bah, questo morrowgrain mi fa sentire... strano. In nome di Elune, che cosa sta tramando Staghelm con questa roba?\n\nComunque, grazie ancora per il tuo aiuto. Ecco un piccolo pensiero... sai, per l'impegno. La mia ricerca sul morrowgrain richiederà un po' di tempo, e senza dubbio me ne servirà altro. Già che ci sono, potrei prendermi il tempo di vedere se il morrowgrain ha qualche utilizzo alchemico interessante. Eppure, mi sento a disagio anche solo a starci vicino.", 0xd8cf82fd, 0xf7684088, 0x4a5fec1a, 0x216361ab, 0x9f0f22f5, "....." },
  [3801] = { "L'eredità dei ⟦Dark Iron=Ferroscuro⟧", "Parla con Franclorn Forgewright se ti interessa ottenere la chiave maestra della città.", "Salute, {name}. Sono Franclorn Forgewright. Sì, proprio il Franclorn Forgewright a cui si deve il metodo architettonico di Pietrasalda. Nelle tue avventure in questo nostro mondo dilaniato dalla guerra, avrai senz'altro attraversato una delle mie creazioni, o ci sarai salit<o/a> sopra.\n\nProbabilmente ti stai chiedendo perché sono qui e che cosa voglio da te: domande entrambe legittime.\n\nHo bisogno del tuo aiuto, naturalmente. In cambio del tuo aiuto, ti concederò la chiave delle profondità della mia città maledetta.", nil, "Che sia stata l'avidità a condurti qui o un atto di devozione disinteressata, ciò che stai per intraprendere è per il bene di tutti noi.", 0x3b3da85f, 0x0a06140f, 0x0658260b, nil, 0x70085210, "...m." },
  [3802] = { "L'eredità dei ⟦Dark Iron=Ferroscuro⟧", "Uccidi Fineous Darkvire e recupera il grande martello, Ironfel. Porta Ironfel allo Shrine of Thaurissan e ponilo sulla statua di Franclorn Forgewright.", "Troverai Fineous Darkvire oltre il Ring of Law, nella Hall of Crafting. Uccidi quel miserabile cane e recupera Ironfel.\n\nPorta Ironfel allo Shrine of Thaurissan e rimetti il martello al posto che gli spetta: nelle mani della statua eretta in mio onore.\n\nFatto questo, si aprirà lo scomparto in cui ho riposto la chiave maestra. E, cosa ancora più importante, Ironfel resterà per sempre nella mia stretta. Se tentassero di togliere il martello, statua e martello andrebbero in frantumi, perduti per sempre.", "La statua incombe minacciosa sopra di te.", "Il martello scivola saldamente al suo posto, nella stretta dell'imponente monumento ⟦Dark Iron=Ferroscuro⟧. Alla base della statua si apre un minuscolo scomparto. Dentro trovi...", 0x3b3da85f, 0x7dade027, 0x84d5a972, 0x75236cb2, 0x92bd876f, "....." },
  [3821] = { "⟦Dreadmaul Rock=Masso dei Maglioinfame⟧", "Avventurati nelle ⟦Burning Steppes=Steppe Ardenti⟧ e scopri che fine ha fatto Sha'ni Proudtusk.", "Sha'ni è stata mandata a indagare su strane attività rituali degli ogre Rodifuoco nelle ⟦Burning Steppes=Steppe Ardenti⟧, più di tre settimane fa.\n\nGoretooth mi dice che non ha più notizie di nessuno di quel plotone e che è meglio che io lasci perdere e mi concentri sul compito che ho davanti. Ci credi? È mia moglie!\n\nNon posso lasciare il mio posto, {name}, ma devo sapere che fine ha fatto Sha'ni. Va' nelle ⟦Burning Steppes=Steppe Ardenti⟧ e cercala.", nil, "Il mio povero Thal'trak.\n\nAvevamo in programma di andare a vivere con mia madre e mio padre nelle Entroterre, finito il servizio. Ora quei progetti sono andati in fumo!", 0x4b469dbd, 0x5f7281f1, 0x81b81b47, nil, 0x5b741fec, "...m." },
  [3822] = { nil, "Recupera l'⟦Sha'ni's Nose-Ring=Anello da Naso di Sha'ni⟧ da Krom'Grul e riportalo a Thal'trak, a Kargath. Cerca nelle varie grotte e miniere del ⟦Dreadmaul Rock=Masso dei Maglioinfame⟧.", "Tutto il mio plotone è stato catturato, {name}. Sono stati uccisi tutti, tranne me.\n\nIl loro capo, Krom'Grul, voleva tenermi da parte per una specie di rituale.\n\nMi ha incatenata a questo altare e quella bestia mi ha seviziata. Il mio corpo ha smesso di funzionare dopo un'ora di questa tortura. Poi la bestia mi ha strappato dal viso il mio anello nuziale da naso e se l'è infilato al dito. Non avevo mai visto una simile ferocia!\n\nTrova Krom'Grul e uccidilo! Riporta il mio anello a Thal'trak.\n\nE {name}, digli che ci rivedremo... in un'altra vita.", "Hai trovato Sha'ni? Sta bene?", "<Thal'trak crolla.>\n\nVolevamo trasferirci nelle Entroterre. Te l'ha detto? Questa doveva essere la sua ultima missione.\n\n<Thal'trak singhiozza.>\n\nNon lo voglio, {name}. Tienilo, buttalo via, non m'importa! L'anello per me ora non significa niente. Non senza di lei...", 0x72ff97e9, 0xb1056733, 0x6ba1cbac, 0xd0890e0f, 0x91277ed6, "e...." },
  [3823] = { "Spegnere i Rodifuoco", "Uccidi 15 Firegut Ogre-Mage, 7 Firegut Ogre e 7 Firegut Ogre Brute, poi torna da Oralius quando hai finito.", "Dobbiamo colpire i nostri nemici prima che colpiscano noi!\n\nSarò breve, soldato.\n\nGli ogre Rodifuoco delle ⟦Burning Steppes=Steppe Ardenti⟧ sono alleati degli orchi ⟦Blackrock=Roccianera⟧. Lavorano a stretto contatto con quei vili orchi: sorvegliano il ⟦Dreadmaul Rock=Masso dei Maglioinfame⟧, ricco di minerali, e tengono sempre aperte le linee di rifornimento.\n\nLascia il segno, {name}. Paralizza le loro forze e torna da me quando avrai finito.\n\n<Oralius afferra l'aria e mima uno strangolamento.>\n\nTI AMMAZZO, WINKY!", "Non c'è neanche lontanamente abbastanza sangue sulla tua uniforme, soldato!", "Eccellente, soldato! Orchi e ogre barcolleranno per questo colpo per minuti, forse persino per ore!", 0x554f266e, 0xb4439e75, 0xb66dbe20, 0xc3904a24, 0x4c7f645a, "....." },
  [3824] = { "Gor'tesh il Signore dei Bruti", "Trova Gor'tesh, da qualche parte a ovest del ⟦Dreadmaul Rock=Masso dei Maglioinfame⟧. Uccidi Gor'tesh e poi riporta la ⟦Gor'tesh's Lopped Off Head=Testa Mozzata di Gor'tesh⟧ a Oralius, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "Stanno vacillando, te lo dico io! Il nostro prossimo colpo dev'essere decisivo.\n\nIl signore dei bruti, Gor'tesh, deve morire. E soprattutto, la sua testa deve tornare a me, così potrò preparare la terza fase del nostro attacco contro gli ogre Rodifuoco.\n\nTi avverto, soldato: Gor'tesh non comanda dal ⟦Dreadmaul Rock=Masso dei Maglioinfame⟧, ma da una costruzione degli orchi ⟦Blackrock=Roccianera⟧ a ovest del ⟦Dreadmaul Rock=Masso dei Maglioinfame⟧.\n\nI tuoi ordini, quindi, sono semplici. Trova Gor'tesh e tagliagli quella testa grassa. Torna da me quando il lavoro è fatto.\n\nZITTO, WINKY!", "Oh, giorno glorioso! Sei tornat<o/a> con la testa?", "Guardala, soldato. Disgustosa! Quando gli ogre Rodifuoco rimasti vedranno questo grugno grasso infilzato su una picca in cima alla loro montagna, scoppierà un'isteria di massa!\n\n<Oralius sghignazza come un pazzo.>", 0x54d3ea44, 0xcc0b01ae, 0xa6812770, 0xb3a59526, 0x96911f40, "....." },
  [3825] = { "Testa di ogre su una picca = festa", "Prendi la ⟦Gor'tesh's Lopped Off Head=Testa Mozzata di Gor'tesh⟧ e collocala in cima al ⟦Dreadmaul Rock=Masso dei Maglioinfame⟧. Cerca un cumulo di terra soffice in cui piantare la picca.", "Ti resta un'ultima cosa da fare, soldato.\n\nMi sono preso la libertà di infilzare la testa di Gor'tesh su una picca. Adesso devi solo portare questa testa in cima al ⟦Dreadmaul Rock=Masso dei Maglioinfame⟧ e piantarla nel terreno. Fatto questo, guarda quegli ogre codardi scappare per salvarsi la pelle! Quando ti sarai divertit<o/a>, torna da me e ti ricompenserò per tutto il tuo duro lavoro.\n\n<Oralius sembra perdere il contatto con la realtà.>", "Allora? Hai dipinto qualche quadro dell'evento?", "Lavoro eccezionale, soldato! Semplicemente straordinario! Oh, per questo mi daranno la medaglia al valore, ehm, volevo dire che sarai ricompensat<o/a> generosamente!", 0x8a014f90, 0xdb9ec250, 0x54fb7628, 0xf5a6ea7c, 0x57272f80, "....." },
  [3841] = { "Un orfano in cerca di casa", "Parla con Quentin, a ⟦Thousand Needles=Millepicchi⟧.", "Oh, ciao, {name}. Che piacere rivederti. Com'è andato il viaggio a Darnassus?\n\nBe', ti farà piacere sapere che abbiamo fatto parecchi progressi mentre eri via. Abbiamo persino salvato un nido pieno di uova. Purtroppo la madre era morta prima che la raggiungessimo.\n\nDimmi, ne vorresti uno come animale da compagnia? Pare che si schiuderanno presto, quindi avranno bisogno di <un/una> <buon/buona> <padre/madre>. Che ne dici?\n\nSe ti interessa davvero, porta una delle uova a Quentin, alla pista delle corse nelle Distese Salate. Ti dirà di più.", "Ma salve, {class}.\n\nNon lasciarti ingannare da dove mi trovo: non sono davvero qui per le corse... per quanto divertenti possano essere.\n\nIn realtà sono qui a ⟦Thousand Needles=Millepicchi⟧ per scoprire tutto il possibile su quanto questa terra si possa recuperare. È diventata una specie di mia crociata personale: rivitalizzare e rinnovare la zona con terreno nuovo e fertile. Magari scoprirò che c'è una fonte d'acqua qui vicino.\n\nNon dirmi che non hai notato quanto sia strano il passaggio tra Feralas e ⟦Thousand Needles=Millepicchi⟧. Quando è successo, c'era di mezzo una magia insolita.", "Ah, un uovo di drago fatato, e vicino alla maturazione, se non sbaglio. Notevole che tu ne abbia trovato uno, e per giunta in così buone condizioni. Di questi tempi a Feralas se ne vedono di rado. Mi risulta che nella zona ci fossero diversi bracconieri che cercavano di catturarli e ucciderli per molti motivi. Peccato davvero... sono creature così belle, quando diventano adulte.\n\nCome hai fatto a imbatterti in una scoperta simile?", 0x5fb944d9, 0xac2225f9, 0xf0029122, 0x723b29ea, 0x70686f0c, ".....", nil, nil, 0x36604c86, nil, nil },
  [3842] = { "Una breve incubazione", "Porta 2 Elixir of Fortitude a Quentin, a ⟦Thousand Needles=Millepicchi⟧.", "I Moonweaver, eh? Molto interessante. Vorrei che i draghi fatati potessero davvero capire che cosa significa avere quei due che si prendono cura di loro. Sono entrambi molto capaci.\n\nDunque ti hanno dato l'uovo in dono. Be', allora dovresti occupartene tu, per tutto il tempo che vorrai. Sembra quasi pronto a schiudersi, ma dovremmo assicurarci che sia sano e che non abbia subito danni.\n\nMi servono solo due Elixir of Fortitude per un piccolo incantesimo che protegga l'uovo. Il resto dei componenti ce l'ho qui con me.", "Più resto qui, più sono tentato di partecipare a queste corse, {name}. Davvero sconcertante...\n\nHai già trovato gli elisir? Quando potrò dire se l'uovo sarà sano o no, te lo restituirò perché tu lo custodisca finché non sarà pronto a schiudersi.\n\nFammi sapere.", "Splendido. Questi andranno benissimo. Dammi un momento per mescolare i miei componenti e vedremo come se la cava quest'uovo.", 0xe65f357f, 0x8d801f78, 0x781716b8, 0x18629421, 0xebcc26c9, "....." },
  [3843] = { "Il nuovo arrivato in famiglia", "Porta il tuo ⟦Fragile Sprite Darter Egg=Uovo di Drago Fatato Fragile⟧ nelle Entroterre e parla con Agnar Beastamer, ma sbrigati: hai solo 1 ora per trovarlo prima che il piccolo nell'uovo muoia.", "Un esemplare magnifico, {name}. Se questa creatura supera l'incubazione, sarà davvero un animale sano!\n\nC'è un'ultima cosa che ti consiglierei di fare, se intendi andare fino in fondo: va' al ⟦Aerie Peak=Picco dell'Aquila⟧, nelle Entroterre. Lì parla con un nano di nome Agnar Beastamer; è un maestro nell'addestrare animali e dovrebbe saperti guidare nelle ultime fasi dell'incubazione.\n\nMa sbrigati, {name}: quest'uovo è fragile e non durerà a lungo senza le cure adatte.", "Salute, {name}. In che posso esserti utile?", "Bene, bene, bene... Non ne vedevo uno da un'era di draghi. Drago fatato, se non sbaglio... pare della varietà sprite darter. Eccellente, davvero eccellente.\n\nBe', se questo piccoletto deve schiudersi e crescere forte e sano, dovremmo procurargli del cibo. Meno male che me l'hai portato in tempo.", 0xaf971660, 0x005f9120, 0x9ccd4b04, 0xcae6d14e, 0xada97a0a, "....." },
  [3844] = { "È un segreto per tutti", "Cerca nello stagno un indizio su chi possa essere il proprietario di questa zattera distrutta.", "Lungo la riva giace una zattera distrutta. Dato che si tratta solo di un piccolo stagno, non è chiaro come sia finita qui, anche se guardando gli alberi capisci che il livello dell'acqua potrebbe non essere sempre lo stesso.\n\nForse esplorando un po' la zona potresti scoprire altri indizi...", nil, "Sul fondo dello stagno giace uno zaino zuppo d'acqua.", 0x3bc250db, 0x4c34ad92, 0xa109fe23, nil, 0x48822233, "...m." },
  [3845] = { "È un segreto per tutti", "Esamina gli oggetti nello zaino e portali al loro proprietario.", "Afferri lo zaino e lo trascini a riva. Forse, esaminando gli oggetti al suo interno, potresti scoprire qualcosa di più sul suo proprietario.\n\nAl ⟦Marshal's Refuge=Rifugio dei Grant⟧ ci sono alcuni viaggiatori di passaggio. Forse lì potresti saperne di più.", "Ciao. Ti ho già vist<o/a>... vero?", "Oh... Sì, queste cose mi sembrano familiari... be', più o meno...", 0x3bc250db, 0x3b5ff13f, 0x813cc439, 0x66133329, 0x61e3e44d, "....." },
  [3861] = { "COCCODÈ!", "Trova del ⟦Special Chicken Feed=Mangime Speciale per Polli⟧ e torna dalla gallina che hai preso in simpatia. Quando l'hai trovato, rivolgile un /cheer prima di provare a darle il ⟦Special Chicken Feed=Mangime Speciale per Polli⟧.", "«Coc... coc... coc... COCCODÈ!\n\nCoc... coc... coc.»\n\nLa gallina ti guarda e poi comincia a grattare il terreno con le zampe. Ti sembra che stia scrivendo una parola, ma non sai bene quale. Potrebbe essere... S-A-L-D-E-A-N? Prima che tu possa chiederlo, la gallina si volta e torna alle sue faccende.", "La gallina ti fissa con occhi scuri e freddi. Ti aspetta, affamata.\n\n«COCCODÈÈÈ!\n\nCoc... coc... coc.»", "«COCCODÈ!!!»\n\nLa gallina comincia a ingozzarsi del mangime che le hai messo davanti.\n\nDopo un attimo, la gallina si guarda intorno, spaventata. Si agita a disagio avanti e indietro. Che sia incinta? Forse è meglio controllare sotto di lei.", 0x15276154, 0x72531b26, 0xa6190e7e, 0x6aec8435, 0x76e1a259, "....." },
  [3881] = { "La salvezza della spedizione", "Porta una ⟦Crate of Foodstuffs=Cassa di Cibo⟧ e l'⟦Research Equipment=Equipaggiamento Scientifico⟧ a Williden Marshal, nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Non so come tu sia arrivat<o/a> fin qui, ma sei uno spettacolo per gli occhi! Sono Williden Marshal e guido una compagnia di spedizione indipendente. La nostra ultima e più grande impresa è andata incontro a quelli che sembrano innumerevoli disastri, il più grave dei quali è che abbiamo sottovalutato la ferocia del ⟦Un'Goro Crater=Cratere di Un'Goro⟧!\n\nFuggendo dai nostri campi base nelle zone sud-occidentale e nord-orientale del cratere, ci siamo lasciati dietro provviste vitali. Mi sembri abbastanza in gamba: puoi aiutarci a recuperarle?", "Se vogliamo avere qualche possibilità di uscire vivi da qui, ci serve la nostra grossa cassa di cibo. E riavere almeno una parte del nostro equipaggiamento scientifico sarebbe una benedizione in un mare di guai.", "Hai recuperato sia il nostro cibo SIA il nostro equipaggiamento scientifico! Non hai solo salvato la spedizione, hai salvato anche le nostre vite. Io e il resto della squadra non potremo mai ringraziarti abbastanza; grazie a te, forse riusciremo a resistere qui ancora per un po'.\n\nAnche se non abbiamo molto, non ti lascerò certo a mani vuote per l'aiuto prezioso che ci hai dato. Grazie, {name}: hai un amico nella Marshal Expeditions!", 0x2ffaf72d, 0xd8277369, 0xc27d3349, 0xd0aa3c51, 0x40e21d40, "....." },
  [3882] = { "Il gioco delle ossa", "Porta 8 Osso di Dinosauro a Spark Nilminer nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Uno penserebbe che essere il capo scavatore delle Marshal Expeditions voglia dire che mi piace scavare. Ci saranno anche cose peggiori da fare a questo mondo... ma così su due piedi non me ne viene in mente nessuna.\n\nDovevamo scavare nella ⟦Terror Run=Landa del Terrore⟧ (nome FANTASTICO, tra l'altro) in cerca di stegodonti e diemetradonti morti. Be', lì ce ne sono anche un sacco di vivi! Wil e Hol sono ancora fissati con lo studio di questa trappola mortale, quindi ci servono quelle ossa di dinosauro. Detto tra noi, però, anche quelle prese da esemplari vivi andranno benissimo.", "Pensa di me quello che vuoi, ma a loro non importerà se le ossa da studiare vengono da antichi stegodonti e diemetradonti o da quelli che per poco non ci hanno divorati in un boccone mentre cercavamo di montare gli accampamenti. Io sarò contento se ce ne andiamo di qui vivi...", "Eccellente, queste dovrebbero andare bene. E ora, se permetti...\n\nGRAZIE PER AVER SCAVATO TUTTE QUESTE OSSA DAL TERRENO PER NOI SENZA FARE ALCUN MALE ALLE BESTIE DEL POSTO.\n\nChe tu l'abbia fatto davvero o no, non lo voglio sapere. Lasciamo le cose così, d'accordo? Ecco, magari questo ti terrà la bocca chiusa su tutta la faccenda. Qualunque cosa pur di uscire vivi di qui, dico io!", 0x163fb225, 0x0da2635c, 0x5ed6ddc4, 0x1ac4da25, 0x8df00135, "....." },
  [3883] = { "Un'ecologia aliena", "Usa la Fiala di Campioni per prelevare un ⟦Hive Wall Sample=Campione di Alveare⟧ da uno dei vivai degli alveari Gorishi nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧. Cerca le camere con le larve appese.\n\nPorta il ⟦Hive Wall Sample=Campione di Alveare⟧ a Hol'anyee Marshal nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Solo perché abbiamo subito un contrattempo, non vuol dire che la ricerca debba fermarsi! Prima di finire qui, stavamo studiando gli insetti Gorishi nella parte meridionale del cratere. La loro presenza è estranea all'ecologia di Un'Goro, e vogliamo scoprire perché.\n\nNella loro rete di alveari devono esserci dei vivai di larve. Puoi riconoscerli dalle larve appese. Usa questa fiala per prelevare un campione dalla parete dell'alveare vicino a uno qualsiasi dei vivai. Riportamelo perché possa studiarlo, ma fa' attenzione!", "Hai il campione dell'alveare Gorishi da farmi studiare, {name}?", "Sì, questo andrà benissimo. Sei stat<o/a> di grande aiuto... Vorrei poterti dare di più, ma essere praticamente bloccati in mezzo a una terra selvaggia limita parecchio ciò che posso darti. Ma sta' pur cert<o/a>: la ricerca svolta qui non sarebbe stata possibile senza il tuo aiuto!", 0xcf01b983, 0x1d4c9802, 0xe8755f09, 0x7d3d682e, 0xa95770c0, "....." },
  [3884] = { "Il diario di Williden", "Riporta il diario a Williden Marshal, da qualche parte nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Hai trovato un diario malridotto. Alcune parti sono ancora leggibili, e un certo Williden Marshal ne rivendica la proprietà. Se il diario è attendibile, Williden si trova da qualche parte nella zona settentrionale del Cratere; secondo il diario, lui e i suoi compagni hanno cercato riparo in alto, lontano dalle bestie feroci del Cratere, dopo che i loro accampamenti erano stati travolti.", "Salve! Io e i miei compagni siamo felici di vedere qui qualche essere vivente che non sia una bestia feroce cresciuta a dismisura! Cosa ti porta nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧?", "Ma guarda: il mio diario! Pensavo di averlo perso, come quasi tutto il resto che avevamo portato a Un'Goro. Ti ringrazio di cuore per avermelo riportato!", 0x61668177, 0xb6359148, 0xd6d9ed61, 0xcd2b79cd, 0xbc784e74, "....." },
  [3901] = { "Scuotere i Rattlecage", "Uccidi 12 Rattlecage Skeleton, poi torna dal Sacerdote dell'Ombra Sarvis ad ⟦Deathknell=Albamorta⟧.", "Hai mostrato ai Reietti il tuo potenziale in circostanze normali, {name}: ora vediamo come te la cavi sotto pressione.\n\nGli scheletri Rattlecage, altri servi senza mente del Re dei Lich, sono nemici più duri degli zombi che hai affrontato finora. Ancora una volta, riduci il loro numero e dimostra il tuo valore ai Reietti. Non indugiare: quando hai finito, torna a parlarmi.", "Chi perde tempo in questo compito tanto vale che finisca a vagare senza meta come i nostri fratelli e sorelle caduti nel villaggio. Speriamo che tu te la cavi meglio di loro, eh?", "Ho finito con te, {name}: ti sei dimostrat<o/a> degn<o/a> della libertà che ti è stata data. Molti ti si opporranno per ciò che sei diventat<o/a>, ma sappi che, qualunque cosa tentino contro di noi, siamo liberi e non saremo più incatenati.\n\nPrendi questi e va' per la tua strada. Hai molto da compiere, {class}.", 0x044eea75, 0xcf755d52, 0x04a1073b, 0x9538ef09, 0x9bd22007, "....." },
  [3902] = { "Rovistare ad ⟦Deathknell=Albamorta⟧", "Cerca ad ⟦Deathknell=Albamorta⟧ e nei dintorni 6 ⟦Scavenged Goods=Beni Recuperati⟧ e portali al guardiamorte Saltain.", "Ehi, tu! Se cerchi qualcosa per renderti utile, ascolta bene!\n\nCi servono reclute appena uscite dalla terra che vadano ad ⟦Deathknell=Albamorta⟧ a cercare qualsiasi tipo di equipaggiamento utile. Molto probabilmente sarà in pile di casse. Presto si risveglieranno altre reclute, e se non vogliamo che vadano in giro nude faremo meglio a metterci a rovistare!\n\nForza, al lavoro, miserabile sacco d'ossa! Non ricompenso chi non si dà da fare.", "Sei riuscit<o/a> a recuperare qualcosa di utile per noi? Non c'è vergogna nel riutilizzare ciò che altri hanno buttato via. Nessuno ci regalerà niente: noi Reietti ci arrangeremo da soli!", "Ottimo lavoro, {name}, lo sapevo che non eri un<o/a> buon<o/a> a nulla. Ecco, prendi uno degli oggetti migliori che ho trovato tra quelli raccolti finora.", 0xaae13cb4, 0x229db0af, 0x9da89248, 0x3376988f, 0xbaaab0ef, "....." },
  [3903] = { nil, "Parla con Milly Osworth.", "Ti sei dimostrato un {class} affidabile, {name}. Affidabile, e senza paura di sporcarti le mani, eh?\n\nHo un'amica, Milly Osworth, che è nei guai. È con il suo carro dall'altra parte dell'abbazia, vicino alla stalla. Sono sicuro che un paio di mani come le tue le farebbero comodo.", nil, "Oh, è stato il vicesceriffo Willem a dirti di parlare con me? È un uomo coraggioso e sempre pronto ad aiutare, ma i suoi doveri lo tengono bloccato all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧ e temo che il problema che ho oggi vada oltre le sue possibilità.\n\nForse tu puoi aiutarmi?", 0xe1f36bcd, 0xf258ab38, 0x7ad88966, nil, 0xcb7f07d4, "e..m." },
  [3904] = { "Il ⟦Milly's Harvest=Raccolto di Milly⟧", "Porta 8 casse di ⟦Milly's Harvest=Raccolto di Milly⟧ a Milly Osworth, all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Una banda di briganti, i Defias, si è stabilita nelle ⟦Northshire Vineyards=Vigne della Contea del Nord⟧ mentre facevo la vendemmia! L'ho riferito alle guardie della ⟦Northshire=Contea del Nord⟧ e mi hanno assicurato che se ne sarebbero occupate, ma... temo per il mio raccolto d'uva! Se non me la rubano i Defias, ho paura che la calpestino le nostre guardie quando inseguiranno quei delinquenti.\n\nTi prego, devi aiutarmi! Ho raccolto quasi tutta l'uva nei secchi, ma li ho lasciati nelle vigne a sud-est.\n\nPortami quelle casse! Salva il mio raccolto!", "Hai il mio raccolto, {name}?", "Oh, grazie, {name}! Hai salvato il mio raccolto! E spero che tu abbia fatto capire a qualcuno di quei Defias che qui non possono combinare guai.\n\nDi questi tempi avremo anche poche guardie, ma siamo fortunati ad avere eroi come te a proteggerci!", 0xb7c26a3d, 0x92647f37, 0x0fa99512, 0x44af6d31, 0xbc754155, "....." },
  [3905] = { "⟦Grape Manifest=Bollettino dell'Uva⟧", "Porta il ⟦Grape Manifest=Bollettino dell'Uva⟧ a fratello Neals, nell'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Ora che il mio raccolto è salvo, porta questo ⟦Grape Manifest=Bollettino dell'Uva⟧ a fratello Neals. Gestisce le scorte di cibo e bevande della ⟦Northshire=Contea del Nord⟧, e sono sicura che sarà felicissimo di sapere che ha uva fresca.\n\nTroverai fratello Neals nell'abbazia, sul campanile... dove gli piace assaggiare il suo vino.", "Sembri di ottimo umore! Vieni! Siediti e bevi qualcosa!", "Vediamo un po'...\n\nOh, cielo! L'uva di Milly è salva! Quando mi ha detto che dei briganti avevano invaso le sue vigne ho quasi perso la speranza, ma la mia fede nella Luce non ha vacillato!\n\nE grazie al tuo coraggio ora abbiamo uva per altro vino! Che la Luce ti benedica, {name}, e ti protegga!", 0x46e6ddee, 0x54a8efd7, 0x7e4adc7b, 0x920c46b4, 0x8ad49c5d, "....." },
  [3906] = { "Disarmonia della fiamma", "Raggiungi la cava nel ⟦Blackrock Mountain=Massiccio Roccianera⟧ e uccidi Overmaster Pyron. Torna da Thunderheart quando avrai portato a termine questo incarico.", "Gli anziani hanno percepito un turbamento tra gli elementi. I nani ⟦Dark Iron=Ferroscuro⟧ hanno evocato nel nostro mondo uno spirito immondo che minaccia di affliggere le nostre terre con una siccità eterna. Questa disarmonia della fiamma va indagata.\n\nRaggiungi il ⟦Blackrock Mountain=Massiccio Roccianera⟧ e, attraverso il Chasm of Flame, entra nella cava. È lì che troverai questo signore del fuoco: Overmaster Pyron.\n\nPoni fine a questo sconvolgimento e torna da me.", "Gli elementi sono ancora in subbuglio, {name}.", "Non può essere... non deve essere. La distruzione di Pyron ha solo sollevato un velo. Nelle profondità di ⟦Blackrock=Roccianera⟧ si cela una fonte di corruzione molto più insidiosa.", 0x12c28708, 0x0cb7f2a4, 0x72589669, 0x602e93ef, 0x99670efd, "....." },
  [3907] = { "Disarmonia del fuoco", "Entra nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e trova Lord Incendius. Uccidilo e porta a Thunderheart qualunque fonte di informazioni tu riesca a trovare.", "Sento il sapore della corruzione nell'aria che ti circonda, {name}. C'è un altro, nascosto nelle profondità di ⟦Blackrock=Roccianera⟧, che controlla questa corruzione.\n\nIl vento e la terra gridano il suo nome: lord Incendius... ma qualcuno... qualcosa... comanda questo essere. Lui è solo un emissario.\n\nTrovalo e scopri dove si nasconde il suo padrone. Torna da me quando avrai raccolto queste informazioni.", "Presto le fiamme travolgeranno queste terre. Affrettati, {name}!", "<Thunderheart stringe la ⟦Tablet of Kurniya=Tavoletta di Kurniya⟧.>\n\nRagnaros... qui...\n\nGli anziani avevano ragione a temere la corruzione che emana dal ⟦Blackrock Mountain=Massiccio Roccianera⟧. Un generale degli Dei Antichi! NEL NOSTRO MONDO! Dobbiamo riconsiderare la nostra posizione qui a Kargath. Dobbiamo decidere se restare a combattere o fuggire per paura di una nuova Separazione.\n\nDiffida da ogni ulteriore esplorazione del ⟦Blackrock Mountain=Massiccio Roccianera⟧, {name}. Un male ben più grande di qualunque cosa esista in questo mondo dimora in quelle profondità infuocate.", 0x179734dd, 0x14a0125f, 0xd13aa2b5, 0x89659896, 0xf5b4afe0, "....." },
  [3908] = { "È un segreto per tutti", "Porta la spada di Linken a Donova Snowden a ⟦Winterspring=Fontefredda⟧.", "Vedi, non ho idea di come sia finito qui. Nessuno lo sa davvero: è un segreto per tutti! Proprio non riesco a ricordare niente...\n\nPerò questi oggetti che mi hai portato... Mi sta tornando in mente qualcosa.\n\nLa mia spada. Dovrei rafforzarla in qualche modo, ma non so proprio perché. Mi spiace non poterti dire di più, ma davvero non me lo ricordo!\n\nComunque, so dove puoi portarla: da Donova Snowden, a ⟦Winterspring=Fontefredda⟧. La troverai vicino alle sorgenti calde. Lei può temprare la spada nelle vasche che ci sono lì.", "Bene, bene... Così Linken si è finalmente deciso a mandarmi la sua spada.", "Be', certo che posso temprare questa spada. Mentre lavoro, puoi spiegarmi perché Linken ci ha messo tanto a farmela avere. Di solito non è uno che dimentica le cose...", 0x3bc250db, 0x967007ba, 0x7ca1e461, 0x92bb2dab, 0x48bc10c9, "....." },
  [3909] = { "L'⟦Videre Elixir=Elisir Videre⟧", "Cerca Gregan Brewspewer nel nord di Feralas. Scopri da lui come ottenere l'⟦Videre Elixir=Elisir Videre⟧, poi torna da Donova Snowden a ⟦Winterspring=Fontefredda⟧.", "Allora, che cos'è questa storia? Linken... HA DIMENTICATO?\n\nOh, capisco... Ha perso la memoria...\n\nBe', ecco la sua spada. Però non è completa. Conosco chi può finirla, ma... parlare con lui potrebbe rivelarsi difficile.\n\nAscolta, conosco qualcuno che potrà aiutarti. È troppo lungo da spiegare adesso, ma devi procurarti in qualche modo un ⟦Videre Elixir=Elisir Videre⟧. L'unico che conosco che possa aiutarti in questo è Gregan Brewspewer. È difficile da rintracciare, ma l'ultima volta che ne ho avuto notizia era accampato nelle terre selvagge di Feralas.", "Già di ritorno?", "Mi serve una fiala per assicurarmi che sia davvero l'elisir... Sì... È proprio questo.", 0x2cdfc19c, 0x6fde17bf, 0xfc8b3a73, 0x721001d5, 0xa88964c5, "....." },
  [3911] = { "L'ultimo elemento", "Raggiungi i ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e recupera 10 ⟦Essence of the Elements=Essenza degli Elementi⟧. Il tuo primo istinto è di cercare tra i golem e i loro costruttori. Ricordi anche che Vivian Lagrave ha borbottato qualcosa sugli elementali.", "C'è lavoro per chi si avventura nelle profondità, {name}.\n\nI Ferroscuro sono diventati maestri nella creazione di golem estremamente potenti.\n\nI primi rapporti delle nostre spie indicano che i nani usano una fonte di energia unica per dare alle loro creazioni un potere distruttivo senza pari.\n\nImmagina cosa potremmo fare con i nostri abomini se mettessimo le mani su questa essenza degli elementi! Metti a soqquadro quella città se serve, ma non tornare finché non avrai trovato l'essenza! Il compenso varrà il rischio.", nil, nil, 0x19b2e88f, 0xfd70e576, 0xf6bdad3c, nil, nil, "...mm" },
  [3912] = { "Appuntamento al cimitero", "Va' al cimitero fuori ⟦Gadgetzan=Meccania⟧ e usa l'⟦Videre Elixir=Elisir Videre⟧. Segui il resto delle istruzioni di Donova per trovare Gaeriyan.", "Questo elisir ti permetterà di parlare con qualcuno che normalmente non riusciresti nemmeno a vedere...\n\nPorta l'Elisir Videre, insieme alla spada di Linken, al cimitero appena fuori ⟦Gadgetzan=Meccania⟧, a Tanaris. Una volta lì, bevi la pozione. I risultati potrebbero sorprenderti parecchio, ma non allarmarti.\n\nNella tua «altra» forma, dirigiti dritto a nord finché non raggiungi le montagne. Troverai colui con cui devi parlare in una delle fenditure della roccia. Si chiama Gaeriyan.\n\nRicorda, ti parlerà solo in quella forma...", nil, "È passato molto tempo da quando qualcuno è venuto a parlare con me...", 0xd4eb2ee9, 0xfe910951, 0x76c74a88, nil, 0xc5e80199, "...m." },
  [3913] = { "Una situazione grave", "Resuscita, poi cerca la lapide che Gaeriyan ti ha detto di trovare.", "Se torni al cimitero, {name}, troverai una lapide... Non una lapide qualsiasi: questa spiccherà fra le altre. Custodisce dei segreti.\n\nSpingi la pietra e scoprirai questi segreti...", "Questa dev'essere la lapide di cui parlava Gaeriyan...", "Spingi con decisione la pietra, che scivola via rivelando una piccola cavità sottostante.\n\nPosando la spada di Linken nella cavità, ti accorgi che ci entra alla perfezione...", 0x644bf249, 0xdd68d1c4, 0xc9be6d34, 0x0620b77a, 0x6e8e34a6, "....." },
  [3914] = { "La spada di Linken", "Consegna la ⟦Linken's Superior Sword=Spada Superiore di Linken⟧ a Linken nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Dopo un forte lampo di luce, riesci di nuovo a raccogliere la spada. Si è trasformata!", "Oh! Mi ricordo di te! Tu sei... No, non dirmelo!", "La mia spada... È finita!\n\nOra, se solo riuscissi a ricordare perché mi serviva...\n\nEcco, lascia che almeno ti paghi per il tuo lavoro.", 0x78d825d5, 0x1e373f37, 0xcacff99b, 0xc732a45b, 0xc86f7993, "....." },
  [3921] = { nil, "Porta il ⟦Broken Samophlange=Samoflago Rotto⟧ a Wenikee Boltbucket.", "Credo di aver rotto quel samoflago. Non va bene, perché ne ho già parlato con alcuni colleghi di Undermine ed erano molto incuriositi. Dobbiamo trovare un modo per aggiustarlo!\n\nPorta il samoflago rotto a Wenikee Boltbucket, appena a sud di Mor'shan Rampart, l'avamposto dell'Orda tra le ⟦Barrens=Savane⟧ e ⟦Ashenvale=Valtetra⟧. È molto sveglia e curiosa. Scommetto che, se le mostri il samoflago, coglierà al volo l'occasione di ripararlo.", "Sono molto impegnata con il mio lavoro, {class}. A meno che tu non abbia qualcosa per me, sarebbe meglio che te ne andassi...", "Oh, e questo cos'è? Un samoflago, dici? E che cos'è un samoflago??\n\nAh... ma guarda come si muove quando lo maneggi. E dentro si sente il rumore di ingranaggi complicati. Oh, accidenti! Voglio ripararlo e vedere cosa fa, tu no??", 0x60e1e274, 0x7bdd885e, 0x53dfcdc8, 0xa50b6b78, 0xec4e6f32, "e...." },
  [3922] = { nil, "Porta 15 Cuscinetto a Wenikee Boltbucket, nelle ⟦Barrens=Savane⟧.", "Voglio riparare questo samophlange, ma per farlo mi servono un po' di materiali. Ho finito i nugget slug calibro diciassette virgola cinque e me ne serviranno un bel po' per il lavoro che mi aspetta.\n\nIl posto più vicino dove trovarli è la ⟦Sludge Fen=Palude Fangosa⟧, a est. La ⟦Venture Company=S.P.R. & Co.⟧ di solito li tiene nei secchi degli attrezzi. Va' alla ⟦Sludge Fen=Palude Fangosa⟧ e guarda nei secchi degli attrezzi che trovi lì, poi torna da me quando avrai raccolto abbastanza nugget slug.", "Hai i nugget slug, {name}? Sto tenendo d'occhio questo samophlange e non vedo l'ora di metterci le mani.", "Grande, li hai presi! Ora posso mettermi al lavoro...", 0x048fd5a7, 0x60a82d68, 0x9253461d, 0xaa34b2e5, 0x1136f9bf, "e...." },
  [3923] = { nil, "Porta il ⟦Broken and Battered Samophlange=Samoflago Rotto e Danneggiato⟧ a Rilli Greasygob, a Orgrimmar.", "Be', non ha funzionato. Ho messo qualche indicatore in più sul samoflago per misurarne l'integrità strutturale, e segnano l'integrità al minimo storico. Potrei aggiungere altri quadranti e magari una leva o due per provare a ripararlo, ma... credo che peggiorerei solo le cose.\n\nDovresti portare il samoflago a Rilli Greasygob. Lavorava per la ⟦Venture Company=S.P.R. & Co.⟧: se qualcuno sa come ripararlo, è Rilli.\n\nLo trovi al Nogg's Machine Shop di Orgrimmar, nella ⟦Valley of Honor=Valle dell'Onore⟧.", "Attent<o/a> alla testa! Non voglio che mi intralci il lavoro!", "Cos'è questo? Ma è un samoflago! Dove l'hai preso? Sei andat<o/a> a ficcare il naso nei possedimenti della ⟦Venture Company=S.P.R. & Co.⟧ nelle ⟦Barrens=Savane⟧?\n\nDevi essere molto coraggios<o/a>, o molto stupid<o/a>.", 0x4f8af447, 0x451916dc, 0xf87c0604, 0xe6681672, 0xdb24502b, "e...." },
  [3924] = { "⟦Samophlange Manual=Manuale per Samoflago⟧", "Porta il ⟦Samophlange Manual=Manuale per Samoflago⟧ a Rilli Greasygob, a Orgrimmar.", "Credo di poter riparare il samoflago, ma prima mi serve il manuale d'uso. Quando lavoravo per la ⟦Venture Company=S.P.R. & Co.⟧ avevo un rivale, il capo Copperplug, che custodiva gelosamente i segreti del samoflago e ne rivelava solo qualche briciola a chi godeva della sua fiducia. Io non ero tra quei pochi fortunati...\n\nIl capo Copperplug stava alla ⟦Boulder Lode Mine=Miniera di Pietravera⟧, nelle ⟦Barrens=Savane⟧ nord-orientali. Prendigli il manuale, e se ne ha dato qualche pagina a qualcuno, dovrai recuperare anche quelle.", "Hai il manuale?", "Hai preso il manuale! Non vedo l'ora di leggerlo e scoprire come riparare il samoflago! Ho parlato con Sputtervalve a ⟦Ratchet=Porto Paranco⟧: voleva ringraziarti per l'aiuto e ricompensare i tuoi sforzi.\n\nAnch'io voglio ringraziarti, e se mai riuscirò a riparare questo affare te lo farò sapere...", 0x414249b4, 0x7dc1529a, 0xbe65b209, 0xfd8a38a1, 0xd5013a6b, "....." },
  [3941] = { "L'aiuto di una gnoma", "Trova J.D. Collie nella grotta al ⟦Marshal's Refuge=Rifugio dei Grant⟧.", "Pensa... Pensa... So che sono venuto qui per qualcosa di importante...\n\nHo un'idea, {name}. Nella grotta laggiù c'è una gnoma di nome J.D. che è stata molto gentile con me quando sono arrivato qui. Forse, nel mio stato confuso, potrei averle detto qualcosa.\n\nPerché non vai a chiederle se sa qualcosa? Oh, ma fa' attenzione: armeggia sempre con quei pazzi cristalli luminosi che ho visto nel cratere. Non so proprio cosa stia combinando là dentro!", nil, "Resta dove sei solo per un momento... Sto provando una nuova combinazione di cristalli...", 0x40816cd9, 0xfd9339a6, 0x646068c0, nil, 0xc7a0f8a8, "...m." },
  [3942] = { "La memoria di Linken", "Trova Eridan Bluewind nel ⟦Felwood=Vilbosco⟧ meridionale.", "Oh... Linken? Sì, è un tipo buffo. Quando è arrivato qui borbottava ogni genere di cose strane. Probabilmente ha preso una bella botta in testa, immagino.\n\nPerò una cosa che ha detto mi è rimasta impressa: che stava costruendo una specie di totem; diceva che doveva parlare con un certo Eridan Bluewind... in un posto chiamato ⟦Felwood=Vilbosco⟧, credo?\n\nDubito che adesso possa dirti molto, però. Se vuoi saperne di più, forse dovresti cercare Eridan tu stess<o/a>.", nil, "Salve, {class}. Posso aiutarti in qualche modo?", 0xb545690b, 0x4a17c137, 0x47f4f6e6, nil, 0x0fd9739c, "...m." },
  [3961] = { "L'avventura di Linken", "Porta il ⟦Silver Totem of Aquementas=Totem di Aquementas d'Argento⟧ a Linken, al ⟦Marshal's Refuge=Rifugio dei Grant⟧.", "E pensare che per tutto questo tempo Linken era venuto qui per liberarci di Fiammafulgida... Sembra un tipo così normale, ma ho notato che non gli interessa per niente nessuno dei miei esperimenti o congegni, come invece interesserebbe alla maggior parte degli gnomi. Dev'essere un vero guerriero nell'animo.\n\nPortagli il totem. Vediamo se lo aiuta a ricordare perché è venuto qui.", "Ciao di nuovo, {name}!", "J.D. ti è stato d'aiuto?", 0xe96fc353, 0x37cbdaf9, 0x77ae9d2a, 0xb9979763, 0x9e32cb12, "....." },
  [3962] = { "È pericoloso andare da soli", "Raggiungi il ⟦Fire Plume Ridge=Rilievo del Magma Colante⟧, a sud del ⟦Marshal's Refuge=Rifugio dei Grant⟧.\n\nTrova Fiammafulgida e usa il totem per rimuovere la sua aura protettiva. Una volta sconfitto, prendi la ⟦Golden Flame=Fiamma Dorata⟧ dalla grotta.", "{name}, finalmente ricordo... Sono venuto qui per combattere Fiammafulgida. Ero in viaggio, e questa doveva essere l'ultima tappa.\n\nMa l'eroe non sono più io... Sei tu. Dopo tutto quello che hai fatto, sei tu a dover portare a termine questa impresa, non io.\n\nFiammafulgida custodisce un manufatto chiamato ⟦Golden Flame=Fiamma Dorata⟧. Dà un potere più vasto di qualunque altro io abbia mai conosciuto, ed è pericoloso nelle mani di chi ha un cuore malvagio.\n\nFaresti bene a portare altri con te: è pericoloso andare da soli. Prendilo come un mio consiglio.", "Fiammafulgida è quasi invincibile dietro l'aura che ha creato usando la ⟦Golden Flame=Fiamma Dorata⟧. Solo tu hai il potere di rimuoverla con il ⟦Silver Totem of Aquementas=Totem di Aquementas d'Argento⟧.", "Grazie, {name}.\n\nLa ⟦Golden Flame=Fiamma Dorata⟧ sarà riportata nella mia terra natale, dove potrà essere protetta e non sarà mai più usata per il male.\n\nSenza di te, non avrei ancora idea di chi sono! Visto che hai fatto tanto per me, vorrei che avessi qualcosa di speciale...\n\nScegli quello che preferisci!", 0x9d699a86, 0xa69128f0, 0xd9c5c47b, 0xf5ce54e8, 0x6e1f34a9, "....." },
  [3981] = { "Il comandante Gor'shak", "Trova il comandante Gor'shak nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧.\n\nRicordi che il rozzo disegno dell'orco aveva delle sbarre tracciate sopra il ritratto. Forse dovresti cercare una specie di prigione.", "Povero Gargal... non l'ha nemmeno vista arrivare. BAM! La freccia gli si è piantata dritta in cima alla testa. Non era un genio nemmeno prima, ma adesso...\n\n<Galamav fa una smorfia.>\n\nQuando abbiamo estratto la freccia, abbiamo notato un biglietto arrotolato legato all'asta. Sopra c'era il rozzo disegno di un orco dietro le sbarre, con la firma del comandante Gor'shak.\n\nSe è ancora vivo nei Sotterranei, dovrai trovarlo.\n\nUna trappola, dici? Ma va', zoccoli addormentati! È per questo che ci vai tu!", nil, "Non abbiamo molto tempo. Ascolta attentamente, {race}. Ciò che devo dirti è riservato e solo per le tue orecchie.", 0x8c469204, 0xa1275b64, 0xdcabb55c, nil, 0x9dc26c99, "...m." },
  [3982] = { "Che cosa sta succedendo?", "Difendi Gor'shak.", "Sono stato mandato qui sotto l'egida di Thrall. Credi davvero che questi buffoni potessero catturarmi? Mi sono lasciato catturare per raccogliere informazioni.\n\n<Gor'shak sussurra.>\n\nLa principessa di ⟦Ironforge=Forgiardente⟧ è stata rapita dall'imperatore Thaurissan. La principessa Bronzebeard è proprio in questa città! Scommetto che al vecchio Magni si è quasi fermato il cuore quando ha saputo la notizia.\n\n<Gor'shak ride.>\n\nSssh! Senti? Arrivano le guardie! DIFENDITI!", "Difenditi, stolto!", "C'è mancato poco. Si sono accorti della tua presenza... ne arriveranno di sicuro altri.", 0x6bdf65cd, 0xf461bb19, 0xa2f68f6a, 0xcc8ab8cb, 0x99acc367, "....." },
})
